window.PEOPLE=[{"id": "turingai", "section": "ai1", "name": "Alan Turing (as AI's first thinker)", "years": "1912 – 1954", "role": "Asked whether machines can think — see the finale for his full story", "photo": "people/turingai.jpg", "w": 540, "h": 720, "credit": "Elliott &amp; Fry — Public domain, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Alan_turing_header.jpg)", "story": ["Before anyone used the words 'artificial intelligence', Alan Turing had already asked the question. His 1950 paper 'Computing Machinery and Intelligence' opens: 'I propose to consider the question, Can machines think?'", "His full story — codebreaking, the universal machine, and his tragic end — lives in the finale of this site, where his question comes back around."], "facts": ["'Computing Machinery and Intelligence', Mind, 1950"], "sources": [{"title": "Computing Machinery and Intelligence — Wikipedia", "url": "https://en.wikipedia.org/wiki/Computing_Machinery_and_Intelligence"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "mccarthy", "section": "ai1", "name": "John McCarthy", "years": "1927 – 2011", "role": "Named the field 'artificial intelligence'; invented Lisp and pushed time-sharing", "photo": "people/mccarthy.jpg", "w": 622, "h": 720, "credit": "\"null0\" — CC BY-SA 2.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:John_McCarthy_Stanford.jpg)", "story": ["John McCarthy was born in Boston in 1927 to immigrant parents. His father was an Irish Catholic labor organizer; his mother, Ida Glatt, was a Lithuanian Jewish immigrant who worked for a wire service and later as a social worker.", "He was a sickly child, so the family moved to Los Angeles for his health. There, as a teenager, he taught himself mathematics from books near Caltech. When Caltech admitted him in 1944, it gave him advanced standing.", "He earned his PhD in mathematics at Princeton in 1951. While teaching at Stanford he co-edited a book with Claude Shannon called Automata Studies — and noticed its dull title didn't excite anyone. That lesson stuck.", "So when he moved to Dartmouth College and helped organize a summer workshop for 1956, he gave the topic a bold new name: artificial intelligence. Lester Earnest, writing McCarthy's ACM profile, calls it ironic that this careful mathematician's most famous contribution was, in effect, a brand name.", "At MIT from 1958 he and Marvin Minsky started the Artificial Intelligence Project. There he created Lisp, a language built from lists that became the workhorse of AI research for decades. Around 1959 he also came up with 'garbage collection', a way for a program to clean up memory it no longer needs — an idea now in most modern languages.", "He also wrote a memo proposing time-sharing: letting many people use one big computer at once, each feeling they had it to themselves. That idea inspired MIT's CTSS system in 1962 and helped pave the way to networked computing.", "In 1962 he returned to Stanford and built what became the Stanford Artificial Intelligence Laboratory (SAIL), a hothouse of robotics, speech, computer music and early computer-aided design. In 1968 he bet chess master David Levy that a computer would beat him within ten years — and lost the bet.", "He won the Turing Award in 1971 and kept arguing, to the end, that real intelligence needs common-sense reasoning. He died at his Stanford home in October 2011, aged 84."], "facts": ["Coined 'artificial intelligence' for the 1956 Dartmouth workshop", "Created Lisp (1958) and garbage collection (c. 1959)", "Proposed general-purpose time-sharing", "Founded what became SAIL", "ACM Turing Award 1971"], "sources": [{"title": "ACM Turing Award laureate profile — John McCarthy (by Lester Earnest)", "url": "https://amturing.acm.org/award_winners/mccarthy_1118322.cfm"}, {"title": "John McCarthy (computer scientist) — Wikipedia", "url": "https://en.wikipedia.org/wiki/John_McCarthy_(computer_scientist)"}, {"title": "Dartmouth proposal (1955), AI Magazine reprint", "url": "https://ojs.aaai.org/aimagazine/index.php/aimagazine/article/view/1904"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "minsky", "section": "ai1", "name": "Marvin Minsky", "years": "1927 – 2016", "role": "Co-founder of the MIT AI Lab; theorist of 'the society of mind'", "photo": "people/minsky.jpg", "w": 541, "h": 720, "credit": "The original uploader was Sethwoodworth at English Wikipedia. — CC BY 3.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Marvin_Minsky_at_OLPCb_(3x4_cropped).jpg)", "story": ["Marvin Minsky was born in New York City in 1927 and went to the Bronx High School of Science — one grade behind Frank Rosenblatt, who would one day become his great rival.", "He served in the U.S. Navy in 1944–45, then studied mathematics at Harvard and earned his PhD at Princeton in 1954, with John von Neumann on his thesis committee.", "In 1951 he built SNARC, a learning machine of vacuum tubes and motors often called the first artificial neural network. Ironically, he later became the best-known critic of simple neural networks.", "As a young Harvard Junior Fellow he invented the confocal scanning microscope. The idea sat mostly unused until lasers and computers caught up; today it is a standard tool in biology.", "With John McCarthy he founded the MIT AI Laboratory. Minsky built robot hands with touch sensors and a 14-jointed arm, and with Seymour Papert worked on the Logo 'turtle' robot that taught children to program.", "In 1969 Minsky and Papert published Perceptrons, a rigorous book showing what single-layer networks could not do. It is often blamed for the slump in neural-network research; how much it caused that slump, versus reflecting it, is still debated.", "In The Society of Mind (1986) he argued that intelligence emerges from many small 'agents', none intelligent alone. He called words like 'consciousness' suitcase words — so big you can stuff anything into them.", "He received the Turing Award in 1969 and died in Boston in January 2016."], "facts": ["Built SNARC (1951)", "Invented the confocal scanning microscope", "Co-founded the MIT AI Lab", "Perceptrons (1969, with Papert)", "ACM Turing Award 1969"], "sources": [{"title": "ACM Turing Award laureate profile — Marvin Minsky (by Patrick Henry Winston)", "url": "https://amturing.acm.org/award_winners/minsky_7440781.cfm"}, {"title": "Marvin Minsky — Wikipedia", "url": "https://en.wikipedia.org/wiki/Marvin_Minsky"}, {"title": "Society of Mind — Wikipedia", "url": "https://en.wikipedia.org/wiki/Society_of_Mind"}, {"title": "MIT News obituary, 2016", "url": "https://news.mit.edu/2016/marvin-minsky-obituary-0125"}], "uncertain": ["How much Perceptrons caused, rather than reflected, the neural-network funding slump is debated."], "src": "ai-and-quantum"}, {"id": "rosenblatt", "section": "ai1", "name": "Frank Rosenblatt", "years": "1928 – 1971", "role": "Inventor of the perceptron, the first trainable neural network machine", "photo": "people/rosenblatt.jpg", "w": 350, "h": 455, "credit": "AnonymousUnknown author — CC BY-SA 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Frank_Rosenblatt.jpg)", "story": ["In July 1958 the U.S. Office of Naval Research showed off something strange. A five-ton IBM 704 was fed punch cards, and after 50 tries it had taught itself to tell cards marked on the left from cards marked on the right.", "The man behind it was Frank Rosenblatt, a psychologist. Born in 1928, he grew up in New Rochelle, New York, went to the Bronx High School of Science, and earned his PhD in psychology at Cornell. For his dissertation he had already built an 'Electronic Profile Analyzing Computer' to sort personality data.", "His real question was about brains: what is the least a brain needs, physically, to do the amazing things it does? His answer was the perceptron — artificial neurons that guess, and adjust their connections whenever they guess wrong.", "The press went wild. The New York Times headline read 'New Navy Device Learns by Doing', and reported the Navy expected such machines to 'walk, talk, see, write, reproduce itself and be conscious of its existence.' The New Yorker called it 'the first serious rival to the human brain ever devised.'", "He then built the Mark I Perceptron at the Cornell Aeronautical Laboratory in Buffalo: 400 photocells in a 20-by-20 grid as its 'eye', wired to 512 association units, with learning stored in potentiometers turned by electric motors. It is now at the Smithsonian.", "Back in Ithaca he led a lively crew of students on Tobermory, a speech-recognizing perceptron named after a talking cat in a short story. He bought a telescope too big to store, then a house to put it in, and he and his students built an observatory in the yard.", "Minsky, his old schoolmate, doubted the perceptron could ever see or understand language. The two debated in public, and Rosenblatt called Minsky 'the loyal opposition'. After Minsky and Papert's 1969 book Perceptrons, funding faded.", "Rosenblatt drowned while sailing on Chesapeake Bay on his 43rd birthday in 1971. Today his learning rule is recognized as a root of deep learning, and the IEEE created an award in his name in 2004."], "facts": ["Perceptron demo on IBM 704, July 1958", "Mark I Perceptron: 400-photocell 'retina', now at the Smithsonian", "Book: Principles of Neurodynamics (1962)", "IEEE Frank Rosenblatt Award established 2004"], "sources": [{"title": "Cornell Chronicle, 'Professor's perceptron paved the way for AI – 60 years too soon' (2019)", "url": "https://news.cornell.edu/stories/2019/09/professors-perceptron-paved-way-ai-60-years-too-soon"}, {"title": "Perceptron — Wikipedia", "url": "https://en.wikipedia.org/wiki/Perceptron"}, {"title": "Frank Rosenblatt — Wikipedia", "url": "https://en.wikipedia.org/wiki/Frank_Rosenblatt"}, {"title": "Rosenblatt, 'The Perceptron: A Probabilistic Model…', Psychological Review 65 (1958)", "url": "https://doi.org/10.1037/h0042519"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "weizenbaum", "section": "ai1", "name": "Joseph Weizenbaum", "years": "1923 – 2008", "role": "Creator of ELIZA, the first famous chatbot — and an early critic of AI", "photo": "people/weizenbaum.jpg", "w": 490, "h": 720, "credit": "Rochester Institute of Technology — Public domain, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Weizenbaum_1982.jpg)", "story": ["Joseph Weizenbaum was born in Berlin in 1923 to Jewish parents. In January 1936 his family escaped Nazi Germany for the United States.", "He began studying math at Wayne State University in Detroit, then served in the U.S. Army Air Corps as a meteorologist — he had been turned down for codebreaking work because he was classed as an 'enemy alien'.", "After the war he helped build a digital computer at Wayne State, then worked for General Electric on ERMA, the system that introduced the magnetic-ink numbers printed along the bottom of checks.", "In 1963 he joined MIT. In 1966 he published ELIZA, named after Eliza Doolittle in Shaw's Pygmalion. With a script called DOCTOR it mimicked a therapist, mostly by turning your words back into questions.", "He was shocked by how people reacted. Users poured their hearts out to it. Famously, his secretary, who knew it was just a program, asked him to leave the room so she could talk to it in private.", "That shock turned him into a critic. His 1976 book Computer Power and Human Reason argued that even if computers can do something, some decisions — those needing human judgment and care — should not be handed to them.", "In 1996 he moved back to Berlin, near his childhood neighborhood, and died in 2008. Today, our habit of reading understanding into a chatbot is called 'the ELIZA effect'."], "facts": ["ELIZA (1966), written in his own SLIP language", "Book: Computer Power and Human Reason (1976)", "The 'ELIZA effect' is named after his program"], "sources": [{"title": "Joseph Weizenbaum — Wikipedia", "url": "https://en.wikipedia.org/wiki/Joseph_Weizenbaum"}, {"title": "Weizenbaum, 'ELIZA', Communications of the ACM 9(1), 1966", "url": "https://doi.org/10.1145/365153.365168"}, {"title": "ELIZA — Wikipedia", "url": "https://en.wikipedia.org/wiki/ELIZA"}, {"title": "Computer Power and Human Reason — Wikipedia", "url": "https://en.wikipedia.org/wiki/Computer_Power_and_Human_Reason"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "pearl", "section": "ai1", "name": "Judea Pearl", "years": "born 1936", "role": "Taught machines to reason with uncertainty and about cause and effect", "photo": "people/pearl.jpg", "w": 720, "h": 515, "credit": "Better Than Bacon — CC BY 2.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Judea_Pearl_at_NIPS_2013_(11781981594).jpg)", "story": ["Judea Pearl was born in Tel Aviv in 1936 and grew up in Bnei Brak, a town his grandfather helped re-establish. He served in the Israeli army, joined a kibbutz, then studied electrical engineering at the Technion, where he met his wife, Ruth.", "He moved to the U.S. in 1960 and earned a PhD in 1965 on superconducting memories — a kind of current is still called a 'Pearl vortex'. When semiconductor memory wiped out that line of work, he moved to UCLA in 1969 to pursue his real interest: reasoning.", "In the 1970s most AI 'expert systems' used hand-made rules with 'certainty factors'. Pearl thought proper probability would work better. Rule systems, for example, couldn't handle 'explaining away': if the grass is wet and you learn the sprinkler was on, rain becomes less likely.", "His answer was Bayesian networks: diagrams of arrows showing which things directly influence which, plus an efficient way to update beliefs called belief propagation. His 1988 book Probabilistic Reasoning in Intelligent Systems helped turn AI toward probability.", "Then he went further, to cause and effect. Data can show smoking and cancer go together, but not which causes which. His 'do-calculus' gives math for asking what happens if we intervene. He explains it for everyone in The Book of Why (2018).", "His son, journalist Daniel Pearl, was kidnapped and murdered in Pakistan in 2002. Judea and Ruth founded the Daniel Pearl Foundation to promote understanding between cultures.", "He won the 2011 Turing Award and pledged much of the prize money to the foundation and to teaching causal inference."], "facts": ["Invented Bayesian networks and belief propagation", "Developed the do-calculus for causal inference", "ACM Turing Award 2011", "Books: Causality (2000), The Book of Why (2018, with Dana Mackenzie)"], "sources": [{"title": "ACM Turing Award laureate profile — Judea Pearl (by Stuart Russell)", "url": "https://amturing.acm.org/award_winners/pearl_2658896.cfm"}, {"title": "Judea Pearl — Wikipedia", "url": "https://en.wikipedia.org/wiki/Judea_Pearl"}, {"title": "The Book of Why — Wikipedia", "url": "https://en.wikipedia.org/wiki/The_Book_of_Why"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "hinton", "section": "ai2", "name": "Geoffrey Hinton", "years": "born 1947", "role": "Kept neural networks alive through the lean years; 2024 Nobel Prize in Physics", "photo": "people/hinton.jpg", "w": 514, "h": 720, "credit": "Cmichel67 — CC BY-SA 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Geoffrey_Hinton_in_2026.jpg)", "story": ["Geoffrey Everest Hinton was born in Wimbledon in 1947 into a family of scientists. The logician George Boole was his great-great-grandfather, and the family middle name honors a relative after whom Mount Everest was named.", "At Cambridge he tried physiology, physics and philosophy before graduating in experimental psychology in 1970. Feeling none of them explained thinking, he briefly worked as a carpenter.", "In 1972 he went to Edinburgh to study AI and chose a deeply unfashionable topic: neural networks. He later said, 'If you think it's a really good idea and other people tell you it's complete nonsense then you know you are really onto something.'", "With David Ackley and Terry Sejnowski he developed the Boltzmann machine, borrowing tools from physics. With Rumelhart and Williams he co-wrote the 1986 backpropagation paper that revived the field.", "After five years at Carnegie Mellon he left the U.S., partly in opposition to the 'Star Wars' missile-defense program, and moved to the University of Toronto.", "In 2012 his students Alex Krizhevsky and Ilya Sutskever built AlexNet with him. It crushed the ImageNet contest, and Google bought their tiny company, DNNresearch. He worked at Google from 2013 to 2023.", "He shared the 2018 Turing Award with LeCun and Bengio, and the 2024 Nobel Prize in Physics with John Hopfield — only the second person, after Herbert Simon, to win both.", "In May 2023 he left Google, saying he wanted to speak freely about AI's risks, from misinformation and job disruption to the longer-term danger of autonomous systems. Some colleagues share his worries; others, like LeCun, think them overblown."], "facts": ["Co-author of the 1986 backpropagation paper", "Co-inventor of the Boltzmann machine", "Supervised AlexNet (2012)", "Turing Award 2018; Nobel Prize in Physics 2024"], "sources": [{"title": "ACM Turing Award laureate profile — Hinton (by Thomas Haigh)", "url": "https://amturing.acm.org/award_winners/hinton_4791679.cfm"}, {"title": "Geoffrey Hinton — Wikipedia", "url": "https://en.wikipedia.org/wiki/Geoffrey_Hinton"}, {"title": "Nobel Prize in Physics 2024", "url": "https://www.nobelprize.org/prizes/physics/2024/summary/"}, {"title": "ACM 2018 Turing Award announcement", "url": "https://awards.acm.org/about/2018-turing"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "lecun", "section": "ai2", "name": "Yann LeCun", "years": "born 1960", "role": "Inventor of convolutional networks; outspoken AI optimist", "photo": "people/lecun.jpg", "w": 569, "h": 720, "credit": "Jérémy Barande — CC BY-SA 2.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Laura_Chaubard_%26_Yann_Le_Cun_-_2024_(53814052697)_(cropped).jpg)", "story": ["If you deposited a check by machine in the 1990s or 2000s, a descendant of Yann LeCun's work may well have read the handwriting.", "He was born near Paris in 1960, studied engineering at ESIEE Paris, and earned his PhD in 1987 at Université Pierre et Marie Curie, working on an early form of backpropagation. Geoffrey Hinton was his external examiner.", "He spent 1987–88 as a postdoc in Hinton's Toronto group, then joined AT&T Bell Labs. There he developed convolutional neural networks, which slide small learned filters across an image to find edges, then shapes, then whole objects.", "His LeNet networks learned to read handwritten digits, and the check-reading system he helped build was widely deployed by NCR and other companies.", "He joined NYU in 2003 and in 2013 became founding director of Facebook AI Research. In 2018 he shared the Turing Award with Hinton and Bengio, with whom he had met regularly through a Canadian research program.", "LeCun argues that today's chatbots lack an understanding of the physical world, lasting memory and planning, and that fears of AI takeover are exaggerated. In December 2025 he left his role as Meta's chief AI scientist and co-founded Advanced Machine Intelligence Labs to pursue that vision."], "facts": ["Developed convolutional neural networks (LeNet)", "Check-reading system deployed by NCR", "Founding director of FAIR (2013)", "Turing Award 2018", "Co-founded Advanced Machine Intelligence Labs (Dec 2025)"], "sources": [{"title": "Yann LeCun — Wikipedia", "url": "https://en.wikipedia.org/wiki/Yann_LeCun"}, {"title": "LeCun et al., 'Gradient-Based Learning Applied to Document Recognition', Proc. IEEE 1998", "url": "https://doi.org/10.1109/5.726791"}, {"title": "ACM laureate profile — Hinton (LeCun's postdoc)", "url": "https://amturing.acm.org/award_winners/hinton_4791679.cfm"}, {"title": "ACM 2018 Turing Award announcement", "url": "https://awards.acm.org/about/2018-turing"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "bengio", "section": "ai2", "name": "Yoshua Bengio", "years": "born 1964", "role": "Deep learning pioneer; leads the international AI safety report", "photo": "people/bengio.jpg", "w": 597, "h": 720, "credit": "Xuthoria — CC BY-SA 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:ICLR_2025_-_Yoshua_Bengio_02.jpg)", "story": ["Yoshua Bengio was born in Paris in 1964 to parents with roots in Morocco. His mother, Célia Moreno, was an actress, and his father co-ran a Montreal theater company that performed in Judeo-Arabic. The family settled in Montreal.", "He earned his PhD at McGill University in 1991 and did postdocs at MIT and AT&T Bell Labs, then joined the Université de Montréal.", "His lab grew into Mila, now one of the world's largest academic AI institutes. In 2003 his team published a neural language model that learned word meanings as points in space — an ancestor of today's chatbots.", "In 2014 his lab, with Dzmitry Bahdanau and Kyunghyun Cho, introduced 'attention' for translation: letting a network look back at the most relevant words as it writes each new one. Three years later, attention became the heart of the Transformer.", "He shared the 2018 Turing Award with Hinton and LeCun.", "Since around 2023 he has turned to AI safety. At the first AI Safety Summit in November 2023 the UK announced he would lead an international scientific report on the risks of advanced AI. He also launched LawZero, a nonprofit working on safer AI designs."], "facts": ["Founded Mila in Montreal", "Neural probabilistic language model (2003)", "Neural attention for translation (2014, with Bahdanau and Cho)", "Turing Award 2018", "Leads the International AI Safety Report"], "sources": [{"title": "Yoshua Bengio — Wikipedia", "url": "https://en.wikipedia.org/wiki/Yoshua_Bengio"}, {"title": "Bahdanau, Cho & Bengio 2014 — arXiv", "url": "https://arxiv.org/abs/1409.0473"}, {"title": "Bengio et al., 'A Neural Probabilistic Language Model', JMLR 2003", "url": "https://www.jmlr.org/papers/v3/bengio03a.html"}, {"title": "ACM 2018 Turing Award announcement", "url": "https://awards.acm.org/about/2018-turing"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "feifeili", "section": "ai2", "name": "Fei-Fei Li", "years": "born 1976", "role": "Creator of ImageNet; champion of human-centered AI", "photo": "people/feifeili.jpg", "w": 485, "h": 720, "credit": "ITU Pictures — CC BY 2.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Fei-Fei_Li_at_AI_for_Good_2017.jpg)", "story": ["Fei-Fei Li was born in Beijing in 1976 and grew up in Chengdu. When she was 12 her father emigrated to Parsippany, New Jersey; at 16 she and her mother joined him.", "At Parsippany High School she worked weekends at her family's dry-cleaning shop, then went on to study physics at Princeton.", "She earned her PhD at Caltech in 2005. Around 2006 she began to suspect that computer vision was stuck not only because of algorithms, but because computers had seen far too few examples of the world.", "That hunch became ImageNet: eventually more than 14 million images sorted into over 20,000 categories, labeled largely by crowd workers on Amazon Mechanical Turk.", "From 2010 an annual ImageNet challenge measured progress. In 2012, AlexNet's dramatic win showed that deep networks plus big data plus GPUs were a winning recipe.", "She became a Stanford professor, chief scientist of AI at Google Cloud, and co-director of Stanford's Institute for Human-Centered AI. She co-founded AI4ALL to bring more diverse students into AI.", "In 2024 she co-founded World Labs to build 'spatial intelligence' — AI that understands 3D worlds. Her memoir is The Worlds I See (2023)."], "facts": ["Led the creation of ImageNet", "Co-director, Stanford HAI", "Co-founded AI4ALL and World Labs", "Memoir: The Worlds I See (2023)"], "sources": [{"title": "Fei-Fei Li — Wikipedia", "url": "https://en.wikipedia.org/wiki/Fei-Fei_Li"}, {"title": "ImageNet — Wikipedia", "url": "https://en.wikipedia.org/wiki/ImageNet"}, {"title": "Deng et al., 'ImageNet: A Large-Scale Hierarchical Image Database', CVPR 2009", "url": "https://doi.org/10.1109/CVPR.2009.5206848"}, {"title": "Stanford HAI — Fei-Fei Li", "url": "https://hai.stanford.edu/people/fei-fei-li"}], "uncertain": ["Wikipedia reports AMD agreed to acquire World Labs in September 2026; confirm before stating on the site."], "src": "ai-and-quantum"}, {"id": "krizhevsky", "section": "ai2", "name": "Alex Krizhevsky", "years": "birth year not public", "role": "Built AlexNet on two gaming GPUs and set off the deep-learning boom", "photo": null, "w": null, "h": null, "credit": null, "story": ["Alex Krizhevsky is a Canadian computer scientist who, as a PhD student in Geoffrey Hinton's Toronto lab, wrote the code behind one of the most important results in AI history.", "Before AlexNet he created CIFAR-10 and CIFAR-100, small image datasets that students still use to test ideas today.", "Neural networks back then were usually trained on ordinary processors. Krizhevsky wrote highly tuned code to train them on NVIDIA GeForce graphics cards — chips built for video games, but ideal for the endless multiplications neural networks need.", "Motivated by Ilya Sutskever and guided by Hinton, he built AlexNet: a deep convolutional network with about 60 million parameters, trained on just two GPUs, using tricks like 'dropout' to keep it from memorizing.", "In the 2012 ImageNet challenge its top-5 error was about 15.3%. The next-best entry scored about 26.2%. Computer vision switched to deep learning almost overnight.", "The three founded DNNresearch, which Google bought. Krizhevsky left Google in September 2017 to work at the startup Dessa, and has kept an unusually low public profile."], "facts": ["Lead author of AlexNet (NeurIPS 2012)", "Created CIFAR-10/100 datasets", "Top-5 error ~15.3% vs ~26.2% for the runner-up"], "sources": [{"title": "Krizhevsky, Sutskever & Hinton, NeurIPS 2012", "url": "https://papers.nips.cc/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html"}, {"title": "Alex Krizhevsky — Wikipedia", "url": "https://en.wikipedia.org/wiki/Alex_Krizhevsky"}, {"title": "ACM laureate profile — Hinton (AlexNet details)", "url": "https://amturing.acm.org/award_winners/hinton_4791679.cfm"}, {"title": "AlexNet — Wikipedia", "url": "https://en.wikipedia.org/wiki/AlexNet"}], "uncertain": ["Popular 'trained in his bedroom' story not verified; omitted. Birthplace/year not in reliable sources; omitted."], "src": "ai-and-quantum"}, {"id": "sutskever", "section": "ai2", "name": "Ilya Sutskever", "years": "born 1986", "role": "AlexNet co-author, OpenAI co-founder, founder of Safe Superintelligence", "photo": "people/sutskever.jpg", "w": 192, "h": 287, "credit": "Eladkarmel — CC BY-SA 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Ilya_Sutskever_and_Sam_Altman_in_TAU_(cropped).jpg)", "story": ["Ilya Sutskever was born in 1986 to a Russian-Jewish family in Nizhny Novgorod (then Gorky) in the Soviet Union. As a child he moved with his family to Israel and grew up in Jerusalem.", "In eighth grade he began taking classes at the Open University of Israel. At 16 his family moved to Canada, and after only a month of high school he was admitted to the University of Toronto.", "There he joined Geoffrey Hinton's lab and pushed Alex Krizhevsky to build AlexNet, convinced that much deeper networks would win if trained on enough data.", "At Google Brain he co-authored the 2014 'sequence to sequence' paper, which taught networks to read a sentence in one language and write it in another.", "In 2015 he co-founded OpenAI and became chief scientist. Wired reports that soon after the Transformer paper appeared, he suggested researcher Alec Radford work on the idea — leading to the first GPT models.", "In November 2023 he was part of the board that fired CEO Sam Altman. Within days he said he regretted it, and Altman returned.", "He left OpenAI in 2024 and co-founded Safe Superintelligence Inc. with Daniel Gross and Daniel Levy."], "facts": ["Co-author of AlexNet (2012) and seq2seq (2014)", "Co-founder and former chief scientist of OpenAI", "Co-founded Safe Superintelligence Inc. (2024)"], "sources": [{"title": "Ilya Sutskever — Wikipedia", "url": "https://en.wikipedia.org/wiki/Ilya_Sutskever"}, {"title": "Sutskever, Vinyals & Le, 'Sequence to Sequence Learning' — arXiv", "url": "https://arxiv.org/abs/1409.3215"}, {"title": "Steven Levy, '8 Google Employees Invented Modern AI', WIRED, 2024", "url": "https://www.wired.com/story/eight-google-employees-invented-modern-ai-transformers-paper/"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "ng", "section": "ai2", "name": "Andrew Ng", "years": "born 1976", "role": "Co-founded Google Brain; taught AI to millions online", "photo": "people/ng.jpg", "w": 587, "h": 720, "credit": "TechCrunch — CC BY 2.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Andrew_Ng_at_TechCrunch_Disrupt_SF_2017.jpg)", "story": ["Andrew Ng was born in London in 1976 to parents from Hong Kong. He spent his early childhood in Hong Kong, and from 1984 grew up in Singapore.", "He earned a triple major in computer science, statistics and economics at Carnegie Mellon, a master's at MIT, and in 2002 a PhD at Berkeley on reinforcement learning, supervised by Michael I. Jordan.", "As a Stanford professor he argued that neural networks would get much better if trained at much larger scale.", "He co-founded the Google Brain project with Jeff Dean, Greg Corrado and Rajat Monga. A famous result: a network on 16,000 processor cores watched YouTube video frames and learned to recognize cats without ever being told what a cat was.", "In 2012 he and Daphne Koller co-founded Coursera. His machine-learning course drew over 100,000 students, and his online courses have since reached millions.", "He became chief scientist at Baidu in 2014, and later founded DeepLearning.AI, Landing AI and the AI Fund. In 2024 he joined Amazon's board of directors."], "facts": ["Co-founded Google Brain", "'Cat neuron' experiment on 16,000 CPU cores", "Co-founded Coursera (2012)", "Chief scientist at Baidu from 2014"], "sources": [{"title": "Andrew Ng — Wikipedia", "url": "https://en.wikipedia.org/wiki/Andrew_Ng"}, {"title": "Le et al., 'Building High-level Features Using Large Scale Unsupervised Learning' — arXiv", "url": "https://arxiv.org/abs/1112.6209"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "sutton", "section": "ai2", "name": "Richard Sutton", "years": "born 1957 or 1958", "role": "Co-founder of modern reinforcement learning; author of 'The Bitter Lesson'", "photo": "people/sutton.jpg", "w": 710, "h": 720, "credit": "Xuthoria — CC BY-SA 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:SD_2025_-_Richard_Sutton_01_(cropped).jpg)", "story": ["Richard Sutton was born in Toledo, Ohio, around 1957–58 and grew up near Chicago. He studied psychology at Stanford, fascinated by how animals learn from reward.", "In 1978 he began working with Andrew Barto at the University of Massachusetts Amherst. Together they turned 'learning by trial and error' into a precise computer-science problem: reinforcement learning.", "Their key idea, temporal-difference learning, lets a system improve its predictions about the future from its own later predictions, without waiting for the final outcome. Later research found such algorithms help explain dopamine signals in the brain.", "Their textbook Reinforcement Learning: An Introduction (1998) became the standard reference, cited more than 75,000 times.", "After years at GTE and AT&T labs he moved to the University of Alberta in 2003, and worked at DeepMind from 2017 to 2023. He became a Canadian citizen in 2015.", "In 2019 he wrote a short essay, 'The Bitter Lesson': 70 years of AI show that general methods that use more computation beat clever human-built shortcuts. It became a manifesto of the scaling era.", "He and Barto won the 2024 Turing Award. Reinforcement learning powered AlphaGo and is used to fine-tune chatbots. Sutton has publicly called AI 'doomers' out of line."], "facts": ["Co-founded modern reinforcement learning with Andrew Barto", "Temporal-difference learning", "Textbook Reinforcement Learning: An Introduction (1998)", "'The Bitter Lesson' (2019)", "ACM Turing Award 2024"], "sources": [{"title": "ACM 2024 Turing Award announcement", "url": "https://awards.acm.org/about/2024-turing"}, {"title": "Richard S. Sutton — Wikipedia", "url": "https://en.wikipedia.org/wiki/Richard_S._Sutton"}, {"title": "Sutton, 'The Bitter Lesson' (2019)", "url": "http://www.incompleteideas.net/IncIdeas/BitterLesson.html"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "hassabis", "section": "ai2", "name": "Demis Hassabis", "years": "born 1976", "role": "DeepMind co-founder; AlphaGo and AlphaFold; 2024 Nobel Prize in Chemistry", "photo": "people/hassabis.jpg", "w": 540, "h": 720, "credit": "John Sears — CC BY-SA 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Demis_Hassabis,_2024_Nobel_Prize_Laureate_in_Chemistry_7_(cropped).jpg)", "story": ["Demis Hassabis was born in London in 1976. As a boy he was a chess prodigy, reaching a rating of 2300 and captaining England junior teams.", "He finished his A-levels two years early. Cambridge asked him to take a gap year because he was so young, so he joined the game studio Bullfrog Productions. At 17 he co-designed and lead-programmed Theme Park (1994), which sold millions of copies.", "He then studied computer science at Cambridge, founded his own game studio, Elixir, and later earned a PhD in cognitive neuroscience at University College London, studying memory and imagination.", "In 2010 he co-founded DeepMind with Shane Legg and Mustafa Suleyman, with a mission to 'solve intelligence'. Google acquired it in 2014.", "In March 2016 AlphaGo beat Lee Sedol 4–1 in Seoul. Its move 37 in game two looked like a mistake to experts — and turned out to be brilliant.", "DeepMind then tackled a 50-year-old biology puzzle: predicting a protein's 3D shape from its chain of amino acids. AlphaFold 2 essentially solved it in 2020, and DeepMind released predicted structures for over 200 million proteins.", "In 2024 he and John Jumper shared half the Nobel Prize in Chemistry, with David Baker receiving the other half. He was knighted, leads Google DeepMind, and founded Isomorphic Labs to apply AI to drug discovery."], "facts": ["Co-designed Theme Park at 17", "Co-founded DeepMind (2010)", "AlphaGo beat Lee Sedol 4–1 (2016)", "AlphaFold; Nobel Prize in Chemistry 2024"], "sources": [{"title": "Demis Hassabis — Wikipedia", "url": "https://en.wikipedia.org/wiki/Demis_Hassabis"}, {"title": "Silver et al. 2016 — Nature", "url": "https://www.nature.com/articles/nature16961"}, {"title": "Jumper et al. 2021 — Nature", "url": "https://www.nature.com/articles/s41586-021-03819-2"}, {"title": "Nobel Prize in Chemistry 2024", "url": "https://www.nobelprize.org/prizes/chemistry/2024/summary/"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "vaswani", "section": "ai3", "name": "Ashish Vaswani", "years": "birth year not public", "role": "Transformer co-author; listed first on the paper", "photo": null, "w": null, "h": null, "credit": null, "story": ["Ashish Vaswani was born in India and raised mostly in the Middle East. He studied computer science at Birla Institute of Technology, Mesra, then earned a PhD at the University of Southern California in its machine-translation group.", "He joined Google Brain, which he described to Wired as 'a radical group' that believed neural networks would advance human understanding. He was looking for a big project.", "When he heard about Jakob Uszkoreit's self-attention idea, he signed on. With Uszkoreit and Illia Polosukhin he drew up the first design document for 'Transformers'.", "Late one night, crashing on an office couch, he saw neurons in the curtain pattern and told intern Aidan Gomez the work would go far beyond translation: one architecture for speech, audio and vision.", "His name ended up first in an author list the team had declared random.", "He co-founded Adept AI with Niki Parmar, then Essential AI in December 2022. Wikipedia reports that in June 2026 Nvidia acqui-hired Essential AI's team, including Vaswani."], "facts": ["First-listed author of 'Attention Is All You Need'", "Co-founded Adept AI and Essential AI"], "sources": [{"title": "Ashish Vaswani — Wikipedia", "url": "https://en.wikipedia.org/wiki/Ashish_Vaswani"}, {"title": "Vaswani et al., 'Attention Is All You Need' (2017), arXiv", "url": "https://arxiv.org/abs/1706.03762"}, {"title": "Steven Levy, '8 Google Employees Invented Modern AI', WIRED, 2024", "url": "https://www.wired.com/story/eight-google-employees-invented-modern-ai-transformers-paper/"}], "uncertain": ["Nvidia acqui-hire (June 2026) from Wikipedia; confirm against news."], "src": "ai-and-quantum"}, {"id": "shazeer", "section": "ai3", "name": "Noam Shazeer", "years": "born 1975 or 1976", "role": "Transformer co-author; the team's implementation 'wizard'", "photo": null, "w": null, "h": null, "credit": null, "story": ["Noam Shazeer was born in Philadelphia and grew up in Massachusetts. In 1994 he won a gold medal with a perfect score at the International Mathematical Olympiad.", "After Duke University he joined Google in 2000, one of its early employees, and became an in-house legend for work like improving search spelling correction and the early ad system.", "In 2017, walking past Łukasz Kaiser's workspace, he overheard Vaswani and Parmar excitedly discussing self-attention. He found older recurrent networks 'irritating' and thought, 'Let's go replace them!'", "He rewrote the team's code his own way. Teammates described the result with words like 'magic' and 'alchemy'; Llion Jones said simply, 'Noam is a wizard.' His version pushed the model past the best existing systems.", "In 2021 he left Google with Daniel De Freitas to found Character.AI, after Google declined to release their chatbot, Meena. In 2024 he returned to Google in a licensing deal to co-lead work on Gemini."], "facts": ["IMO gold medal with perfect score (1994)", "Joined Google in 2000", "Co-founded Character.AI (2021); returned to Google (2024)"], "sources": [{"title": "Noam Shazeer — Wikipedia", "url": "https://en.wikipedia.org/wiki/Noam_Shazeer"}, {"title": "Vaswani et al., 'Attention Is All You Need' (2017), arXiv", "url": "https://arxiv.org/abs/1706.03762"}, {"title": "Steven Levy, '8 Google Employees Invented Modern AI', WIRED, 2024", "url": "https://www.wired.com/story/eight-google-employees-invented-modern-ai-transformers-paper/"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "parmar", "section": "ai3", "name": "Niki Parmar", "years": "birth year not public", "role": "Transformer co-author; ran key experiments to the deadline", "photo": null, "w": null, "h": null, "credit": null, "story": ["Niki Parmar is an Indian engineer who worked for an American software company in India before moving to the U.S. She earned a master's at USC in 2015 and, recruited by all the big tech firms, chose Google.", "At Google she worked with Uszkoreit on model variants for search, then joined the Transformer effort.", "In the final sprint she was gathering results to the last minute: 'The English-French numbers came, like, five minutes before we submitted the paper,' she told Wired.", "She later co-founded Adept and then Essential AI with Ashish Vaswani."], "facts": ["Co-author of 'Attention Is All You Need'", "Co-founded Adept and Essential AI"], "sources": [{"title": "Vaswani et al., 'Attention Is All You Need' (2017), arXiv", "url": "https://arxiv.org/abs/1706.03762"}, {"title": "Steven Levy, '8 Google Employees Invented Modern AI', WIRED, 2024", "url": "https://www.wired.com/story/eight-google-employees-invented-modern-ai-transformers-paper/"}], "uncertain": ["No Wikipedia article; details rely on Wired."], "src": "ai-and-quantum"}, {"id": "uszkoreit", "section": "ai3", "name": "Jakob Uszkoreit", "years": "birth year not public", "role": "Transformer co-author; championed self-attention and named the model", "photo": null, "w": null, "h": null, "credit": null, "story": ["Jakob Uszkoreit is the son of computational linguist Hans Uszkoreit, who as a teenager was jailed for 15 months in East Germany for protesting the Soviet invasion of Czechoslovakia.", "Jakob joined Google's translation team as an intern, abandoned his PhD plans, and around 2014 began pushing an idea he called self-attention: let every word look at every other word at once.", "Colleagues were skeptical — even his father, over dinner. He kept sketching it on whiteboards until Polosukhin and Vaswani joined him.", "He picked the name 'Transformer' from day zero; he had two little Transformer toys as a child. The early design document ended with a cartoon of Transformers zapping lasers.", "He later co-founded Inceptive, a biotech company built on Transformer technology."], "facts": ["Originated the self-attention push at Google", "Named the Transformer", "Co-founded Inceptive"], "sources": [{"title": "Vaswani et al., 'Attention Is All You Need' (2017), arXiv", "url": "https://arxiv.org/abs/1706.03762"}, {"title": "Steven Levy, '8 Google Employees Invented Modern AI', WIRED, 2024", "url": "https://www.wired.com/story/eight-google-employees-invented-modern-ai-transformers-paper/"}], "uncertain": ["No Wikipedia article; details rely on Wired."], "src": "ai-and-quantum"}, {"id": "jones", "section": "ai3", "name": "Llion Jones", "years": "born 1984", "role": "Transformer co-author; came up with the paper's title", "photo": "people/jones.jpg", "w": 482, "h": 720, "credit": "Syced — CC0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Llion_Jones,_author_of_Attention_is_All_You_Need,_at_CIC_Tokyo_speaking_about_sakana.ai_(cropped).jpg)", "story": ["Llion Jones was born in 1984 in Bangor, Wales, and grew up in Bangor and Abergynolwyn. He studied AI and computer science at the University of Birmingham.", "He finished his master's in 2009 in the middle of a recession and lived on unemployment benefits for months. He applied to Google as a 'hail Mary', joined YouTube, and moved to Google Research in 2015.", "Hearing about self-attention from a colleague, he joined the team. Days before the deadline he suggested the title, riffing on the Beatles' 'All You Need Is Love'. 'It literally took five seconds of thought,' he said.", "In 2023 he co-founded Sakana AI in Tokyo with David Ha and became its CTO. He has criticized the field's narrow focus on large language models."], "facts": ["Suggested the title 'Attention Is All You Need'", "Co-founder and CTO of Sakana AI"], "sources": [{"title": "Llion Jones — Wikipedia", "url": "https://en.wikipedia.org/wiki/Llion_Jones"}, {"title": "Vaswani et al., 'Attention Is All You Need' (2017), arXiv", "url": "https://arxiv.org/abs/1706.03762"}, {"title": "Steven Levy, '8 Google Employees Invented Modern AI', WIRED, 2024", "url": "https://www.wired.com/story/eight-google-employees-invented-modern-ai-transformers-paper/"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "gomez", "section": "ai3", "name": "Aidan Gomez", "years": "birth year not public", "role": "Transformer co-author as a 20-year-old intern; Cohere CEO", "photo": "people/gomez.jpg", "w": 514, "h": 720, "credit": "Gabriel Hutchinson — CC BY-SA 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Aidan_Gomez_at_%22ALL_IN%22_2025_06.jpg)", "story": ["Aidan Gomez grew up in Brighton, Ontario, where his family tapped maple trees for syrup each spring.", "As an undergraduate at the University of Toronto he fell in love with AI and joined Hinton's lab. He emailed Google researchers with ideas; Łukasz Kaiser invited him to intern — he only later learned those internships were meant for PhD students.", "At 20 he was the team's intern, debugging non-stop and making diagrams for the paper. 'People weren't sleeping,' he recalled.", "In 2019 he co-founded Cohere in Toronto, which builds language models for businesses. He completed his Oxford PhD in 2024."], "facts": ["Co-author of 'Attention Is All You Need' at age 20", "Co-founder and CEO of Cohere"], "sources": [{"title": "Aidan Gomez — Wikipedia", "url": "https://en.wikipedia.org/wiki/Aidan_Gomez"}, {"title": "Vaswani et al., 'Attention Is All You Need' (2017), arXiv", "url": "https://arxiv.org/abs/1706.03762"}, {"title": "Steven Levy, '8 Google Employees Invented Modern AI', WIRED, 2024", "url": "https://www.wired.com/story/eight-google-employees-invented-modern-ai-transformers-paper/"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "kaiser", "section": "ai3", "name": "Łukasz Kaiser", "years": "birth year not public", "role": "Transformer co-author; later an OpenAI researcher", "photo": null, "w": null, "h": null, "credit": null, "story": ["Łukasz Kaiser is a Polish-born theoretical computer scientist who moved into deep learning at Google Brain.", "He and his intern, Aidan Gomez, were working on their own approach to improving language models when they saw self-attention was more promising, and deliberately merged their project with the Transformer team.", "Around publication, Kaiser recalled, Shazeer proposed replacing Google's entire search index with one huge Transformer — an idea even Kaiser found ridiculous at the time, though it no longer sounds so crazy.", "He is the only one of the eight who did not found a company; he joined OpenAI."], "facts": ["Co-author of 'Attention Is All You Need'", "Joined OpenAI"], "sources": [{"title": "Vaswani et al., 'Attention Is All You Need' (2017), arXiv", "url": "https://arxiv.org/abs/1706.03762"}, {"title": "Steven Levy, '8 Google Employees Invented Modern AI', WIRED, 2024", "url": "https://www.wired.com/story/eight-google-employees-invented-modern-ai-transformers-paper/"}], "uncertain": ["No Wikipedia article; details rely on Wired."], "src": "ai-and-quantum"}, {"id": "polosukhin", "section": "ai3", "name": "Illia Polosukhin", "years": "birth year not public", "role": "Transformer co-author; co-founder of NEAR", "photo": null, "w": null, "h": null, "credit": null, "story": ["Illia Polosukhin was born in Ukraine and worked at Google for nearly three years on answering questions directly in search, where responses had to come in milliseconds.", "Over lunch in 2016 he complained about the problem to Uszkoreit, who suggested: why not use self-attention? With Vaswani they drew up the first Transformer design document.", "He left Google in early 2017, before the paper was finished, to co-found Near.ai with Alexander Skidanov. It became NEAR Protocol, a blockchain — the only one of the eight authors' companies not built on Transformers."], "facts": ["Co-wrote the first Transformer design document", "Co-founded NEAR Protocol"], "sources": [{"title": "NEAR Protocol — Wikipedia", "url": "https://en.wikipedia.org/wiki/NEAR_Protocol"}, {"title": "Vaswani et al., 'Attention Is All You Need' (2017), arXiv", "url": "https://arxiv.org/abs/1706.03762"}, {"title": "Steven Levy, '8 Google Employees Invented Modern AI', WIRED, 2024", "url": "https://www.wired.com/story/eight-google-employees-invented-modern-ai-transformers-paper/"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "kaplan", "section": "ai3", "name": "Jared Kaplan", "years": "birth year not public", "role": "Physicist behind neural 'scaling laws'; Anthropic co-founder", "photo": "people/kaplan.jpg", "w": 680, "h": 720, "credit": "TechCrunch — CC BY 2.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Jared_Kaplan_(cropped).jpg)", "story": ["Jared Kaplan graduated from the Illinois Mathematics and Science Academy in 2001, studied physics and math at Stanford, and earned a PhD at Harvard under Nima Arkani-Hamed.", "He worked on quantum gravity and holography — the idea that some spaces can be described by physics on their boundary — and has been a physics professor at Johns Hopkins since 2012.", "He joined OpenAI in 2019. In 2020 he led 'Scaling Laws for Neural Language Models', which found that a model's performance improves smoothly and predictably as you add parameters, data and compute — almost like a law of physics.", "That predictability gave labs confidence to spend huge sums on bigger models. He co-authored the GPT-3 paper the same year.", "In 2022 DeepMind's 'Chinchilla' paper refined the recipe, showing many models were too large for the amount of data they had been trained on.", "Kaplan co-founded Anthropic and is its chief science officer; in October 2024 he also became its Responsible Scaling Officer, overseeing what safety checks are required before models are released."], "facts": ["Lead author, Scaling Laws for Neural Language Models (2020)", "Co-author of the GPT-3 paper", "Co-founder and chief science officer of Anthropic"], "sources": [{"title": "Jared Kaplan — Wikipedia", "url": "https://en.wikipedia.org/wiki/Jared_Kaplan"}, {"title": "Kaplan et al. 2020 — arXiv", "url": "https://arxiv.org/abs/2001.08361"}, {"title": "Hoffmann et al. 2022 (Chinchilla) — arXiv", "url": "https://arxiv.org/abs/2203.15556"}, {"title": "Brown et al. 2020 (GPT-3) — arXiv", "url": "https://arxiv.org/abs/2005.14165"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "benioff", "section": "quantum", "name": "Paul Benioff", "years": "1930 – 2022", "role": "Described the first quantum-mechanical model of a computer", "photo": "people/benioff.jpg", "w": 720, "h": 720, "credit": "Justinhsb — CC BY 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Paul_Benioff_profile_picture_with_glasses.jpg)", "story": ["Paul Benioff was born in Pasadena in 1930. His father, Hugo Benioff, was a seismology professor at Caltech; his mother held a master's degree in English from Berkeley.", "He studied botany at Berkeley, worked in nuclear chemistry, and earned a PhD in nuclear chemistry in 1959. After fellowships at the Weizmann Institute and the Niels Bohr Institute, he joined Argonne National Laboratory in 1961 and stayed until he retired in 1995.", "In the 1970s he began asking a question few took seriously: could a computer run entirely by the laws of quantum mechanics?", "In a paper published in 1980 he showed it could, describing a Turing machine with Schrödinger's equation. Building on Charles Bennett's work on reversible computing, his model didn't dissipate energy as it ran.", "At the time, several papers argued quantum effects would make such a machine impossible. Benioff's work helped answer them, and in 1982 he showed more about how quantum computers could work.", "He is counted, with Feynman, Deutsch and Shor, among the people who started the field. He kept researching at Argonne as an emeritus scientist and died in 2022, survived by his wife of 62 years."], "facts": ["1980 paper: quantum-mechanical model of Turing machines", "Argonne National Laboratory, 1961–1995"], "sources": [{"title": "Paul Benioff — Wikipedia", "url": "https://en.wikipedia.org/wiki/Paul_Benioff"}, {"title": "Benioff, 'The computer as a physical system', J. Stat. Phys. 22 (1980)", "url": "https://doi.org/10.1007/BF01011339"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "feynman", "section": "quantum", "name": "Richard Feynman", "years": "1918 – 1988", "role": "Proposed simulating nature with quantum computers", "photo": null, "w": null, "h": null, "credit": null, "story": ["Richard Feynman was born in Queens, New York, in 1918, and his family later moved to Far Rockaway. He loved puzzles and fixing radios.", "After MIT and a Princeton PhD he joined the Manhattan Project. He married his first love, Arline Greenbaum, knowing she had tuberculosis, and visited her on weekends in a sanatorium near Los Alamos until she died in 1945.", "After the war, at Cornell and then Caltech, he reinvented quantum electrodynamics using simple sketches now called Feynman diagrams. He shared the 1965 Nobel Prize in Physics with Julian Schwinger and Shin'ichirō Tomonaga.", "In 1981, at a conference on the physics of computation at MIT, he argued that ordinary computers can't efficiently simulate quantum systems — the numbers explode. 'Nature isn't classical, dammit,' he said, 'and if you want to make a simulation of nature, you'd better make it quantum mechanical.'", "The talk, published in 1982 as 'Simulating Physics with Computers', is widely seen as a spark of quantum computing, alongside Benioff's work.", "In 1986 he served on the Rogers Commission investigating the Space Shuttle Challenger disaster, and became known for blunt, independent findings.", "His storytelling made him famous far beyond physics, in books like Surely You're Joking, Mr. Feynman! His Feynman Lectures on Physics are free online. He died in 1988."], "facts": ["Nobel Prize in Physics 1965", "1981 talk 'Simulating Physics with Computers'", "Rogers Commission on Challenger (1986)"], "sources": [{"title": "Richard Feynman — Wikipedia", "url": "https://en.wikipedia.org/wiki/Richard_Feynman"}, {"title": "Feynman, 'Simulating Physics with Computers', Int. J. Theor. Phys. 21 (1982)", "url": "https://doi.org/10.1007/BF02650179"}, {"title": "The Feynman Lectures on Physics — Caltech", "url": "https://www.feynmanlectures.caltech.edu/"}, {"title": "Nobel Prize in Physics 1965", "url": "https://www.nobelprize.org/prizes/physics/1965/summary/"}], "uncertain": ["Quote wording varies slightly between retellings; check against the published 1982 paper before display."], "src": "ai-and-quantum"}, {"id": "deutsch", "section": "quantum", "name": "David Deutsch", "years": "born 1953", "role": "Described the universal quantum computer", "photo": "people/deutsch.jpg", "w": 388, "h": 417, "credit": "Simon Benjamin — CC BY 3.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:David_Deutsch_(cropped).jpg)", "story": ["David Deutsch was born in Haifa, Israel, in 1953 to a Jewish family, and grew up in London.", "He studied at Cambridge and did his doctorate at Oxford, where he worked with the cosmologist Dennis Sciama. He has remained in Oxford, as a visiting professor linked to the Centre for Quantum Computation at the Clarendon Laboratory.", "In 1985 he published a description of a universal quantum computer — a quantum version of Turing's universal machine. He is often called the 'father of quantum computing'.", "In 1992, with Richard Jozsa, he extended that paper into the Deutsch–Jozsa algorithm, one of the first examples of a quantum algorithm exponentially faster than any deterministic classical method.", "Deutsch champions the many-worlds interpretation of quantum mechanics and argues quantum computers draw on many parallel universes. Many physicists don't accept that explanation; it remains debated.", "He set out his worldview in The Fabric of Reality (1997) and The Beginning of Infinity (2011). In 2022 he was awarded the Breakthrough Prize in Fundamental Physics, shared with Charles Bennett, Gilles Brassard and Peter Shor."], "facts": ["1985 paper on the universal quantum computer", "Deutsch–Jozsa algorithm (1992)", "Breakthrough Prize in Fundamental Physics (announced 2022, '2023 prize')"], "sources": [{"title": "David Deutsch — Wikipedia", "url": "https://en.wikipedia.org/wiki/David_Deutsch"}, {"title": "Deutsch 1985, Proc. R. Soc. Lond. A 400", "url": "https://doi.org/10.1098/rspa.1985.0070"}, {"title": "The Fabric of Reality — Wikipedia", "url": "https://en.wikipedia.org/wiki/The_Fabric_of_Reality"}], "uncertain": ["The many-worlds explanation of quantum speedup is contested."], "src": "ai-and-quantum"}, {"id": "shor", "section": "quantum", "name": "Peter Shor", "years": "born 1959", "role": "Discovered the quantum factoring algorithm and the first quantum error-correcting code", "photo": "people/shor.jpg", "w": 559, "h": 720, "credit": "International Centre for Theoretical Physics — CC BY 3.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Peter_Shor_2017_Dirac_Medal_Award_Ceremony.png)", "story": ["Peter Shor was born in New York City in 1959 and grew up in Washington, D.C., and Mill Valley, California.", "At Tamalpais High School he placed third in the 1977 USA Mathematical Olympiad, then won a silver medal at the International Mathematical Olympiad. At Caltech he became a Putnam Fellow in 1978.", "After a PhD in applied math at MIT he joined AT&T Bell Labs. In 1994 he found an algorithm showing a quantum computer could factor large numbers exponentially faster than any known classical method.", "That mattered enormously: RSA, the encryption protecting much of the internet, relies on factoring being hard. Suddenly governments cared about quantum computers.", "Skeptics pointed out that qubits are fragile. In 1995 Shor answered with the first quantum error-correcting code, spreading one qubit's information across nine so errors can be detected and fixed.", "He won the Nevanlinna Prize in 1998, has been an MIT professor of applied mathematics since 2003, and shared the 2023 Breakthrough Prize in Fundamental Physics.", "His algorithm has only factored tiny numbers on real hardware so far, but it has already pushed the world toward new 'post-quantum' encryption, standardized by NIST in 2024."], "facts": ["Shor's algorithm (1994)", "First quantum error-correcting code (1995)", "Nevanlinna Prize 1998", "Breakthrough Prize in Fundamental Physics 2023"], "sources": [{"title": "Peter Shor — Wikipedia", "url": "https://en.wikipedia.org/wiki/Peter_Shor"}, {"title": "Shor, 'Polynomial-Time Algorithms for Prime Factorization…' — arXiv", "url": "https://arxiv.org/abs/quant-ph/9508027"}, {"title": "Shor, 'Scheme for reducing decoherence in quantum computer memory', Phys. Rev. A 52 (1995)", "url": "https://doi.org/10.1103/PhysRevA.52.R2493"}, {"title": "NIST Post-Quantum Cryptography", "url": "https://csrc.nist.gov/projects/post-quantum-cryptography"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "grover", "section": "quantum", "name": "Lov Grover", "years": "born 1961", "role": "Discovered the quantum search algorithm", "photo": null, "w": null, "h": null, "credit": null, "story": ["Lov Kumar Grover was born in Meerut, India, in 1961.", "He earned his bachelor's degree at the Indian Institute of Technology Delhi in 1981 and a PhD in electrical engineering at Stanford in 1985.", "He joined Bell Labs in 1984, and from 1987 to 1994 was also a visiting professor at Cornell.", "In 1996, two years after Shor, he presented the second great quantum algorithm. It searches an unsorted list of N items in about √N steps: a million entries need about a thousand looks instead of up to a million.", "The speedup is smaller than Shor's, but it applies to a huge range of search-like problems, and it is provably the best possible for that kind of search.", "He explained it for general readers in a 1999 magazine article and a short piece titled 'What's a Quantum Phone Book?'. His algorithm was implemented in a scalable physical quantum system in 2017. He retired from Bell Labs in 2008 to research independently."], "facts": ["Grover's algorithm (1996)", "Bell Labs, 1984–2008"], "sources": [{"title": "Lov Grover — Wikipedia", "url": "https://en.wikipedia.org/wiki/Lov_Grover"}, {"title": "Grover, 'A fast quantum mechanical algorithm for database search' — arXiv", "url": "https://arxiv.org/abs/quant-ph/9605043"}, {"title": "Grover's algorithm — Wikipedia", "url": "https://en.wikipedia.org/wiki/Grover%27s_algorithm"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "zoller", "section": "quantum", "name": "Peter Zoller", "years": "born 1952", "role": "Co-proposed the trapped-ion quantum computer", "photo": "people/zoller.jpg", "w": 444, "h": 600, "credit": "Hans Weber — CC BY-SA 3.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Zoller_Peter.jpg)", "story": ["Peter Zoller was born in Austria in 1952 and studied physics at the University of Innsbruck, where he is now emeritus professor.", "He became a leading theorist of quantum optics — how light and single atoms interact. While he was at JILA in Boulder, Colorado, a young Spanish physicist, Ignacio Cirac, joined him as a postdoc in 1991.", "In 1995 the two published a short paper showing exactly how to build a quantum computer from ions — charged atoms — held in a row by electric fields. Laser pulses would set each ion's state, and the ions' shared vibration would let them interact.", "David Wineland's group at NIST soon demonstrated a key two-qubit gate using trapped ions. Wineland later shared the 2012 Nobel Prize in Physics.", "Zoller went on to pioneer ideas in quantum simulation and quantum communication. He and Cirac shared the 2013 Wolf Prize in Physics.", "Trapped ions remain one of the leading quantum-computer technologies today."], "facts": ["Cirac–Zoller proposal, Phys. Rev. Lett. 74 (1995)", "Wolf Prize in Physics 2013 (with Cirac)", "Fellow of the Royal Society"], "sources": [{"title": "Peter Zoller — Wikipedia", "url": "https://en.wikipedia.org/wiki/Peter_Zoller"}, {"title": "Cirac & Zoller, 'Quantum Computations with Cold Trapped Ions', PRL 74 (1995)", "url": "https://doi.org/10.1103/PhysRevLett.74.4091"}, {"title": "Trapped-ion quantum computer — Wikipedia", "url": "https://en.wikipedia.org/wiki/Trapped-ion_quantum_computer"}], "uncertain": ["Timing of Wineland's 1995 gate demo relative to the proposal stated loosely as 'soon'."], "src": "ai-and-quantum"}, {"id": "cirac", "section": "quantum", "name": "Ignacio Cirac", "years": "born 1965", "role": "Co-proposed the trapped-ion quantum computer; pioneer of quantum simulation", "photo": "people/cirac.jpg", "w": 207, "h": 285, "credit": "Author original propietry — CC BY-SA 3.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Prof_Cirac_office_klein_(cropped).jpg)", "story": ["Juan Ignacio Cirac Sasturain was born on 11 October 1965 in Manresa, Spain. He graduated from the Complutense University of Madrid in 1988.", "In 1991 he went to Boulder, Colorado, as a postdoc with Peter Zoller, while teaching physics in Ciudad Real, Spain, until 1996.", "Together they wrote the 1995 trapped-ion proposal that turned quantum computing from a thought experiment into an engineering plan.", "His work on atoms in 'optical lattices' — egg-crate patterns of laser light — helped launch quantum simulation, using one controllable quantum system to mimic another.", "He became a professor in Innsbruck in 1996 and, in 2001, a director of the Max Planck Institute of Quantum Optics in Garching, Germany, where he heads the theory division.", "He shared the 2013 Wolf Prize with Zoller and is among the most cited researchers in his field."], "facts": ["Cirac–Zoller proposal (1995)", "Director, Max Planck Institute of Quantum Optics (since 2001)", "Wolf Prize in Physics 2013"], "sources": [{"title": "Juan Ignacio Cirac — Wikipedia", "url": "https://en.wikipedia.org/wiki/Juan_Ignacio_Cirac_Sasturain"}, {"title": "Cirac & Zoller, PRL 74 (1995)", "url": "https://doi.org/10.1103/PhysRevLett.74.4091"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "martinis", "section": "quantum", "name": "John Martinis", "years": "born 1958", "role": "Showed circuits can be quantum; led Google's 2019 supremacy experiment; 2025 Nobel", "photo": "people/martinis.jpg", "w": 488, "h": 720, "credit": "Karen Zhou — CC BY-SA 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:John_M._Martinis,_American_physicst_and_2025_Nobel_laurate_in_physics.jpg)", "story": ["John Martinis was born in 1958 and grew up in San Pedro, Los Angeles. His father had emigrated from the Croatian island of Vis.", "He studied physics at Berkeley. As a graduate student in John Clarke's lab, working with postdoc Michel Devoret, he studied a superconducting circuit containing a Josephson junction — a tiny insulating gap.", "In 1985 they showed the whole circuit, big enough to see, behaved like a single quantum object: it tunneled through an energy barrier and had separate energy levels, like an atom. That became a foundation of superconducting qubits.", "After a postdoc in France and years at NIST in Boulder, he joined UC Santa Barbara in 2004. A device his group built was Science magazine's Breakthrough of the Year in 2010.", "In 2014 Google hired Martinis and his team. In 2019 their 53-qubit Sycamore chip performed a sampling task in about 200 seconds that they estimated would take a supercomputer 10,000 years. IBM disputed that estimate, and later classical methods narrowed the gap.", "He left Google in 2020. In October 2025 he, Clarke and Devoret won the Nobel Prize in Physics."], "facts": ["1985 discovery of macroscopic quantum tunneling and energy quantization in a circuit", "Led Google's Sycamore experiment (2019)", "Nobel Prize in Physics 2025"], "sources": [{"title": "John M. Martinis — Wikipedia", "url": "https://en.wikipedia.org/wiki/John_M._Martinis"}, {"title": "Nobel Prize in Physics 2025 — NobelPrize.org", "url": "https://www.nobelprize.org/prizes/physics/2025/summary/"}, {"title": "Arute et al. 2019 — Nature", "url": "https://www.nature.com/articles/s41586-019-1666-5"}], "uncertain": ["Sycamore's '10,000 years' claim was contested.", "His 2020 departure date taken from earlier reporting."], "src": "ai-and-quantum"}, {"id": "devoret", "section": "quantum", "name": "Michel Devoret", "years": "born 1953", "role": "Superconducting-qubit pioneer (quantronium, transmon, fluxonium); 2025 Nobel", "photo": "people/devoret.jpg", "w": 480, "h": 720, "credit": "Christian Ursilva from København, Danmark — CC BY-SA 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Michel_Devoret_(54987873184).jpg)", "story": ["Michel Devoret was born in Paris in 1953. He trained as an engineer at Télécom Paris, then earned a PhD in quantum condensed-matter physics at Orsay in 1982, researching at CEA Saclay.", "From 1982 to 1984 he was a postdoc in John Clarke's group at Berkeley. With grad student John Martinis, they demonstrated in 1985 the quantized energy levels of a Josephson junction — the work later honored by the Nobel.", "Back at Saclay he co-founded the Quantronics group with Daniel Esteve and Cristian Urbina, which built the 'quantronium', an early superconducting qubit.", "He later moved to Yale, where he worked on superconducting qubit designs including the transmon — the type used by Google and IBM — and, in 2009, the fluxonium.", "He is now a professor at UC Santa Barbara, professor emeritus at Yale, and chief scientist for quantum hardware at Google Quantum AI.", "He shared the 2025 Nobel Prize in Physics with Clarke and Martinis."], "facts": ["1985 Josephson-junction experiment with Clarke and Martinis", "Co-founded Quantronics group at CEA Saclay", "Quantronium, transmon, fluxonium architectures", "Nobel Prize in Physics 2025"], "sources": [{"title": "Michel Devoret — Wikipedia", "url": "https://en.wikipedia.org/wiki/Michel_Devoret"}, {"title": "Nobel Prize in Physics 2025 — NobelPrize.org", "url": "https://www.nobelprize.org/prizes/physics/2025/summary/"}, {"title": "Transmon — Wikipedia", "url": "https://en.wikipedia.org/wiki/Transmon"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "turing", "section": "finale", "name": "Alan Turing", "years": "1912 – 1954", "role": "Imagined the universal computer and asked 'Can machines think?'", "photo": "people/turing.jpg", "w": 540, "h": 720, "credit": "Elliott &amp; Fry — Public domain, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Alan_turing_header.jpg)", "story": ["Alan Turing was born in London in 1912. At school his headmaster worried he cared too much about science and not enough about the classics.", "In 1936, at 24, he published 'On Computable Numbers', imagining a simple machine reading symbols on a tape — and showing that one universal machine could imitate any other. Every computer today is a version of that idea.", "During World War II at Bletchley Park he led Hut 8, breaking German naval Enigma messages. His methods improved on the Polish 'bomba' and sped up the breaking of Enigma.", "After the war he designed an early stored-program computer and then worked at the University of Manchester on some of the first real computers.", "In 1950 he wrote 'Computing Machinery and Intelligence', asking 'Can machines think?' He swapped the vague question for a game: if a judge chatting by text can't tell machine from human, why not say it thinks? We call it the Turing test.", "He predicted that by about the year 2000 machines would fool an average judge about 30% of the time after five minutes, and suggested building a 'child machine' and teaching it — an early hint of machine learning.", "In 1952 he was prosecuted for homosexuality, accepted chemical castration, and lost his security clearance. He died on 7 June 1954, aged 41.", "After a 2009 campaign, Prime Minister Gordon Brown apologized for 'the appalling way he was treated', and in 2013 he received a royal pardon. His question is the one this whole site has been circling."], "facts": ["'On Computable Numbers' (1936)", "Head of Hut 8 at Bletchley Park", "'Computing Machinery and Intelligence' (1950)", "Royal pardon 2013"], "sources": [{"title": "Alan Turing — Wikipedia", "url": "https://en.wikipedia.org/wiki/Alan_Turing"}, {"title": "Turing, 'Computing Machinery and Intelligence', Mind 59 (1950)", "url": "https://doi.org/10.1093/mind/LIX.236.433"}, {"title": "Computing Machinery and Intelligence — Wikipedia", "url": "https://en.wikipedia.org/wiki/Computing_Machinery_and_Intelligence"}, {"title": "Andrew Hodges, Alan Turing: The Enigma — author's site", "url": "https://www.turing.org.uk/"}], "uncertain": ["The inquest ruled his death suicide; some writers have questioned that verdict."], "src": "ai-and-quantum"}, {"id": "good", "section": "finale", "name": "I. J. Good", "years": "1916 – 2009", "role": "Described the 'intelligence explosion'", "photo": null, "w": null, "h": null, "credit": null, "story": ["Irving John Good was born Isadore Jacob Gudak in London in 1916 to a Polish Jewish family. He later anglicized his name and signed his work 'I. J. Good'.", "He studied mathematics at Cambridge and, during World War II, worked at Bletchley Park as a cryptologist alongside Alan Turing.", "After the war he worked with Turing at Manchester on computer design and on Bayesian statistics, a field in which he became a major figure.", "In 1965 he wrote 'Speculations Concerning the First Ultraintelligent Machine'. A machine smarter than any human could design even better machines, he argued, setting off an 'intelligence explosion' that would leave humans far behind.", "His most quoted line: 'the first ultraintelligent machine is the last invention that man need ever make, provided that the machine is docile enough to tell us how to keep it under control.'", "Because of this work, Stanley Kubrick consulted him while making 2001: A Space Odyssey (1968), with its famous AI, HAL 9000.", "He moved to the United States and became a professor at Virginia Tech. He died in 2009."], "facts": ["Bletchley Park cryptologist with Turing", "'Speculations Concerning the First Ultraintelligent Machine' (1965)", "Adviser to Kubrick on 2001"], "sources": [{"title": "I. J. Good — Wikipedia", "url": "https://en.wikipedia.org/wiki/I._J._Good"}, {"title": "Good, 'Speculations Concerning the First Ultraintelligent Machine', Advances in Computers 6", "url": "https://doi.org/10.1016/S0065-2458(08)60418-0"}, {"title": "Technological singularity — Wikipedia", "url": "https://en.wikipedia.org/wiki/Technological_singularity"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "bostrom", "section": "finale", "name": "Nick Bostrom", "years": "born 1973", "role": "Philosopher of superintelligence and existential risk", "photo": "people/bostrom.jpg", "w": 553, "h": 720, "credit": "Future of Humanity Institute — CC BY 4.0, via Wikimedia Commons (https://commons.wikimedia.org/wiki/File:Prof_Nick_Bostrom_324-1.jpg)", "story": ["Nick Bostrom was born Niklas Boström in Helsingborg, Sweden, in 1973. He disliked school and spent his last year of high school learning at home, reading widely in anthropology, art, literature and science.", "He earned a PhD in philosophy at the London School of Economics.", "In 2003 he published the 'simulation argument': at least one of three possibilities must be true, one of which is that we are almost certainly living in a computer simulation.", "In 2005 he founded Oxford's Future of Humanity Institute to study big-picture risks to civilization, from synthetic biology to advanced AI.", "His 2014 book Superintelligence: Paths, Dangers, Strategies argued that an AI far smarter than humans might pursue goals at odds with ours, and that solving the 'control problem' in advance is urgent. Bill Gates and Elon Musk praised it.", "Critics say such scenarios are speculative and distract from present-day harms like bias and surveillance. The Future of Humanity Institute shut down in 2024."], "facts": ["Simulation argument (2003)", "Founded the Future of Humanity Institute (2005–2024)", "Superintelligence (2014)"], "sources": [{"title": "Nick Bostrom — Wikipedia", "url": "https://en.wikipedia.org/wiki/Nick_Bostrom"}, {"title": "Superintelligence — Wikipedia", "url": "https://en.wikipedia.org/wiki/Superintelligence:_Paths,_Dangers,_Strategies"}, {"title": "Bostrom, 'Are You Living in a Computer Simulation?', Phil. Quarterly 53 (2003)", "url": "https://doi.org/10.1111/1467-9213.00309"}], "uncertain": [], "src": "ai-and-quantum"}, {"id": "bardeen", "section": "transistor", "name": "John Bardeen", "years": "1908–1991", "role": "The quiet theorist who co-invented the transistor, then won a second Nobel", "photo": "people/bardeen.jpg", "w": 280, "h": 396, "credit": "Photo: Nobel foundation. License: Public domain. Source: https://commons.wikimedia.org/wiki/File:Bardeen.jpg", "story": ["John Bardeen grew up in Madison, Wisconsin. His father was dean of the university's medical school, and young John was so far ahead in math that he entered the University of Wisconsin at just fifteen.", "He studied electrical engineering, then took a detour that surprises people: he went to work in Pittsburgh at the Gulf Research Laboratories, using physics to help hunt for oil.", "It paid well, but his heart was in pure science. In 1933 he quit and went to Princeton to study mathematical physics, earning his PhD in 1936 on how electrons behave inside metals.", "After wartime work for the Navy, he joined Bell Labs in 1945. Bell wanted a solid, cool, reliable switch to replace the hot, fragile vacuum tubes in its telephone network.", "The team's first attempts did nothing. Bardeen worked out why: electrons trapped at the surface of the crystal were acting like a shield, blocking the electric field from getting inside.", "That one idea changed the plan. Instead of pushing through the surface, he and Walter Brattain started working right at it, and in December 1947 their germanium device amplified a signal. The transistor was born.", "In 1951 he left Bell Labs for the University of Illinois. There he took on a 40-year-old puzzle: why some metals, chilled near absolute zero, carry electricity with zero resistance.", "With Leon Cooper and Robert Schrieffer he cracked it. Their 'BCS theory' won the 1972 Nobel Prize in Physics, making Bardeen the only person ever to win the physics prize twice.", "Picture it: one man helped launch the age of electronics, then went on to explain one of the deepest puzzles in physics. He died in 1991."], "facts": ["Entered university at 15", "Worked as a geophysicist at Gulf Research before his PhD", "Joined Bell Labs 1945; transistor with Brattain, Dec 1947", "Nobel Prize in Physics 1956 and 1972 — the only double physics laureate"], "sources": [{"title": "NobelPrize.org: John Bardeen, Biographical", "url": "https://www.nobelprize.org/prizes/physics/1956/bardeen/biographical/"}, {"title": "NobelPrize.org: Nobel Prize in Physics 1956", "url": "https://www.nobelprize.org/prizes/physics/1956/summary/"}, {"title": "NobelPrize.org: Nobel Prize in Physics 1972", "url": "https://www.nobelprize.org/prizes/physics/1972/summary/"}, {"title": "Computer History Museum, The Silicon Engine: 1947 Invention of the Point-Contact Transistor", "url": "https://www.computerhistory.org/siliconengine/invention-of-the-point-contact-transistor/"}, {"title": "Wikipedia: John Bardeen", "url": "https://en.wikipedia.org/wiki/John_Bardeen"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "brattain", "section": "transistor", "name": "Walter Brattain", "years": "1902–1987", "role": "The hands-on experimenter who built the first transistor", "photo": "people/brattain.jpg", "w": 280, "h": 396, "credit": "Photo: Nobel Foundation. License: Public domain. Source: https://commons.wikimedia.org/wiki/File:Brattain.jpg", "story": ["Walter Brattain was born in Amoy (now Xiamen), China, where his father was teaching at a school for Chinese boys. He came back to the United States as a baby.", "He grew up on a cattle ranch near Tonasket, in the hills of Washington State. Ranch work meant fixing whatever broke, and that habit of making things work with his hands stayed with him.", "Both of his parents had gone to Whitman College in Walla Walla, and so did he, graduating in 1924. He went on to a master's at Oregon and a PhD at Minnesota in 1929.", "That same year he joined Bell Labs. For years he studied what happens on the surfaces of solids, which turned out to be exactly the knowledge the transistor needed.", "After the war he was paired with theorist John Bardeen. The rhythm was simple: Bardeen would suggest an idea, Brattain would build it on the bench the same day, and they would talk over what happened.", "In December 1947 Brattain wrapped gold foil around a small plastic wedge, slit it with a razor so two gold contacts sat extremely close together, and pressed it onto germanium. A weak signal went in; a stronger one came out.", "That was the point-contact transistor. It looked crude, more like a science-fair project than the start of a revolution.", "Brattain shared the 1956 Nobel Prize. From 1963 he taught at Whitman College, his old school, and kept teaching there after retiring from Bell Labs in 1967."], "facts": ["Born in Amoy (Xiamen), China, 1902", "Bell Labs from 1929", "Built the first point-contact transistor with Bardeen, Dec 1947", "Nobel Prize in Physics 1956"], "sources": [{"title": "NobelPrize.org: Walter H. Brattain, Biographical", "url": "https://www.nobelprize.org/prizes/physics/1956/brattain/biographical/"}, {"title": "NobelPrize.org: Nobel Prize in Physics 1956", "url": "https://www.nobelprize.org/prizes/physics/1956/summary/"}, {"title": "Computer History Museum, The Silicon Engine: 1947 Invention of the Point-Contact Transistor", "url": "https://www.computerhistory.org/siliconengine/invention-of-the-point-contact-transistor/"}, {"title": "Wikipedia: Walter Houser Brattain", "url": "https://en.wikipedia.org/wiki/Walter_Houser_Brattain"}], "uncertain": ["Gold-foil-and-razor construction detail is from standard histories (CHM / Wikipedia), not the Nobel bio."], "src": "chips-and-networks"}, {"id": "shockley", "section": "transistor", "name": "William Shockley", "years": "1910–1989", "role": "Brilliant physicist, difficult boss, and the man who brought silicon to the Valley", "photo": "people/shockley.jpg", "w": 585, "h": 720, "credit": "Photo: Nobel foundation. License: Public domain. Source: https://commons.wikimedia.org/wiki/File:Shockley.jpg", "story": ["William Shockley was born in London to American parents, both connected to mining, and grew up in Palo Alto, California.", "He studied at Caltech and earned his PhD at MIT, then joined Bell Labs. After World War II he organized the solid-state group that set out to replace the vacuum tube.", "In April 1945 he dreamed up a 'field-effect' amplifier. It did not work. It was Bardeen who explained why, and Bardeen and Brattain who made the first transistor, in December 1947, without him in the room.", "Shockley was furious at being left out. The Computer History Museum describes what came next as a month of intense work, 'partly spurred by professional jealousy'.", "On January 23, 1948 he conceived a different design: the junction transistor, built from layers of differently treated semiconductor. It was sturdier and much easier to manufacture than the fiddly point-contact device.", "In 1956 he moved back near his mother in Palo Alto and set up Shockley Semiconductor Laboratory in Mountain View. He hired some of the brightest young scientists in the country.", "But he was a hard man to work for: controlling, suspicious, and quick to blame. In one famous episode, after a secretary got a small cut, he demanded lie-detector tests to find the 'culprit'.", "In 1957 eight of his best people walked out together and started Fairchild Semiconductor. Shockley's company never succeeded, but the people he hired went on to build Silicon Valley.", "His later decades are a dark chapter: he spent them promoting racist claims about intelligence that scientists rejected. His story shows that great science and good judgment do not always come together."], "facts": ["Born in London, 1910; raised in Palo Alto", "Conceived the junction transistor Jan 23, 1948", "Founded Shockley Semiconductor Laboratory, 1956", "Nobel Prize in Physics 1956"], "sources": [{"title": "NobelPrize.org: William B. Shockley, Biographical", "url": "https://www.nobelprize.org/prizes/physics/1956/shockley/biographical/"}, {"title": "NobelPrize.org: Nobel Prize in Physics 1956", "url": "https://www.nobelprize.org/prizes/physics/1956/summary/"}, {"title": "Computer History Museum, The Silicon Engine: 1948 Conception of the Junction Transistor", "url": "https://www.computerhistory.org/siliconengine/conception-of-the-junction-transistor/"}, {"title": "Wikipedia: William Shockley", "url": "https://en.wikipedia.org/wiki/William_Shockley"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "kilby", "section": "transistor", "name": "Jack Kilby", "years": "1923–2005", "role": "The new hire who built the first integrated circuit over a summer", "photo": "people/kilby.jpg", "w": 273, "h": 363, "credit": "Photo: James R. Biard. License: CC BY-SA 4.0 (https://creativecommons.org/licenses/by-sa/4.0/). Source: https://commons.wikimedia.org/wiki/File:Jack_Kilby_(cropped).png", "story": ["Jack Kilby was born in Jefferson City, Missouri, and grew up in Great Bend, Kansas, where his father ran a small electric company serving rural customers.", "When a huge ice storm knocked down power and phone lines, his father's company had to rely on amateur radio operators to stay in touch with customers. Teenage Jack watched, and electronics grabbed him for life.", "After the war he studied electrical engineering at the University of Illinois and worked at Centralab in Milwaukee, making circuits.", "In 1958 he joined Texas Instruments in Dallas. Engineers everywhere faced the 'tyranny of numbers': bigger circuits needed so many separate parts, all hand-wired, that they became unreliable.", "Kilby was so new he had not earned any vacation, so he spent the summer of 1958 in a quiet lab, thinking. His answer: make every part — transistors, resistors, capacitors — out of the same piece of semiconductor.", "On September 12, 1958 he showed his bosses a tiny piece of germanium wired to an oscilloscope. He pressed a switch and a steady wave appeared on the screen. It was the first integrated circuit.", "His chip still had small 'flying wires' linking the parts. A few months later Robert Noyce at Fairchild found a flat, wire-free way to do it, and today both are credited.", "Kilby later co-invented the handheld electronic calculator at TI. In 2000 he received the Nobel Prize in Physics — long after Noyce had died — and in his lecture he gave credit to Noyce too.", "He died in 2005. His home town's college in Great Bend still holds a yearly Jack Kilby STEM Day."], "facts": ["Born Jefferson City, MO; raised Great Bend, KS", "First IC demonstrated Sept 12, 1958 at Texas Instruments", "Co-inventor of the handheld calculator", "Nobel Prize in Physics 2000"], "sources": [{"title": "NobelPrize.org: Jack S. Kilby, Biographical (his own account)", "url": "https://www.nobelprize.org/prizes/physics/2000/kilby/biographical/"}, {"title": "NobelPrize.org: Jack S. Kilby, Facts", "url": "https://www.nobelprize.org/prizes/physics/2000/kilby/facts/"}, {"title": "National Inventors Hall of Fame: Jack S. Kilby", "url": "https://www.invent.org/inductees/jack-s-kilby"}, {"title": "Wikipedia: Jack Kilby", "url": "https://en.wikipedia.org/wiki/Jack_Kilby"}], "uncertain": ["That Kilby credited Noyce in his Nobel lecture is widely reported; not re-read in the lecture text itself."], "src": "chips-and-networks"}, {"id": "noyce", "section": "transistor", "name": "Robert Noyce", "years": "1927–1990", "role": "The 'Mayor of Silicon Valley' who made the chip practical", "photo": "people/noyce.jpg", "w": 640, "h": 360, "credit": "Photo: Intel Free Press. License: CC BY-SA 2.0 (https://creativecommons.org/licenses/by-sa/2.0/). Source: https://commons.wikimedia.org/wiki/File:Robert_Noyce_with_Motherboard_1959.png", "story": ["Robert Noyce grew up in Grinnell, Iowa, a minister's son who loved to build things. At twelve, in the summer of 1940, he and his brother built a boy-sized glider and flew it off the roof of the Grinnell College stables.", "He also built a radio from scratch and put a washing-machine motor and propeller on his sled.", "At Grinnell College his physics professor, Grant Gale, got hold of some of the very first transistors from Bell Labs. Noyce held the future in his hand as an undergraduate.", "He earned a PhD at MIT, worked at Philco, and then in 1956 joined Shockley in California. A year later he was one of the eight who walked out to start Fairchild Semiconductor.", "In 1959 the company's patent lawyer asked what else Jean Hoerni's new flat 'planar' process could be used for. Noyce's answer: build an entire circuit on one flat chip, with metal lines laid on top of the protective oxide to connect everything.", "That removed Kilby's flying wires and made chips that could be made in huge numbers. It is the ancestor of nearly every chip made since.", "In 1968 he and Gordon Moore left Fairchild to found Intel. Noyce was the warm, informal leader, and the press nicknamed him 'the Mayor of Silicon Valley'.", "He avoided the trappings of rank, and that relaxed, open-plan style became a Silicon Valley habit.", "He died suddenly in 1990. Because Nobel Prizes are not given after death, he could not share Kilby's prize in 2000."], "facts": ["Planar monolithic IC concept patented 1959", "Co-founded Fairchild (1957) and Intel (1968)", "Nicknamed 'the Mayor of Silicon Valley'", "Died June 3, 1990"], "sources": [{"title": "Computer History Museum, The Silicon Engine: 1959 Practical Monolithic IC Concept Patented", "url": "https://www.computerhistory.org/siliconengine/practical-monolithic-integrated-circuit-concept-patented/"}, {"title": "National Inventors Hall of Fame: Robert N. Noyce", "url": "https://www.invent.org/inductees/robert-n-noyce"}, {"title": "Wikipedia: Robert Noyce", "url": "https://en.wikipedia.org/wiki/Robert_Noyce"}], "uncertain": ["'Avoided the trappings of rank' (no reserved parking, etc.) is widely told in biographies such as Leslie Berlin's 'The Man Behind the Microchip'; not checked in a fetched primary source."], "src": "chips-and-networks"}, {"id": "moore", "section": "transistor", "name": "Gordon Moore", "years": "1929–2023", "role": "Chemist, Intel co-founder, and the man behind Moore's law", "photo": "people/moore.jpg", "w": 366, "h": 519, "credit": "Photo: Intel Free Press. License: CC BY-SA 2.0 (https://creativecommons.org/licenses/by-sa/2.0/). Source: https://commons.wikimedia.org/wiki/File:Gordon_Moore_1978_(cropped).png", "story": ["Gordon Moore was born in San Francisco in 1929. His father worked in law enforcement for San Mateo County, and the family moved to Redwood City in 1939.", "In 1940 he got a chemistry set for Christmas. It decided his career: he would become a chemist.", "He studied chemistry at UC Berkeley and earned his PhD at Caltech in 1954, then worked at Johns Hopkins before Shockley hired him.", "He was one of the 'traitorous eight' who left in 1957 to found Fairchild, where he became head of research and development.", "In 1965, asked to predict the future of chips, he drew a line through just five data points: the number of parts on the cheapest chip had been doubling about every year. He guessed it would reach 65,000 by 1975.", "His article 'Cramming more components onto integrated circuits' appeared in Electronics magazine. In 1975 he revised the pace to about every two years. Caltech professor Carver Mead gave it the name 'Moore's law'.", "It was never a law of nature. It became a target the whole industry planned around, which helped make it come true for decades.", "In 1968 he and Noyce founded Intel. He later became CEO, and in 2000 he and his wife Betty created a foundation with a gift worth about $5 billion for science and conservation.", "He died at his home in Hawaii in 2023, at 94. A CHM quote captures him: 'If everything you try works, you aren't trying hard enough.'"], "facts": ["'Cramming more components onto integrated circuits', Electronics, 1965", "Revised the doubling period to ~2 years in 1975", "Co-founded Intel, 1968", "Gordon and Betty Moore Foundation, 2000"], "sources": [{"title": "Computer History Museum: Gordon Moore, CHM Fellow", "url": "https://computerhistory.org/profile/gordon-moore/"}, {"title": "Computer History Museum, The Silicon Engine: 1965 Moore's Law Predicts the Future of ICs", "url": "https://www.computerhistory.org/siliconengine/moores-law-predicts-the-future-of-integrated-circuits/"}, {"title": "Computer History Museum catalog: Moore, 'Cramming more components onto integrated circuits' (1965)", "url": "https://www.computerhistory.org/collections/catalog/102770822"}, {"title": "National Inventors Hall of Fame: Gordon Moore", "url": "https://www.invent.org/inductees/gordon-moore"}, {"title": "Wikipedia: Gordon Moore", "url": "https://en.wikipedia.org/wiki/Gordon_Moore"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "hoerni", "section": "transistor", "name": "Jean Hoerni", "years": "1924–1997", "role": "Swiss physicist whose 'planar process' makes every modern chip possible", "photo": null, "w": null, "h": null, "credit": null, "story": ["Jean Hoerni was born in Switzerland in 1924. He earned two doctorates in physics, one from the University of Geneva and one from Cambridge.", "He came to the United States as a researcher and was recruited by William Shockley to his new lab in Mountain View.", "Like the others, he found Shockley impossible to work for. In 1957 he was one of the eight who left to found Fairchild Semiconductor.", "Early transistors had a weakness: their junctions sat exposed, and a speck of dirt or moisture could ruin them. Early in 1959 Hoerni found a fix.", "His planar process kept everything flat. A thin layer of silicon dioxide, basically glass, was left on the surface to protect the delicate junctions, with small windows etched only where needed.", "Flat, sealed chips were reliable, and they could be wired with metal on top. Noyce used exactly that to make the practical integrated circuit.", "Hoerni kept starting companies: Amelco in 1961, Union Carbide Electronics in 1964, and Intersil in 1967, where he pioneered low-power CMOS chips.", "He was also a passionate mountaineer who often visited the Karakoram mountains in Pakistan. Moved by the poverty there, he helped fund a school in the village of Korphe and endowed the Central Asia Institute.", "He died in 1997. In 2009 he was inducted into the National Inventors Hall of Fame."], "facts": ["Doctorates from Geneva and Cambridge", "Invented the planar process early 1959 (US Patent 3,025,589)", "Founded Amelco, Union Carbide Electronics, Intersil", "NIHF 2009"], "sources": [{"title": "National Inventors Hall of Fame: Jean Hoerni", "url": "https://www.invent.org/inductees/jean-hoerni"}, {"title": "Computer History Museum, The Silicon Engine: 1959 Practical Monolithic IC Concept Patented", "url": "https://www.computerhistory.org/siliconengine/practical-monolithic-integrated-circuit-concept-patented/"}, {"title": "Wikipedia: Jean Hoerni", "url": "https://en.wikipedia.org/wiki/Jean_Hoerni"}, {"title": "Wikipedia: Planar process", "url": "https://en.wikipedia.org/wiki/Planar_process"}], "uncertain": ["No free-licensed photo of Hoerni found on Wikimedia Commons; card has no photo.", "Some histories date the planar idea to 1957 notebook entries; NIHF says early 1959."], "src": "chips-and-networks"}, {"id": "faggin", "section": "transistor", "name": "Federico Faggin", "years": "born 1941", "role": "Italian physicist who designed the first microprocessor, and signed it", "photo": "people/faggin.jpg", "w": 572, "h": 720, "credit": "Photo: Intel Free Press. License: CC BY-SA 2.0 (https://creativecommons.org/licenses/by-sa/2.0/). Source: https://commons.wikimedia.org/wiki/File:Federico_Faggin_(cropped).jpg", "story": ["Federico Faggin was born in Vicenza, Italy, in 1941. At 19, working at Olivetti, he co-designed and built a small transistorized computer.", "He then earned a physics degree at the University of Padua in 1965 and joined SGS-Fairchild in Italy, where he developed their first MOS chip process.", "In 1968 he moved to Fairchild in Palo Alto. With Tom Klein he made silicon-gate technology practical: transistors with a gate of silicon instead of aluminum, which were faster, denser and more reliable.", "In 1970 he joined Intel to turn the Busicom calculator plan into real chips. The architecture existed on paper; nobody had yet worked out how to build it.", "Working long hours, with Masatoshi Shima's help on the logic, he designed all four chips in the MCS-4 family, including the 4004 processor.", "Proud of the work, he etched his initials, F.F., into a corner of the 4004. Signing a chip was his idea, and other designers copied it.", "The 4004 went on sale in November 1971 with about 2,300 transistors. Faggin also built a wafer tester run by a 4004, proving the chip could control machines, not just calculators.", "He went on to lead the 8008 and 8080, then co-founded Zilog, whose Z80 ran countless home computers, and later Synaptics, an early maker of touchpads."], "facts": ["Co-built a transistor computer at Olivetti at age 19", "Silicon-gate technology at Fairchild, 1968", "Led design of the Intel 4004 (1971); initials 'F.F.' on the die", "NIHF 1996; co-founded Zilog and Synaptics"], "sources": [{"title": "Computer History Museum: Federico Faggin, CHM Fellow", "url": "https://computerhistory.org/profile/federico-faggin/"}, {"title": "National Inventors Hall of Fame: Federico Faggin", "url": "https://www.invent.org/inductees/federico-faggin"}, {"title": "Computer History Museum, The Silicon Engine: 1968 Silicon Gate Technology", "url": "https://www.computerhistory.org/siliconengine/silicon-gate-technology-developed-for-ics/"}, {"title": "Computer History Museum, The Silicon Engine: 1971 Microprocessor Integrates CPU Function onto a Single Chip", "url": "https://www.computerhistory.org/siliconengine/microprocessor-integrates-cpu-function-onto-a-single-chip/"}, {"title": "Wikipedia: Federico Faggin", "url": "https://en.wikipedia.org/wiki/Federico_Faggin"}, {"title": "Wikipedia: Intel 4004", "url": "https://en.wikipedia.org/wiki/Intel_4004"}], "uncertain": ["Olivetti computer year: Wikipedia says 1960, NIHF says 1961 (both say age 19)."], "src": "chips-and-networks"}, {"id": "hoff", "section": "transistor", "name": "Ted Hoff", "years": "born 1937", "role": "The engineer who said: put a general-purpose computer on one chip", "photo": "people/hoff.jpg", "w": 384, "h": 535, "credit": "Photo: Dicklyon. License: CC BY-SA 4.0 (https://creativecommons.org/licenses/by-sa/4.0/). Source: https://commons.wikimedia.org/wiki/File:Marcian_Ted_Hoff_(cropped).jpg", "story": ["Marcian 'Ted' Hoff was born in Rochester, New York. As a high-school student in 1954 he was a finalist in the Westinghouse Science Talent Search.", "He studied electrical engineering at Rensselaer Polytechnic Institute, then earned his master's and PhD at Stanford by 1962.", "At Stanford he worked with Bernard Widrow on adaptive systems, early circuits that could learn — a distant ancestor of today's neural networks.", "In 1968 he joined the young Intel as manager of applications research. Intel had been founded to make memory chips.", "In 1969 Intel took a contract from Busicom, a Japanese calculator maker, and Hoff was assigned to look after the visiting Japanese engineering team.", "Busicom's plan needed many complicated custom chips. Hoff thought there was a simpler way: one small general-purpose processor that followed a program stored in memory, so software did the special work.", "With Stan Mazor he shaped that idea into the 4004 architecture. Faggin and Shima then turned it into silicon.", "In 1980 Hoff became Intel's first Intel Fellow, its top technical title. He left in 1983 for Atari, then worked as a consultant and patent technical expert.", "He was inducted into the National Inventors Hall of Fame in 1996 and received the National Medal of Technology and Innovation from President Obama in 2009."], "facts": ["Westinghouse Science Talent Search finalist, 1954", "Stanford PhD 1962; worked with Bernard Widrow", "Proposed the general-purpose single-chip CPU for Busicom, 1969", "First Intel Fellow 1980; National Medal of Technology and Innovation 2009"], "sources": [{"title": "Computer History Museum: Ted Hoff", "url": "https://computerhistory.org/profile/ted-hoff/"}, {"title": "Computer History Museum, The Silicon Engine: 1971 Microprocessor Integrates CPU Function onto a Single Chip", "url": "https://www.computerhistory.org/siliconengine/microprocessor-integrates-cpu-function-onto-a-single-chip/"}, {"title": "Wikipedia: Marcian Hoff", "url": "https://en.wikipedia.org/wiki/Marcian_Hoff"}], "uncertain": ["Exact number of chips in Busicom's original plan varies by account (often 'about a dozen'); left vague on purpose."], "src": "chips-and-networks"}, {"id": "mazor", "section": "transistor", "name": "Stan Mazor", "years": "born 1941", "role": "Self-taught programmer who co-designed the first microprocessor", "photo": "people/mazor.jpg", "w": 617, "h": 720, "credit": "Photo: Dicklyon. License: CC BY-SA 4.0 (https://creativecommons.org/licenses/by-sa/4.0/). Source: https://commons.wikimedia.org/wiki/File:Shima_and_Mazor_(cropped).jpg", "story": ["Stanley Mazor was born on October 22, 1941 in Chicago, and grew up in California, graduating from Oakland High School in 1959.", "At San Francisco State he majored in math and, for fun, studied helicopter design. Then he found the college's IBM 1620 computer and fell for it.", "He became a professor's assistant, teaching other students how to use the machine, and studied computer architecture from technical manuals on his own.", "In 1964 he became a programmer at Fairchild Semiconductor, then a computer designer there, and co-patented 'Symbol', a computer designed to run a high-level language directly.", "In 1969 he joined the year-old Intel and worked with Ted Hoff on the Busicom project. The two of them refined the idea of a computer on a chip.", "Mazor focused on the instruction set and the software. According to the IEEE history wiki, he wrote the software for the 4004 himself.", "Later he moved to Brussels for Intel, helping customers use its chips, then turned to teaching at Intel, Stanford and Santa Clara, with stints teaching around the world.", "He shares US Patent 3,821,715 for the microprocessor with Hoff and Faggin, and all three were inducted into the National Inventors Hall of Fame in 1996. With Hoff, Faggin and Shima he also received the Kyoto Prize."], "facts": ["Born Chicago, Oct 22, 1941", "Fairchild programmer from 1964", "Co-architect of the 4004; co-holder of US Patent 3,821,715", "NIHF 1996; Kyoto Prize"], "sources": [{"title": "IEEE Engineering and Technology History Wiki: Stanley Mazor", "url": "https://ethw.org/Stanley_Mazor"}, {"title": "National Inventors Hall of Fame: Stanley Mazor", "url": "https://www.invent.org/inductees/stanley-mazor"}, {"title": "Computer History Museum, The Silicon Engine: 1971 Microprocessor Integrates CPU Function onto a Single Chip", "url": "https://www.computerhistory.org/siliconengine/microprocessor-integrates-cpu-function-onto-a-single-chip/"}, {"title": "Wikipedia: Stanley Mazor", "url": "https://en.wikipedia.org/wiki/Stanley_Mazor"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "shima", "section": "transistor", "name": "Masatoshi Shima", "years": "born 1943", "role": "Chemistry graduate turned chip designer, from the 4004 to the Z80", "photo": "people/shima.jpg", "w": 617, "h": 720, "credit": "Photo: Dicklyon. License: CC BY-SA 4.0 (https://creativecommons.org/licenses/by-sa/4.0/). Source: https://commons.wikimedia.org/wiki/File:Masatoshi_Shima_(cropped).jpg", "story": ["Masatoshi Shima was born in Shizuoka, Japan, in 1943. He studied organic chemistry at Tohoku University.", "Jobs in chemistry were scarce, so in spring 1967 he joined Busicom, a calculator company. There he taught himself software and digital logic design.", "In 1968 Busicom decided to build its calculators with large-scale chips, and Shima was asked to design the logic for a set of custom chips.", "In 1969 he worked with Intel's Ted Hoff and Stan Mazor, who proposed a simpler, programmable design built around one processor.", "In 1970 Federico Faggin turned that architecture into silicon, with Shima assisting on the logic design. CHM later named both Fellows for their work on the 4004.", "Shima saw the deeper meaning. As he told CHM: 'the biggest invention with the microprocessor was the replacement of hardwired logic by software… Nobody knew how to do it. After the 4004, it was easy.'", "Intel then recruited him to design the 8-bit 8080. He also designed several Intel support chips later used in the IBM PC.", "He followed Faggin to Zilog to develop the Z80 (1976) and Z8000 (1979). In 1980 he returned to Japan to lead the Intel Japan Design Center, and in 2000 became a professor at the University of Aizu."], "facts": ["Born Shizuoka, Japan, 1943", "Joined Busicom 1967", "Logic design on the 4004; designer of the 8080 and Z80", "CHM Fellow 2009; Kyoto Prize"], "sources": [{"title": "Computer History Museum: Masatoshi Shima, CHM Fellow", "url": "https://computerhistory.org/profile/masatoshi-shima/"}, {"title": "Wikipedia: Masatoshi Shima", "url": "https://en.wikipedia.org/wiki/Masatoshi_Shima"}], "uncertain": ["Popular story that Shima arrived at Intel in 1970 to find little progress and was angry comes from Faggin's/Shima's recollections; not in the fetched sources, so omitted from the story."], "src": "chips-and-networks"}, {"id": "engelbart", "section": "personal", "name": "Douglas Engelbart", "years": "1925–2013", "role": "The dreamer who invented the mouse and showed the future in one afternoon", "photo": "people/engelbart.jpg", "w": 235, "h": 322, "credit": "Photo: SRI International. License: CC BY-SA 3.0 (https://creativecommons.org/licenses/by-sa/3.0/). Source: https://commons.wikimedia.org/wiki/File:SRI_Douglas_Engelbart_1968_(cropped).jpg", "story": ["Douglas Engelbart was born in Portland, Oregon, in 1925. Midway through college he served in the US Navy as a radio and radar technician in the Philippines.", "There, on the island of Leyte, in a hut on stilts, he read Vannevar Bush's essay 'As We May Think', about machines that could help people handle knowledge.", "In December 1950, newly engaged, he realized he had no real career goal beyond a steady job. Over the next months he settled on a big one: use computers to boost humanity's ability to solve complex, urgent problems.", "He knew from radar that information could be shown on a screen. He imagined people sitting at display 'working stations', flying through information.", "At the Stanford Research Institute (SRI) he founded the Augmentation Research Center. With his lead engineer Bill English he built the mouse: a wooden shell with two metal wheels. The patent called it an 'X-Y position indicator for a display system'.", "On December 9, 1968, in San Francisco, he demonstrated his system, NLS, live. The audience saw a mouse, hypertext links, multiple windows, shared-screen collaboration and on-screen video conferencing.", "Decades later people named it 'the Mother of All Demos'. Much of what we now do every day was on that stage.", "He received the Turing Award in 1997 and the National Medal of Technology in 2000. His favorite saying: 'The better we get at getting better, the faster we will get better.' He died in 2013."], "facts": ["Read 'As We May Think' while a Navy radar tech in the Philippines", "Mouse patent filed 1967, granted 1970 (US 3,541,541)", "'Mother of All Demos', Dec 9, 1968", "Turing Award 1997; National Medal of Technology 2000"], "sources": [{"title": "Computer History Museum: Douglas C. Engelbart, CHM Fellow", "url": "https://computerhistory.org/profile/doug-engelbart/"}, {"title": "Doug Engelbart Institute: Firsts — The Demo", "url": "https://dougengelbart.org/content/view/209/448/"}, {"title": "National Inventors Hall of Fame: Douglas Engelbart", "url": "https://www.invent.org/inductees/douglas-engelbart"}, {"title": "Wikipedia: Douglas Engelbart", "url": "https://en.wikipedia.org/wiki/Douglas_Engelbart"}, {"title": "Wikipedia: The Mother of All Demos", "url": "https://en.wikipedia.org/wiki/The_Mother_of_All_Demos"}], "uncertain": ["Augmentation Research Center founding year: CHM says 1959, other sources say early 1960s."], "src": "chips-and-networks"}, {"id": "kay", "section": "personal", "name": "Alan Kay", "years": "born 1940", "role": "Former jazz guitarist who imagined the laptop for kids, and helped build it", "photo": "people/kay.jpg", "w": 720, "h": 479, "credit": "Photo: Marcin Wichary from San Francisco, U.S.A.. License: CC BY 2.0 (https://creativecommons.org/licenses/by/2.0/). Source: https://commons.wikimedia.org/wiki/File:Alan_Kay_and_the_prototype_of_the_Dynabook_(3009206205).jpg", "story": ["Alan Kay has had an unusual path. Among other things, he was a professional jazz guitarist and taught guitar in Denver for a year.", "He served in the US Air Force, then in 1966 started graduate school at the University of Utah, earning a PhD in computer science in 1969.", "At Utah he studied with Ivan Sutherland, creator of Sketchpad, a 1963 program where you drew directly on a screen. Kay credits it as a big influence.", "In 1968 he met Seymour Papert, who was teaching children to program with a language called Logo. That led Kay to learning theorists like Jean Piaget, and to a lifelong question: how do children learn by making things?", "At Xerox PARC in the 1970s he conceived the Dynabook: a personal computer the size of a notebook, designed as a tool for learning. It is an ancestor of laptops, tablets and e-books.", "His Learning Research Group, with Dan Ingalls and Adele Goldberg, built Smalltalk, where everything is an object sending messages. It deeply shaped modern programming.", "Kay is also the architect of the overlapping-window interface we all use.", "He later worked at Apple, Disney Imagineering, and his own Viewpoints Research Institute. He received the Turing Award in 2003 and the Draper Prize."], "facts": ["Former professional jazz guitarist", "PhD, University of Utah, 1969", "Conceived the Dynabook at Xerox PARC", "Turing Award 2003"], "sources": [{"title": "Computer History Museum: Alan Kay, CHM Fellow", "url": "https://computerhistory.org/profile/alan-kay/"}, {"title": "Computer History Museum: Adele Goldberg, CHM Fellow", "url": "https://computerhistory.org/profile/adele-goldberg/"}, {"title": "Wikipedia: Alan Kay", "url": "https://en.wikipedia.org/wiki/Alan_Kay"}, {"title": "Wikipedia: Dynabook", "url": "https://en.wikipedia.org/wiki/Dynabook"}], "uncertain": ["'The best way to predict the future is to invent it' is often attributed to Kay; not verified in fetched sources, so not used."], "src": "chips-and-networks"}, {"id": "lampson", "section": "personal", "name": "Butler Lampson", "years": "born 1943", "role": "The systems thinker behind the Alto's software, Bravo and much more", "photo": "people/lampson.jpg", "w": 270, "h": 359, "credit": "Photo: Duncan.Hull. License: CC BY-SA 4.0 (https://creativecommons.org/licenses/by-sa/4.0/). Source: https://commons.wikimedia.org/wiki/File:Butler_Lampson_Royal_Society_(cropped).jpg", "story": ["Butler Lampson was born in Washington, DC, in 1943. He studied physics at Harvard, then earned a PhD at UC Berkeley in 1967.", "At Berkeley he was part of Project Genie, which built one of the early time-sharing systems, letting many people share one big computer at once (the SDS 940).", "Several of the Genie team tried to sell such systems through Berkeley Computer Corporation. It failed, but its people became the core of the computer lab at the new Xerox PARC.", "In 1972 Lampson wrote a memo, 'Why Alto?', arguing that cheap, powerful personal computers would change everything. 'If our theories… are correct,' he wrote, 'we should be able to demonstrate them convincingly on Alto.'", "He helped design the Alto and much of what ran on it, including Bravo, the first WYSIWYG ('what you see is what you get') text editor, an ancestor of Microsoft Word.", "He also worked on laser printing, page description languages, Ethernet encryption and computer security.", "Later he worked at Digital Equipment's Systems Research Center and at Microsoft. He received the Turing Award in 1992."], "facts": ["PhD UC Berkeley 1967", "Project Genie / SDS 940 time-sharing", "'Why Alto?' memo, 1972; Bravo editor", "Turing Award 1992"], "sources": [{"title": "Computer History Museum: Butler Lampson, CHM Fellow", "url": "https://computerhistory.org/profile/butler-lampson/"}, {"title": "Wikipedia: Butler Lampson", "url": "https://en.wikipedia.org/wiki/Butler_Lampson"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "thacker", "section": "personal", "name": "Chuck Thacker", "years": "1943–2017", "role": "Hardware designer of the Xerox Alto, the first true personal workstation", "photo": "people/thacker.jpg", "w": 548, "h": 720, "credit": "Photo: Marcin Wichary from San Francisco, U.S.A.. License: CC BY 2.0 (https://creativecommons.org/licenses/by/2.0/). Source: https://commons.wikimedia.org/wiki/File:Chuckthacker_(cropped).jpg", "story": ["Charles 'Chuck' Thacker was born in Pasadena, California, in 1943 and studied physics at UC Berkeley.", "His first job was at Berkeley Computer Corporation, where he led the design of the processor and memory. When BCC failed, he joined Xerox PARC's new Computer Science Laboratory.", "There he led the hardware for the Alto (1973): a desk-sized machine with a full-page screen, a mouse, and a graphical interface. It is often called the first computer built around a mouse-driven GUI.", "He also co-invented Ethernet, the way computers in a building talk over a cable, and contributed to the world's first laser printer.", "His motto, quoted by the Computer History Museum: 'Complexity is the enemy — Exterminate features.'", "In 1983 he helped found Digital Equipment's Systems Research Center. In 1997 he helped set up Microsoft's research lab in Cambridge, England.", "Back in the US he designed the first prototypes of Microsoft's Tablet PC, drawing on the 'interim Dynabook' ideas from PARC.", "He won the Turing Award in 2009 and died in 2017."], "facts": ["Led hardware design of the Xerox Alto (1973)", "Co-inventor of Ethernet", "Designed first Tablet PC prototypes at Microsoft", "Turing Award 2009"], "sources": [{"title": "Computer History Museum: Charles Thacker, CHM Fellow", "url": "https://computerhistory.org/profile/charles-thacker/"}, {"title": "Wikipedia: Chuck Thacker", "url": "https://en.wikipedia.org/wiki/Charles_P._Thacker"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "goldberg", "section": "personal", "name": "Adele Goldberg", "years": "born 1945", "role": "Co-developer of Smalltalk who spread object-oriented programming", "photo": "people/goldberg.jpg", "w": 720, "h": 564, "credit": "Photo: Terry Hancock. License: CC BY-SA 2.5 (https://creativecommons.org/licenses/by-sa/2.5/). Source: https://commons.wikimedia.org/wiki/File:Adele_Goldberg_at_PyCon_2007.jpg", "story": ["Adele Goldberg was born in Cleveland, Ohio, in 1945, and moved to Chicago at 11. She loved problem solving and math.", "She earned a math degree at the University of Michigan in 1967, then a master's and PhD in information science at the University of Chicago, finishing in 1973.", "Her thesis was an early AI-style program for computer-assisted teaching. Education stayed at the heart of her work.", "At Xerox PARC she worked with Alan Kay and Dan Ingalls on Smalltalk and on the Dynabook vision of computers for learning.", "She led efforts to explain Smalltalk to the world. The 'Smalltalk-80' books she co-wrote taught a generation of programmers object-oriented thinking.", "When Steve Jobs visited PARC and demanded a demo of Smalltalk, Goldberg at first refused. Her bosses made her do it. Apple went on to use many PARC ideas in the Macintosh.", "She was president of the ACM, the main computing society, from 1984 to 1986, and later co-founded ParcPlace Systems to sell Smalltalk tools.", "With Kay and Ingalls she received the 1987 ACM Software Systems Award, and the CHM made her a Fellow in 2022."], "facts": ["PhD University of Chicago 1973", "Co-developer of Smalltalk at Xerox PARC", "ACM President 1984–86", "CHM Fellow 2022"], "sources": [{"title": "Computer History Museum: Adele Goldberg, CHM Fellow", "url": "https://computerhistory.org/profile/adele-goldberg/"}, {"title": "Wikipedia: Adele Goldberg", "url": "https://en.wikipedia.org/wiki/Adele_Goldberg_(computer_scientist)"}], "uncertain": ["The refusal-to-demo-for-Jobs story is Goldberg's own account (as reported on Wikipedia)."], "src": "chips-and-networks"}, {"id": "taylor", "section": "personal", "name": "Bob Taylor", "years": "1932–2017", "role": "The research manager who launched ARPANET and built Xerox PARC's dream team", "photo": "people/taylor.jpg", "w": 720, "h": 540, "credit": "Photo: Gardner Campbell. License: CC BY-SA 2.0 (https://creativecommons.org/licenses/by-sa/2.0/). Source: https://commons.wikimedia.org/wiki/File:Bob_Taylor_in_2008.jpg", "story": ["Robert Taylor was born in Dallas, Texas, in 1932 and adopted by a Methodist minister's family.", "He studied experimental psychology, especially how the brain processes sound, and earned a master's in 1959. He chose not to finish a psychology PhD.", "He moved into research management at NASA and then ARPA. In his Pentagon office he had three separate terminals, each linked to a different computer in a different city.", "Each system had its own community of users, cut off from the others. Taylor thought: why not link them so one terminal reaches them all?", "In February 1966 he persuaded ARPA's director to fund a network, and that June he became director of ARPA's computing office. He shepherded the ARPANET until 1969.", "With J. C. R. Licklider he wrote the 1968 paper 'The Computer as a Communication Device', which predicted much of what the internet became.", "In 1970 he founded and later ran the Computer Science Laboratory at Xerox PARC. He was not an engineer himself; his gift was finding brilliant people and keeping them talking.", "His lab produced the Alto, Ethernet, laser printing and WYSIWYG editing. He later founded DEC's Systems Research Center, received the National Medal of Technology in 1999 and the Draper Prize in 2004, and died in 2017."], "facts": ["Three terminals in his Pentagon office inspired ARPANET", "Started ARPANET project, 1966", "'The Computer as a Communication Device' with Licklider, 1968", "Founded PARC's Computer Science Laboratory, 1970"], "sources": [{"title": "Internet Hall of Fame: Robert Taylor", "url": "https://www.internethalloffame.org/inductee/robert-taylor/"}, {"title": "Wikipedia: Robert Taylor", "url": "https://en.wikipedia.org/wiki/Robert_Taylor_(computer_scientist)"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "wozniak", "section": "personal", "name": "Steve Wozniak", "years": "born 1950", "role": "The engineer's engineer behind the Apple I and Apple II", "photo": "people/wozniak.jpg", "w": 541, "h": 720, "credit": "Photo: Gage Skidmore. License: CC BY-SA 3.0 (https://creativecommons.org/licenses/by-sa/3.0/). Source: https://commons.wikimedia.org/wiki/File:Steve_Wozniak_by_Gage_Skidmore_3_(cropped).jpg", "story": ["Steve Wozniak was born in San Jose in 1950. According to the Computer History Museum, he built his first computer at 13 and was an electronics prodigy in high school.", "In 1971 he and a friend built a computer they named 'Cream Soda' after their favorite drink. A newspaper reporter stepped on the power cable and blew it up, but Woz called it a good prelude.", "At 19 he met 14-year-old Steve Jobs. Their first project together was a 'blue box' that tricked the phone network into free calls.", "While designing calculators at Hewlett-Packard, he went to the Homebrew Computer Club and designed a kit computer of his own: the Apple I.", "A local store ordered 50 assembled units. That convinced Jobs there was a business. They founded Apple in 1976.", "The Apple II (1977) was Woz's masterpiece: color graphics, a built-in keyboard, a friendly case, and famously efficient circuits.", "In 1981 he was badly hurt in a plane crash and stepped away for a while. He left Apple in 1985, the year he and Jobs received the National Medal of Technology.", "He later went back to finish his degree at UC Berkeley (1986), made the first programmable universal remote, and put much of his energy into technology in schools.", "His own words, via CHM: 'My dream was actually just to have a computer some day.'"], "facts": ["Designed the Apple I (1976) and Apple II (1977)", "Co-founded Apple, 1976", "National Medal of Technology 1985", "BS UC Berkeley 1986"], "sources": [{"title": "Computer History Museum: Steve Wozniak, CHM Fellow", "url": "https://computerhistory.org/profile/steve-wozniak/"}, {"title": "Wikipedia: Steve Wozniak", "url": "https://en.wikipedia.org/wiki/Steve_Wozniak"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "jobs", "section": "personal", "name": "Steve Jobs", "years": "1955–2011", "role": "Apple co-founder who brought the graphical interface to everyone", "photo": "people/jobs.jpg", "w": 541, "h": 720, "credit": "Photo: Matthew Yohe. License: CC BY-SA 3.0 (https://creativecommons.org/licenses/by-sa/3.0/). Source: https://commons.wikimedia.org/wiki/File:Steve_Jobs_Headshot_2010_(cropped_4).jpg", "story": ["Steve Jobs was born in San Francisco in 1955 and adopted as a baby by Paul and Clara Jobs. He grew up in Mountain View, where his father built a workbench in the garage.", "He attended Reed College in 1972 but withdrew the same year. In 1974 he traveled through India, and later studied Zen Buddhism.", "With Steve Wozniak he founded Apple in 1976. Woz built the machines; Jobs saw that ordinary people would want them, and pushed for products that looked and felt friendly.", "In 1979 he saw the Xerox Alto, with its mouse and windows, and grasped its commercial potential. That led to the Apple Lisa (1983) and then the Macintosh (1984).", "The Macintosh brought the mouse and the graphical interface to the mass market.", "In 1985 he was forced out of Apple. He founded NeXT, and in 1986 bought Lucasfilm's computer graphics group, which became Pixar and made Toy Story (1995), the first computer-animated feature film.", "In 1997 Apple bought NeXT, and Jobs came back as CEO of a company near bankruptcy. He then led the iMac, iPod, iPhone and iPad.", "He died of pancreatic cancer on October 5, 2011."], "facts": ["Co-founded Apple 1976", "Saw the Xerox Alto 1979; Macintosh 1984", "Founded NeXT; bought what became Pixar (1986)", "Returned to Apple 1997"], "sources": [{"title": "Wikipedia: Steve Jobs", "url": "https://en.wikipedia.org/wiki/Steve_Jobs"}], "uncertain": ["No non-Wikipedia source fetched for Jobs (CHM profile 404). Facts are mainstream and uncontroversial."], "src": "chips-and-networks"}, {"id": "gates", "section": "personal", "name": "Bill Gates", "years": "born 1955", "role": "Microsoft co-founder who put software on nearly every PC", "photo": "people/gates.jpg", "w": 539, "h": 720, "credit": "Photo: Bogdan Hoyaux / European Union. License: CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Source: https://commons.wikimedia.org/wiki/File:Bill_Gates_at_the_European_Commission_-_P067383-987995_(cropped)_5.jpg", "story": ["Bill Gates grew up in Seattle and went to Lakeside School. In 1968 the school's Mothers' Club used rummage-sale money to buy a Teletype terminal and time on a remote computer.", "Eighth-grader Gates was hooked. There he became friends with an older student, Paul Allen.", "The boys traded bug-finding for free computer time at a local company, and studied the source code of real programs.", "He went to Harvard in 1973 and took graduate-level computer science, but dropped out in 1975 when the Altair 8800 kit computer appeared. He and Allen wrote a BASIC for it and founded Microsoft.", "In 1980 IBM needed an operating system for its coming PC. Microsoft bought one from Seattle Computer Products, adapted it as MS-DOS, and kept the right to license it to other makers.", "As IBM-compatible clones multiplied, Microsoft's software went with them. Windows followed.", "Gates moved from day-to-day Microsoft work to the Gates Foundation in 2008. In 2010, with Melinda French Gates and Warren Buffett, he started the Giving Pledge."], "facts": ["Learned programming on a Teletype at Lakeside School", "Co-founded Microsoft 1975", "MS-DOS licensed for the IBM PC (1981)", "Focus on Gates Foundation from 2008"], "sources": [{"title": "Computer History Museum: Bill Gates", "url": "https://computerhistory.org/profile/bill-gates/"}, {"title": "Wikipedia: Bill Gates", "url": "https://en.wikipedia.org/wiki/Bill_Gates"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "allen", "section": "personal", "name": "Paul Allen", "years": "1953–2018", "role": "Microsoft's co-founder, the one who spotted the spark", "photo": "people/allen.jpg", "w": 576, "h": 720, "credit": "Photo: Miles Harris. License: CC BY-SA 3.0 (https://creativecommons.org/licenses/by-sa/3.0/). Source: https://commons.wikimedia.org/wiki/File:Paul_G._Allen_(cropped).jpg", "story": ["Paul Allen was born in Seattle in 1953, the son of a schoolteacher and a librarian. He was two years older than Bill Gates when they met at Lakeside School.", "As teens they went 'dumpster diving' for discarded program code, Allen later said, and founded a small company, Traf-O-Data, to analyze traffic counts using an Intel 8008 chip.", "The January 1975 issue of Popular Electronics featured the Altair 8800, a kit computer built on Intel's 8080. Allen and Gates saw their moment: personal computers were arriving, and they would need software.", "They wrote a BASIC for the Altair, and Allen flew to Albuquerque to show it to MITS, the Altair's maker. It worked.", "They founded Microsoft in 1975. In 1980 Allen arranged the deal to buy QDOS (the 'Quick and Dirty Operating System'), written by Tim Paterson at Seattle Computer Products. It became MS-DOS for the IBM PC.", "Diagnosed with Hodgkin lymphoma, Allen left day-to-day work at Microsoft in 1982–83, though he stayed on the board.", "His second act was huge: he founded the Allen Institute for Brain Science and later institutes for AI and cell science, and bought the Seattle Seahawks and Portland Trail Blazers.", "In 2004 he was the sole funder of SpaceShipOne, the first privately funded crewed spacecraft to reach space.", "He died of complications of non-Hodgkin lymphoma on October 15, 2018, at 65."], "facts": ["Co-founded Microsoft, 1975", "Arranged the QDOS purchase that became MS-DOS", "Funded SpaceShipOne (2004)", "Founded the Allen Institute for Brain Science"], "sources": [{"title": "Computer History Museum: Paul Allen", "url": "https://computerhistory.org/profile/paul-allen/"}, {"title": "PaulAllen.com (official legacy site)", "url": "https://www.paulallen.com/"}, {"title": "Wikipedia: Paul Allen", "url": "https://en.wikipedia.org/wiki/Paul_Allen"}], "uncertain": ["The often-told scene of Allen running to show Gates the magazine is from Allen's memoir; not in fetched sources, so phrased neutrally.", "Year Allen left Microsoft: sources say 1982 or early 1983 (CHM: 1983)."], "src": "chips-and-networks"}, {"id": "conway", "section": "personal", "name": "Lynn Conway", "years": "1938–2024", "role": "Chip-design pioneer who rebuilt her career and changed how chips are made", "photo": "people/conway.jpg", "w": 541, "h": 720, "credit": "Photo: Charles Rogers. License: CC BY-SA 2.5 (https://creativecommons.org/licenses/by-sa/2.5/). Source: https://commons.wikimedia.org/wiki/File:Lynn_Conway_July_2006.jpg", "story": ["Lynn Conway was born in Mount Vernon, New York, in 1938. She entered MIT at 17, then earned degrees at Columbia.", "At IBM Research she worked on the Advanced Computing Systems project and made foundational contributions to computer architecture, including a way for a processor to issue several instructions out of order at once.", "In 1968 IBM fired her as she underwent gender transition.", "She started over in a new identity, rose quickly to become a computer architect at Memorex, and joined Xerox PARC in 1973 — while keeping her past hidden for decades.", "At PARC she invented scalable design rules for very large-scale integration (VLSI) chips and became the principal author, with Caltech's Carver Mead, of 'Introduction to VLSI Systems' (1980).", "In 1978, as a visiting professor at MIT, she taught a famous course from a draft of the book. Students designed real chips.", "Her MPC79 project then let students at many universities have their designs made together on shared wafers. That grew into MOSIS (1981), an early version of today's 'design here, manufacture there' chip industry.", "The textbook was used at nearly 120 universities by 1983. In 2020 IBM formally apologized to her. She died in 2024."], "facts": ["Fired by IBM in 1968 during her transition", "Mead & Conway, 'Introduction to VLSI Systems' (1980)", "MIT VLSI course 1978; MPC79 → MOSIS", "IBM apology 2020"], "sources": [{"title": "Computer History Museum: Lynn Conway, CHM Fellow", "url": "https://computerhistory.org/profile/lynn-conway/"}, {"title": "National Inventors Hall of Fame: Lynn Conway", "url": "https://www.invent.org/inductees/lynn-conway"}, {"title": "Wikipedia: Lynn Conway", "url": "https://en.wikipedia.org/wiki/Lynn_Conway"}], "uncertain": ["IBM's 2020 apology is per Wikipedia; NYT source was paywalled (403)."], "src": "chips-and-networks"}, {"id": "licklider", "section": "network", "name": "J. C. R. Licklider", "years": "1915–1990", "role": "The psychologist who dreamed up an 'Intergalactic Computer Network'", "photo": "people/licklider.jpg", "w": 540, "h": 720, "credit": "Photo: Unknown author. License: Public domain. Source: https://commons.wikimedia.org/wiki/File:Portrait_of_J._C._R._Licklider.jpg", "story": ["Joseph Carl Robnett Licklider — 'Lick' to everyone — was born in St. Louis in 1915, the only child of a Baptist minister.", "At Washington University he triple-majored in physics, math and psychology. He earned a PhD at the University of Rochester and became an expert in how people hear.", "At MIT in the 1950s he helped set up Lincoln Laboratory and worked on SAGE, a huge air-defense computer system. Watching people work with machines changed his thinking.", "In 1957 he joined the research firm BBN, where he learned about time-sharing and ran an early public demonstration of it.", "In 1960 he wrote 'Man-Computer Symbiosis'. His idea: humans and computers should work as partners, each doing what they do best, in real time.", "In 1962 he became the first head of ARPA's computing office. In memos to the researchers he funded, he jokingly described an 'Intergalactic Computer Network' linking them all.", "His successors, including Bob Taylor, turned that dream into ARPANET. Together, Licklider and Taylor wrote 'The Computer as a Communication Device' in 1968.", "The Internet Hall of Fame notes he foresaw graphical computing, digital libraries, online banking and cloud computing. He died in 1990, the same year ARPANET formally shut down."], "facts": ["'Man-Computer Symbiosis', 1960", "First director of ARPA's IPTO, 1962", "'Intergalactic Computer Network' memos, 1962–63", "Co-wrote 'The Computer as a Communication Device', 1968"], "sources": [{"title": "Internet Hall of Fame: J.C.R. Licklider", "url": "https://www.internethalloffame.org/inductee/jcr-licklider/"}, {"title": "Licklider, 'Man-Computer Symbiosis' (1960), full text at MIT", "url": "https://groups.csail.mit.edu/medg/people/psz/Licklider.html"}, {"title": "Wikipedia: J. C. R. Licklider", "url": "https://en.wikipedia.org/wiki/J._C._R._Licklider"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "baran", "section": "network", "name": "Paul Baran", "years": "1926–2011", "role": "Designed a network that could survive a nuclear war", "photo": "people/baran.jpg", "w": 175, "h": 237, "credit": "Photo: Andreu Veà, WiWiW.org. License: CC BY-SA 3.0 (https://creativecommons.org/licenses/by-sa/3.0/). Source: https://commons.wikimedia.org/wiki/File:Paul_Baran.jpg", "story": ["Paul Baran was born Pesach Baran in Grodno, Poland (now Belarus), in 1926. His family came to the United States when he was two, and his father opened a grocery store in Philadelphia.", "He earned an electrical engineering degree at Drexel in 1949 and went to work as a technician on the UNIVAC, one of the first commercial computers.", "He later worked on radar data systems at Hughes Aircraft and earned a master's at UCLA, then joined the RAND Corporation in 1959.", "It was the Cold War. Baran's question was chilling: could a communications network survive a nuclear attack and still keep working?", "His answer was a mesh of many connected nodes, with no single center to destroy. Messages would be cut into small 'message blocks' that each found their own way, routing around damage.", "He laid it all out in 'On Distributed Communications', a multi-volume set of RAND reports published in 1964 (the CHM counts 13 volumes).", "AT&T's engineers scoffed. The phone company was built on dedicated circuits, and some told him he simply didn't understand telephones.", "His ideas found their way into ARPANET's planning anyway. Later he kept inventing: in 1985 he founded Metricom, whose Ricochet was an early public wireless mesh network, and in 1992 Com21, an early cable-modem company.", "He died in 2011. RAND's president said the world was better for both his technologies and his conscience."], "facts": ["Born in Grodno, 1926", "Joined RAND 1959", "'On Distributed Communications', 1964", "Founded Metricom (1985) and Com21 (1992)"], "sources": [{"title": "Computer History Museum: Paul Baran, CHM Fellow", "url": "https://computerhistory.org/profile/paul-baran/"}, {"title": "Internet Hall of Fame: Paul Baran", "url": "https://www.internethalloffame.org/inductee/paul-baran/"}, {"title": "National Inventors Hall of Fame: Paul Baran", "url": "https://www.invent.org/inductees/paul-baran"}, {"title": "ETHW Oral History: Paul Baran", "url": "https://ethw.org/Oral-History:Paul_Baran"}, {"title": "Wikipedia: Paul Baran", "url": "https://en.wikipedia.org/wiki/Paul_Baran"}], "uncertain": ["Number of ODC volumes: CHM says 13; other sources count 11 or 12."], "src": "chips-and-networks"}, {"id": "davies", "section": "network", "name": "Donald Davies", "years": "1924–2000", "role": "The Welsh physicist who named the 'packet'", "photo": "people/davies.jpg", "w": 640, "h": 531, "credit": "Photo: Jaggery (geograph.org.uk) — photo of his blue plaque in Treorchy, not a portrait. License: CC BY-SA 2.0 (https://creativecommons.org/licenses/by-sa/2.0/). Source: https://commons.wikimedia.org/wiki/File:Donald_Watts_Davies_blue_plaque,_Treorchy_-_geograph.org.uk_-_6415017.jpg", "story": ["Donald Davies was born in Treorchy, in the Rhondda Valley of Wales, in 1924. His father, a clerk at a coal mine, died a few months later, and his mother took Donald and his twin sister to Portsmouth.", "After studying physics and math at Imperial College London, he joined the National Physical Laboratory (NPL) in 1947 — where Alan Turing was designing a computer called ACE.", "Young Davies spotted mistakes in Turing's famous 1936 paper, much to Turing's annoyance. They may have been some of the first 'bugs' ever found.", "When Turing left, Davies helped finish a smaller version, the Pilot ACE, which first ran in May 1950.", "In 1965, after visiting MIT and talking about time-sharing, he had an idea: split messages into short, fixed-size chunks and send them separately. He called the chunks 'packets', a word that stuck.", "He had reached the same idea as Paul Baran, independently. His colleague Roger Scantlebury presented the NPL design at a 1967 conference, and it caught the ARPANET planners' attention.", "Davies built the world's first working packet-switched network at NPL. Parts went live in 1969, and the full Mark I network was running in January 1970. It stayed in use until 1986.", "Later he worked on data security. He died in 2000. Cerf and Kahn acknowledged Davies and Scantlebury in their landmark 1974 paper."], "facts": ["Born Treorchy, Wales, 1924", "Helped complete the Pilot ACE (1950)", "Coined 'packet' (1965)", "NPL network fully operational January 1970"], "sources": [{"title": "Internet Hall of Fame: Donald Davies", "url": "https://www.internethalloffame.org/inductee/donald-davies/"}, {"title": "National Inventors Hall of Fame: Donald Davies", "url": "https://www.invent.org/inductees/donald-watts-davies"}, {"title": "Wikipedia: Donald Davies", "url": "https://en.wikipedia.org/wiki/Donald_Davies"}, {"title": "Wikipedia: NPL network", "url": "https://en.wikipedia.org/wiki/NPL_network"}], "uncertain": ["Photo is of his blue plaque in Treorchy, not a portrait (no free portrait found)."], "src": "chips-and-networks"}, {"id": "kleinrock", "section": "network", "name": "Leonard Kleinrock", "years": "born 1934", "role": "The mathematician of network traffic, whose lab sent the first ARPANET message", "photo": "people/kleinrock.jpg", "w": 710, "h": 700, "credit": "Photo: TippyZora. License: CC BY-SA 4.0 (https://creativecommons.org/licenses/by-sa/4.0/). Source: https://commons.wikimedia.org/wiki/File:Kleinrock_headshot.png", "story": ["Leonard Kleinrock was born in New York City in 1934 and graduated from the Bronx High School of Science in 1951.", "He studied electrical engineering at City College of New York at night while working, then won a fellowship to MIT.", "His 1962 MIT thesis used queueing theory — the math of waiting lines — to understand how messages flow through networks and where they get delayed. It became a 1964 book.", "He joined UCLA in 1963, and his lab there became the first node of ARPANET.", "At 10:30 pm on October 29, 1969, his student Charley Kline tried to log in to a computer at the Stanford Research Institute. He typed 'L', then 'O'... and the system crashed.", "So the first message on the network that became the internet was 'lo', as in 'lo and behold'. About an hour later, the full login worked.", "In the 1970s Kleinrock measured and modeled real packet networks. His work on hierarchical routing with student Farouk Kamoun still underpins how the internet finds paths.", "Many of his students went on to help build the internet's protocols. He received the National Medal of Science in 2007."], "facts": ["Bronx High School of Science, 1951", "Queueing-theory thesis, MIT 1962", "UCLA: first ARPANET node; 'LO' sent Oct 29, 1969", "National Medal of Science 2007"], "sources": [{"title": "Internet Hall of Fame: Leonard Kleinrock", "url": "https://www.internethalloffame.org/inductee/leonard-kleinrock/"}, {"title": "ETHW Oral History: Leonard Kleinrock", "url": "https://ethw.org/Oral-History:Leonard_Kleinrock"}, {"title": "Wikipedia: Leonard Kleinrock", "url": "https://en.wikipedia.org/wiki/Leonard_Kleinrock"}, {"title": "Wikipedia: ARPANET", "url": "https://en.wikipedia.org/wiki/ARPANET"}], "uncertain": ["Kleinrock's priority claim for packet-switching theory is disputed by some historians (see Wikipedia 'Packet switching')."], "src": "chips-and-networks"}, {"id": "cerf", "section": "network", "name": "Vint Cerf", "years": "born 1943", "role": "Co-designer of TCP/IP, the internet's common language", "photo": "people/cerf.jpg", "w": 540, "h": 720, "credit": "Photo: Duncan.Hull. License: CC BY-SA 4.0 (https://creativecommons.org/licenses/by-sa/4.0/). Source: https://commons.wikimedia.org/wiki/File:Dr_Vint_Cerf_ForMemRS_(cropped).jpg", "story": ["Vinton Cerf was born in New Haven, Connecticut, in 1943. He has been hard of hearing since childhood.", "He earned a math degree at Stanford in 1965 and worked at IBM for two years, then went to UCLA for his master's and PhD (1972).", "At UCLA, in Kleinrock's lab, he helped write the protocols that let host computers talk over ARPANET.", "In spring 1973 Bob Kahn asked him to help solve a bigger problem: how to connect different networks, like radio and satellite networks, to each other.", "Together they designed TCP, first described publicly in May 1974. Later it was split into two layers: TCP for reliable delivery and IP for addressing and routing.", "Cerf was an assistant professor at Stanford from 1972 to 1976, then a program manager at DARPA from 1976 to 1982, overseeing the internet's growth.", "He and his wife Sigrid, who also has hearing loss, met at a hearing-aid office. He has long championed accessibility and sits on the board of Gallaudet University.", "He later served at Google as 'Chief Internet Evangelist'. With Kahn he won the 2004 Turing Award and the Presidential Medal of Freedom."], "facts": ["Co-designed TCP/IP with Bob Kahn (1973–74)", "DARPA program manager 1976–82", "Turing Award 2004 (with Kahn)", "Presidential Medal of Freedom"], "sources": [{"title": "Computer History Museum: Vinton Cerf, CHM Fellow", "url": "https://computerhistory.org/profile/vint-cerf/"}, {"title": "Internet Hall of Fame: Vint Cerf", "url": "https://www.internethalloffame.org/inductee/vint-cerf/"}, {"title": "National Inventors Hall of Fame: Vinton G. Cerf", "url": "https://www.invent.org/inductees/vinton-g-cerf"}, {"title": "Wikipedia: Vint Cerf", "url": "https://en.wikipedia.org/wiki/Vint_Cerf"}], "uncertain": ["Wikipedia (Oct 2026) lists his Google tenure as Oct 2005–July 2026; left as 'later served' to avoid dating."], "src": "chips-and-networks"}, {"id": "kahn", "section": "network", "name": "Bob Kahn", "years": "born 1938", "role": "ARPANET architect and co-inventor of TCP/IP", "photo": "people/kahn.jpg", "w": 720, "h": 720, "credit": "Photo: Steffen Fahl. License: Public domain. Source: https://commons.wikimedia.org/wiki/File:Robert_Kahn.jpg", "story": ["Robert Kahn was born in Brooklyn, New York, in December 1938. He studied electrical engineering at City College of New York, then earned a PhD at Princeton.", "He worked at Bell Labs and taught at MIT. Then he took leave to join the research firm BBN.", "At BBN he was responsible for the system design of ARPANET, and part of the team that built the IMP, the small computer that acted as each site's packet switch.", "In October 1972 he organized a public ARPANET demonstration in Washington, DC, connecting many different computers. Wikipedia quotes it as the event that made people realize packet switching was real.", "He then moved to DARPA. There he saw that radio and satellite networks would also need to connect, and started an 'internetting' project.", "In spring 1973 Vint Cerf joined him. Their design for TCP/IP was first described publicly in May 1974. ARPANET switched over on January 1, 1983.", "As head of DARPA's computing office he also launched the billion-dollar Strategic Computing Initiative.", "In 1986 he founded the Corporation for National Research Initiatives (CNRI). He received the Turing Award in 2004 and the Presidential Medal of Freedom in 2005."], "facts": ["System design of ARPANET at BBN", "Organized the 1972 ICCC ARPANET demo", "TCP/IP with Cerf, first public May 1974", "Founded CNRI 1986; Presidential Medal of Freedom 2005"], "sources": [{"title": "Computer History Museum: Robert Kahn, CHM Fellow", "url": "https://computerhistory.org/profile/robert-kahn/"}, {"title": "Internet Hall of Fame: Robert Kahn", "url": "https://www.internethalloffame.org/inductee/robert-kahn/"}, {"title": "National Inventors Hall of Fame: Robert E. Kahn", "url": "https://www.invent.org/inductees/robert-e-kahn"}, {"title": "ETHW Oral History: Robert Kahn (Charles Babbage Institute interview)", "url": "https://ethw.org/Oral-History:Robert_Kahn"}, {"title": "Wikipedia: Bob Kahn", "url": "https://en.wikipedia.org/wiki/Bob_Kahn"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "berners-lee", "section": "network", "name": "Tim Berners-Lee", "years": "born 1955", "role": "Inventor of the World Wide Web, who gave it away", "photo": "people/berners-lee.jpg", "w": 720, "h": 540, "credit": "Photo: Summit. License: CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Source: https://commons.wikimedia.org/wiki/File:Tim_Berners-Lee_at_the_2025_Web_Summit_(Cropped).jpg", "story": ["Tim Berners-Lee was born in London in 1955. Both of his parents worked on the Ferranti Mark 1, the first commercially built computer.", "He took a first-class physics degree at Oxford in 1976. While there, he built a computer out of an old television bought from a repair shop.", "In 1980, as a contractor at CERN in Geneva, he built a program called ENQUIRE for keeping track of linked information.", "Back at CERN later, he saw scientists struggling to share information across incompatible computers. In March 1989 he wrote a proposal for a system of linked documents.", "His manager, Mike Sendall, called it 'vague, but exciting'. With Robert Cailliau he got the project going.", "By the end of 1990 he had written the first web browser (which was also an editor) and the first web server. The first website went live on December 20, 1990.", "He designed the basic pieces we still use: URLs for addresses, HTTP to fetch pages, and HTML to write them.", "CERN made the web freely available to everyone in April 1993. That choice let it spread everywhere.", "He founded the World Wide Web Consortium (W3C) in 1994, was knighted in 2004, and won the 2016 Turing Award."], "facts": ["First website live Dec 20, 1990", "Proposal March 1989 ('vague, but exciting')", "Invented URLs, HTTP, HTML", "Founded W3C 1994; Turing Award 2016"], "sources": [{"title": "W3C: Tim Berners-Lee biography", "url": "https://www.w3.org/People/Berners-Lee/"}, {"title": "Berners-Lee, 'Information Management: A Proposal' (1989), W3C archive", "url": "https://www.w3.org/History/1989/proposal.html"}, {"title": "Internet Hall of Fame: Tim Berners-Lee", "url": "https://www.internethalloffame.org/inductee/tim-berners-lee/"}, {"title": "Computer History Museum: Tim Berners-Lee", "url": "https://computerhistory.org/profile/tim-berners-lee/"}, {"title": "Wikipedia: Tim Berners-Lee", "url": "https://en.wikipedia.org/wiki/Tim_Berners-Lee"}, {"title": "Wikipedia: World Wide Web", "url": "https://en.wikipedia.org/wiki/World_Wide_Web"}], "uncertain": [], "src": "chips-and-networks"}, {"id": "perlman", "section": "network", "name": "Radia Perlman", "years": "born 1951", "role": "The engineer whose spanning tree keeps networks from tangling", "photo": "people/perlman.jpg", "w": 480, "h": 720, "credit": "Photo: Scientist-100 at English Wikipedia. License: Public domain. Source: https://commons.wikimedia.org/wiki/File:Radia_Perlman_2009.jpg", "story": ["Radia Perlman was born in 1951 in Portsmouth, Virginia. Both of her parents were engineers for the US government.", "At MIT she got her first paid programming job in 1971 at the LOGO Lab of the AI Laboratory.", "Under Seymour Papert she created TORTIS, a way for small children — some as young as three and a half — to program a robot 'turtle' by pushing buttons.", "At Digital Equipment Corporation she faced a nasty problem: when network bridges are connected in loops, messages can circle forever and swamp everything.", "In 1985 she invented the Spanning Tree Protocol. The bridges quietly agree on a tree of paths with no loops, so there is exactly one active route between any two points. If a link breaks, they rebuild the tree.", "She even wrote a playful poem about it, called 'Algorhyme', modeled on Joyce Kilmer's 'Trees'.", "She later invented TRILL to fix spanning tree's limits, wrote the textbook 'Interconnections', and holds over 100 patents.", "She joined the Internet Hall of Fame in 2014 and the National Inventors Hall of Fame in 2016."], "facts": ["TORTIS: programming for preschoolers at MIT", "Invented the Spanning Tree Protocol at DEC, 1985", "Author of 'Interconnections'", "Internet Hall of Fame 2014; NIHF 2016"], "sources": [{"title": "Internet Hall of Fame: Radia Perlman", "url": "https://www.internethalloffame.org/inductee/radia-perlman/"}, {"title": "National Inventors Hall of Fame: Radia Perlman", "url": "https://www.invent.org/inductees/radia-perlman"}, {"title": "Wikipedia: Radia Perlman", "url": "https://en.wikipedia.org/wiki/Radia_Perlman"}, {"title": "Wikipedia: Spanning Tree Protocol", "url": "https://en.wikipedia.org/wiki/Spanning_Tree_Protocol"}], "uncertain": ["That Algorhyme is modeled on Kilmer's 'Trees' is widely known but was not confirmed in a fetched source."], "src": "chips-and-networks"}, {"id": "pascal", "section": "origins", "name": "Blaise Pascal", "years": "1623–1662", "role": "Teenage inventor of one of the first working mechanical calculators", "photo": "people/pascal.jpg", "w": 604, "h": 720, "credit": "Copy of a portrait by François II Quesnel, Palace of Versailles. Public domain, via Wikimedia Commons (File:Blaise_Pascal_Versailles.JPG)", "story": ["Blaise Pascal grew up in a house full of ideas. His mother died when he was a small child, and his father Étienne, a lawyer and keen amateur mathematician, chose to educate the children himself.", "In December 1639 the family moved to Rouen, where Étienne had been appointed a tax official for Upper Normandy. The job meant endless columns of figures, added and re-added by hand. His teenage son decided a machine should take over the drudgery.", "Blaise designed his calculator in 1642, when he was about 19. The hard part was the carry: when one wheel rolls past 9 back to 0, the next wheel has to move up by one. If many wheels need to carry at once, a simple gear chain jams.", "His fix was a little part called the sautoir, from the French word for 'jump'. Turning a wheel slowly lifted a weighted lever; at the right moment gravity let it drop and kick the next wheel on by one step. Pascal claimed a machine with ten thousand wheels would work as well as one with two, because each carry happened on its own.", "Getting from idea to object was a slog. He went through about fifty prototypes before presenting the machine publicly in 1645, dedicated to the Chancellor of France, Pierre Séguier. In 1649 King Louis XIV granted him a royal privilege, something like a patent, giving him the exclusive right to make and sell calculating machines in France.", "Commercially it disappointed. By around 1654 about twenty machines had been made, but they were costly and fiddly, and production stopped. Nine are known to survive today.", "Pascal's mind ran in many directions. He experimented on air pressure (the unit of pressure, the pascal, honours him), and in 1654 he and Pierre de Fermat worked out the foundations of probability in letters about a gambling puzzle. He then turned increasingly to religion and philosophy, writing the notes later published as the Pensées.", "He died in Paris in 1662 at 39. His machine showed something quietly radical: a box of gears could follow a rule of arithmetic perfectly without understanding anything. Around 1970, Niklaus Wirth named the programming language Pascal after him."], "facts": ["Designed his calculator in 1642, aged about 19", "About fifty prototypes before the 1645 public presentation", "Royal privilege for calculating machines, 1649", "About twenty built; nine survive", "Its carry used a gravity-driven 'sautoir'"], "sources": [{"title": "MacTutor History of Mathematics: Blaise Pascal", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Pascal/"}, {"title": "Stanford Encyclopedia of Philosophy: Blaise Pascal", "url": "https://plato.stanford.edu/entries/pascal/"}, {"title": "Pascal's calculator (detailed technical history, with museum holdings)", "url": "https://en.wikipedia.org/wiki/Pascal%27s_calculator"}], "uncertain": ["The 'about fifty prototypes' figure traces to Pascal's own account (cited by MacTutor via Adamson); it can't be independently counted.", "His mother's death (usually given as when he was about three) was not checked against a primary source."], "src": "early"}, {"id": "leibniz", "section": "origins", "name": "Gottfried Wilhelm Leibniz", "years": "1646–1716", "role": "Built the stepped reckoner and championed binary numbers", "photo": "people/leibniz.jpg", "w": 583, "h": 720, "credit": "Christoph Bernhard Francke, portrait c. 1695 (Herzog Anton Ulrich-Museum, Braunschweig). Public domain, via Wikimedia Commons", "story": ["Leibniz grew up in Leipzig, where his father was a professor of moral philosophy. His father died when he was six, but the boy was allowed into the family library and largely taught himself Latin and philosophy from its books.", "He never became a university professor. Instead he worked for princes and noblemen as a lawyer, diplomat, librarian and adviser, and did his philosophy and mathematics in between.", "In 1672 a diplomatic mission took him to Paris. By his own account, the idea for a calculating machine came to him there after seeing a pedometer. He wanted to go further than Pascal's adder: his machine would multiply and divide too.", "In January 1673 he visited the Royal Society in London and showed a model of his machine. It did not go perfectly: at a later meeting the scientist Robert Hooke made unfavourable comments about it. Even so, the Society elected him a fellow that April.", "His key invention was the stepped drum, now called the Leibniz wheel: a cylinder with nine teeth of increasing length. Slide a small gear along it, and one turn of the crank advances that gear by anywhere from zero to nine steps. Multiplication became repeated cranking.", "The full machine, the stepped reckoner, never worked reliably. Its gears needed more precision than craftsmen of the day could deliver, and its carry mechanism had a design flaw. One surviving machine was sent to the University of Göttingen for repair in 1775, forgotten, and found by workmen in an attic in 1876. It is now in Hanover.", "The drum itself was a triumph. It became the heart of the Arithmometer, the first commercially successful calculator, and of many machines that followed.", "Leibniz also wrote up binary arithmetic, counting with only 0 and 1, and published his explanation in 1703. He was struck that the hexagrams of the Chinese I Ching could be read as binary numbers. He was not the very first: the English astronomer Thomas Harriot had worked with binary decades earlier, in unpublished notes. He also dreamed of a symbolic language in which disagreements could be settled by calculating.", "His last years were lonely. A bitter dispute over whether he or Newton invented calculus damaged his reputation, and his employers had lost interest in him. When he died in 1716, no courtier except his own secretary is said to have attended the funeral."], "facts": ["Showed a calculating machine to the Royal Society in 1673", "Invented the stepped drum (Leibniz wheel)", "Surviving stepped reckoner rediscovered in a Göttingen attic in 1876", "Published his explanation of binary arithmetic in 1703"], "sources": [{"title": "MacTutor: Gottfried Wilhelm Leibniz", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Leibniz/"}, {"title": "Stanford Encyclopedia of Philosophy: Gottfried Wilhelm Leibniz", "url": "https://plato.stanford.edu/entries/leibniz/"}, {"title": "Leibniz, 'Explanation of Binary Arithmetic' (1703), translated by Lloyd Strickland", "url": "https://www.leibniz-translations.com/binary.htm"}, {"title": "Stepped reckoner", "url": "https://en.wikipedia.org/wiki/Stepped_reckoner"}], "uncertain": ["The pedometer origin story comes from Leibniz himself.", "The funeral account (only his secretary from the court) is from Wikipedia and secondary sources."], "src": "early"}, {"id": "price", "section": "origins", "name": "Derek J. de Solla Price", "years": "1922–1983", "role": "Physicist-historian who first decoded the Antikythera mechanism's gearing", "photo": null, "w": null, "h": null, "credit": null, "story": ["In 1901 sponge divers off the Greek island of Antikythera recovered treasures from a Roman-era shipwreck. Among them was a corroded lump of bronze and wood. When it split apart, people spotted something baffling inside: gear teeth.", "For decades nobody could say what it was. Nothing with gearwork that fine was known from the ancient world.", "Derek Price was a London-born physicist who moved into the history of science. As a Cambridge PhD student he found a medieval astronomical manuscript, The Equatorie of the Planetis, and argued it was written by Geoffrey Chaucer. Scholars now attribute it to a St Albans monk, John Westwyk, but the find launched Price's career.", "He moved to the United States, studied ancient astronomy at the Institute for Advanced Study in Princeton, and in 1959 joined Yale, where he stayed for the rest of his career.", "He spent about twenty years on the Antikythera fragments, using techniques including gamma-ray imaging to see gears hidden inside the corroded lumps. In papers in 1959 and 1974 (the second, Gears from the Greeks) he argued that it was a geared astronomical calculator, dating from around 80 BCE.", "Price also helped found a new field: the measurement of science itself. In Little Science, Big Science (1963) he showed that the number of scientists and papers had been growing exponentially for centuries.", "He died in 1983, before modern X-ray CT scanning was applied to the fragments. The Antikythera Mechanism Research Project's 2006 paper in Nature, and a 2021 reconstruction from University College London, went far beyond his work, but they confirmed his central claim: this really was an ancient Greek calculating machine."], "facts": ["Studied the Antikythera fragments for about twenty years", "Published on it in 1959 and in Gears from the Greeks (1974)", "Dated the device to around 80 BCE", "Wrote Little Science, Big Science (1963)"], "sources": [{"title": "Derek J. de Solla Price", "url": "https://en.wikipedia.org/wiki/Derek_J._de_Solla_Price"}, {"title": "Freeth et al., 'Decoding the ancient Greek astronomical calculator known as the Antikythera Mechanism', Nature 444 (2006)", "url": "https://www.nature.com/articles/nature05357"}, {"title": "Freeth et al., 'A Model of the Cosmos in the ancient Greek Antikythera Mechanism', Scientific Reports 11 (2021)", "url": "https://www.nature.com/articles/s41598-021-84310-w"}], "uncertain": ["The mechanism's date is debated; Price's ~80 BCE is one estimate and later researchers propose earlier dates.", "Price's biography rests mainly on Wikipedia; no archive biography was checked."], "src": "early"}, {"id": "jacquard", "section": "engines", "name": "Joseph Marie Jacquard", "years": "1752–1834", "role": "Weaver whose punched-card loom became the model for programmable machines", "photo": "people/jacquard.jpg", "w": 654, "h": 720, "credit": "Portrait after Ephraïm Conquy. Public domain, via Wikimedia Commons (File:Joseph_Marie_Jacquard.jpg)", "story": ["Jacquard was born in Lyon, the silk capital of France, into a family of weavers. Patterned silk was slow, skilled work: on a draw loom, an assistant had to pull cords by hand to raise exactly the right threads for each row of the design.", "His early life was turbulent. He tried several trades, and when Lyon rebelled against the revolutionary government in 1793 and the rebellion was crushed, he and his son reportedly escaped by joining the revolutionary army.", "He was not the first to try automating the loom. In 1725 Basile Bouchon used a strip of punched paper to choose threads. Jean-Baptiste Falcon replaced the paper with a chain of punched cards. Jacques de Vaucanson built a mechanised loom in the 1740s.", "Jacquard pulled these ideas together. In 1803 he was called to Paris and attached to the Conservatoire des Arts et Métiers, where Vaucanson's loom was on display and gave him ideas. Starting in 1804 he perfected his own attachment.", "It read a chain of stiff punched cards, one card per row of the pattern. Where a card had a hole, a hook rose and lifted its thread; where it did not, the thread stayed down. Change the cards and you change the fabric without rebuilding the loom.", "In 1805 the invention was declared public property, and Jacquard was rewarded with a pension and a royalty on each machine. Many silk weavers fought it fiercely, fearing for their livelihoods, but it spread anyway.", "Its most famous showpiece came after his death: a woven silk portrait of Jacquard, made in 1839 by the weaver Michel-Marie Carquillat for the Lyon firm Didier, Petit et Cie. It took about 24,000 punched cards and looked so much like an engraving that experts mistook it for one.", "Charles Babbage owned a copy and loved to test guests with it. He later recalled showing it to Prince Albert and the Duke of Wellington. Jacquard's cards became the instruction cards of Babbage's Analytical Engine, then Hollerith's census cards, then the punched cards that fed computers into the 1970s."], "facts": ["Developed his loom attachment from 1804", "Built on Bouchon (1725), Falcon and Vaucanson", "Declared public property in 1805; Jacquard got a pension and royalties", "His 1839 woven portrait needed about 24,000 cards; Babbage owned a copy"], "sources": [{"title": "Joseph Marie Jacquard", "url": "https://en.wikipedia.org/wiki/Joseph_Marie_Jacquard"}, {"title": "Science History Institute, 'The French Connection' (Jacquard's woven portrait)", "url": "https://www.sciencehistory.org/stories/magazine/the-french-connection/"}, {"title": "Computer History Museum, Revolution: Punched cards", "url": "https://www.computerhistory.org/revolution/punched-cards/2"}, {"title": "The Metropolitan Museum of Art: woven portrait of Joseph Marie Jacquard (1839)", "url": "https://www.metmuseum.org/en/art/collection/search/222531"}], "uncertain": ["The army-escape story comes from historian Charles Ballot, as cited on Wikipedia.", "Dates for Falcon's work vary between sources (1728 or 1737).", "The Science History Institute says Jacquard went public in 1802; most sources say 1804."], "src": "early"}, {"id": "babbage", "section": "engines", "name": "Charles Babbage", "years": "1791–1871", "role": "Designed the Difference Engine and the general-purpose Analytical Engine", "photo": "people/babbage.jpg", "w": 460, "h": 720, "credit": "Photograph c. 1860, unknown author. Public domain, via Wikimedia Commons (File:Charles_Babbage_-_1860.jpg)", "story": ["Babbage was the son of a London banker, which gave him something rare: the money and time to chase ideas. At Cambridge he and friends including John Herschel and George Peacock formed the Analytical Society to modernise British mathematics.", "Mathematical tables were the search engines of his age. Navigators, engineers and astronomers depended on them, but they were computed, copied and typeset by hand, and errors crept in at every step. Babbage wanted a machine that would calculate and print them without mistakes.", "His Difference Engine used the method of finite differences, which turns the calculation of polynomials into nothing but repeated addition. Government funding began in the 1820s, and in 1823 he brought in the skilled engineer Joseph Clement to build it.", "It was too ambitious for its time. The parts needed precision at the edge of what workshops could manage, Babbage kept refining the design, and money disputes with Clement dragged on. Work stopped in 1834. By then the government had put in about £17,000, and Babbage around £6,000 of his own money. The government formally ended support in 1842.", "Meanwhile he had a bigger idea. The Analytical Engine had a 'store' for numbers, a 'mill' to do arithmetic, punched cards borrowed from Jacquard for instructions, and the ability to choose its next step based on a result. That is the basic shape of every computer since. It was never built.", "Babbage was a celebrity host. His Saturday evening soirées, held from 1828 into the 1840s, drew scientists, writers and aristocrats, and it was at one of them that the young Ada Byron first met him. He also wrote on economics, codes and much else, and waged a famous public campaign against the street musicians who disturbed his work.", "He died in 1871 believing he had been ignored. Then, between 1985 and 1991, London's Science Museum built his Difference Engine No. 2 from his own drawings, led by curator Doron Swade, for the 200th anniversary of his birth. It worked. It has about 8,000 parts and weighs about five tonnes. A second copy was shown at the Computer History Museum in California from 2008 to 2016."], "facts": ["Brought in engineer Joseph Clement in 1823", "Work stopped in 1834 after about £17,000 of government money", "Designed the Analytical Engine: store, mill, punched cards, branching", "Difference Engine No. 2 built and working at the Science Museum in 1991"], "sources": [{"title": "MacTutor: Charles Babbage", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Babbage/"}, {"title": "Computer History Museum: The Babbage Engine", "url": "https://www.computerhistory.org/babbage/"}, {"title": "Computer History Museum: The Engines", "url": "https://www.computerhistory.org/babbage/engines/"}, {"title": "Difference engine (construction history)", "url": "https://en.wikipedia.org/wiki/Difference_engine"}], "uncertain": ["The details of the Clement dispute were summarised from Wikipedia, not a primary source."], "src": "early"}, {"id": "lovelace", "section": "engines", "name": "Ada Lovelace", "years": "1815–1852", "role": "Wrote the first published computer program and saw that computers could work with any symbols", "photo": "people/lovelace.jpg", "w": 501, "h": 720, "credit": "Alfred Edward Chalon, portrait c. 1840. Public domain, via Wikimedia Commons", "story": ["Augusta Ada Byron was the only legitimate child of the poet Lord Byron. Her parents separated when she was a baby, and she never knew her father.", "Her mother, Lady Byron, steered her toward mathematics and science, hoping to keep her away from her father's wild temperament. Ada was often ill: after measles in 1829 she spent nearly a year confined to bed.", "Her imagination ran ahead anyway. At twelve she decided she wanted to fly. She studied the anatomy of birds and planned a book called Flyology to set out her findings.", "Her teachers included two remarkable people. Mary Somerville, one of the best-known scientists in Britain, became a friend and mentor, and introduced her to Charles Babbage. Later, from 1840 to 1842, the logician Augustus De Morgan tutored her in advanced mathematics, mostly by letter.", "She first met Babbage on 5 June 1833, at one of his soirées. Soon after, he showed her a working piece of his Difference Engine, and they became lifelong friends and correspondents.", "In 1840 Babbage gave a talk on the Analytical Engine in Turin. A young Italian engineer, Luigi Menabrea (later Prime Minister of Italy), wrote it up in French. Ada translated his paper and added seven notes, A to G, about three times longer than the article itself. It was published in 1843, signed only 'A.A.L.'", "Note G sets out step by step how the engine could compute Bernoulli numbers, with a table tracking every variable: the first published program. Just as striking, she wrote that the engine might act on things other than numbers, such as musical notes, if their relationships could be expressed as symbols. She also warned that it could not originate anything on its own.", "Her adult life was hard. She married William King, later Earl of Lovelace, had three children, suffered long illnesses, and lost heavily gambling on horses. She died of cancer at 36, the same age as her father, and at her request was buried beside him.", "In 1980 the US Department of Defense named its new programming language Ada after her. Historians still debate exactly how much of the Bernoulli program was hers and how much Babbage's, but the vision in her notes is her own."], "facts": ["Introduced to Babbage through Mary Somerville; met him 5 June 1833", "Tutored by Augustus De Morgan, 1840–1842", "Her seven Notes (1843) were about three times longer than the article they annotated", "Note G contains the first published program"], "sources": [{"title": "MacTutor: Ada Lovelace", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Lovelace/"}, {"title": "Menabrea's 'Sketch of the Analytical Engine' with Ada Lovelace's Notes (full text, 1843)", "url": "https://www.fourmilab.ch/babbage/sketch.html"}, {"title": "Computer History Museum: The Babbage Engine", "url": "https://www.computerhistory.org/babbage/"}, {"title": "Ada Lovelace", "url": "https://en.wikipedia.org/wiki/Ada_Lovelace"}], "uncertain": ["How much of the Note G program was Lovelace's own versus Babbage's remains debated."], "src": "early"}, {"id": "somerville", "section": "engines", "name": "Mary Somerville", "years": "1780–1872", "role": "Self-taught scientist, Lovelace's mentor, and the person the word 'scientist' was coined for", "photo": "people/somerville.jpg", "w": 592, "h": 720, "credit": "Thomas Phillips, portrait of Mary Somerville (Scottish National Portrait Gallery). Public domain, via Wikimedia Commons", "story": ["Mary Fairfax was born in 1780 in Jedburgh, Scotland, and grew up in Burntisland, Fife. Girls of her background were taught manners, music and a little arithmetic, not science.", "Her spark came from an unlikely place. MacTutor relates that she met algebra in a puzzle in a women's magazine belonging to a friend and had no idea what the symbols meant. Her younger brother's tutor quietly got her elementary books on algebra and Euclid's geometry.", "She studied at night. She practised piano early, painted during the day, and stayed up late with Euclid.", "Her first husband, Samuel Greig, had little regard for learned women, and those London years were unhappy. After his death, her inheritance gave her the freedom to study seriously. Her second husband, William Somerville, encouraged her.", "In 1827 Lord Brougham asked her to translate Laplace's great work on celestial mechanics for British readers. She went far beyond translating, explaining the mathematics step by step. The Mechanism of the Heavens (1831) made her famous.", "Her next book, On the Connexion of the Physical Sciences (1834), was so wide-ranging that William Whewell, reviewing it, used a new word for someone who studies the sciences: 'scientist'. Her discussion of a possible unseen planet disturbing Uranus helped prompt John Couch Adams's search, which led toward the discovery of Neptune.", "In 1835 she and Caroline Herschel became the first women elected honorary members of the Royal Astronomical Society. She was also a warm mentor: she befriended the teenage Ada Byron and introduced her to Charles Babbage.", "She spent her last decades in Italy and died in Naples in 1872, aged 91. Somerville College, Oxford, is named after her, and since 2017 her portrait has appeared on the Royal Bank of Scotland £10 note."], "facts": ["The Mechanism of the Heavens (1831) explained Laplace for English readers", "Whewell first used 'scientist' in reviewing her 1834 book", "First female honorary member of the Royal Astronomical Society (1835, with Caroline Herschel)", "Introduced Ada Lovelace to Babbage"], "sources": [{"title": "MacTutor: Mary Somerville", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Somerville/"}, {"title": "Mary Somerville", "url": "https://en.wikipedia.org/wiki/Mary_Somerville"}, {"title": "Somerville College, Oxford: history", "url": "https://www.some.ox.ac.uk/about/history/"}], "uncertain": ["MacTutor and Wikipedia give slightly different accounts of how she first met algebra."], "src": "early"}, {"id": "demorgan", "section": "engines", "name": "Augustus De Morgan", "years": "1806–1871", "role": "Logician who taught Ada Lovelace and gave us De Morgan's laws", "photo": "people/demorgan.jpg", "w": 584, "h": 720, "credit": "Portrait from Sophia Elizabeth De Morgan's memoir of her husband. Public domain, via Wikimedia Commons (File:De_Morgan_Augustus.jpg)", "story": ["Augustus De Morgan was born in 1806 in Madurai, India, where his father was an army officer. Shortly after birth an eye infection left him blind in one eye. The family returned to England when he was seven months old.", "At school he didn't join in sports and was the target of cruel practical jokes. He found his footing in mathematics, and became a fine flute player.", "He went to Trinity College, Cambridge at 16 and finished as Fourth Wrangler in 1827, a top result. But Cambridge then required religious tests for fellowships and higher degrees, and he would not sign them.", "So he went to the new London University (now University College London), which had no religious test, and became its first professor of mathematics. He resigned twice on principle: in 1831 over the dismissal of a colleague (he later returned), and in 1866 when the college refused a philosophy post to a candidate because he was a Unitarian minister.", "His logic contains what we now call De Morgan's laws: 'not (A and B)' equals '(not A) or (not B)', and 'not (A or B)' equals '(not A) and (not B)'. Programmers and chip designers use them every day. He also coined the term 'mathematical induction'.", "He was a generous teacher. From 1840 to 1842 he tutored Ada Lovelace, mostly by letter, and wrote to her mother that Ada might become an original mathematical investigator. He also corresponded with George Boole, whose logic grew alongside his own.", "In 1865 he became the first president of the London Mathematical Society. He married Sophia Frend in 1837, and died in London in 1871."], "facts": ["Fourth Wrangler at Cambridge, 1827, but refused religious tests", "First professor of mathematics at University College London", "De Morgan's laws; coined 'mathematical induction'", "Tutored Ada Lovelace, 1840–1842; first president of the London Mathematical Society"], "sources": [{"title": "MacTutor: Augustus De Morgan", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/De_Morgan/"}, {"title": "Augustus De Morgan", "url": "https://en.wikipedia.org/wiki/Augustus_De_Morgan"}], "uncertain": [], "src": "early"}, {"id": "boole", "section": "engines", "name": "George Boole", "years": "1815–1864", "role": "Shoemaker's son who turned logic into algebra, the math inside every chip", "photo": "people/boole.jpg", "w": 540, "h": 720, "credit": "Portrait, unknown author. Public domain, via Wikimedia Commons (File:George_Boole_color.jpg)", "story": ["George Boole was born in Lincoln, England. His father was a shoemaker who loved science and instrument-making. The family was poor, and George's formal schooling ended early.", "He taught himself languages and then higher mathematics from books. As a teenager he was working as a schoolteacher to support his family, and he went on to run his own school.", "With no university degree, he started publishing research. In 1844 a paper of his on analysis won the Royal Society's Royal Medal.", "In 1847 he published The Mathematical Analysis of Logic, and in 1854 An Investigation of the Laws of Thought. His idea: write statements as symbols and combine them with operations like AND, OR and NOT using algebraic rules. Logic became something you could calculate.", "In 1849, still without a degree, he was appointed the first professor of mathematics at Queen's College, Cork, in Ireland. There, in 1850, he met Mary Everest, niece of the surveyor George Everest. They married in 1855, and Mary later became a noted writer on how children learn mathematics.", "His death came suddenly. In late 1864 he walked to the college through heavy rain and lectured in wet clothes, then fell seriously ill. Biographies report that his wife believed a remedy should resemble its cause and kept him wet in bed, though the details differ between sources. He died on 8 December 1864, aged 49.", "For decades his algebra was a curiosity for logicians. Then in 1937 Claude Shannon showed that it describes exactly how switching circuits behave. Today every chip runs on Boolean logic, and 'boolean' is a basic type in nearly every programming language."], "facts": ["Largely self-taught; Royal Medal of the Royal Society in 1844", "Published The Laws of Thought in 1854", "First mathematics professor at Queen's College, Cork (1849)", "His algebra became circuit design through Shannon in 1937"], "sources": [{"title": "MacTutor: George Boole", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Boole/"}, {"title": "Stanford Encyclopedia of Philosophy: George Boole", "url": "https://plato.stanford.edu/entries/boole/"}, {"title": "George Boole 200 (University College Cork bicentenary site)", "url": "https://georgeboole.com/"}], "uncertain": ["The wife's water 'cure' is reported by MacTutor (buckets of water) and Wikipedia (wet blankets); it may be embellished family lore, so the text keeps it general.", "His walk is given as two miles (MacTutor) or three (Wikipedia)."], "src": "early"}, {"id": "thomas", "section": "engines", "name": "Charles Xavier Thomas de Colmar", "years": "1785–1870", "role": "Built the Arithmometer, the first commercially successful calculator", "photo": "people/thomas.jpg", "w": 556, "h": 720, "credit": "Charles-Xavier Thomas in 1846, after a painting by Lepaule (Bibliothèque nationale de France). Public domain, via Wikimedia Commons", "story": ["Charles Xavier Thomas was born in 1785 in Colmar, in Alsace, the son of a doctor.", "He joined the French army in 1809 and rose to run supplies for the French armies in Spain. Supplying an army meant endless arithmetic, and that is where he got the idea for a calculating machine.", "Back in civilian life he went into fire insurance, founding Le Soleil in 1829 and L'Aigle in 1843, which grew into one of France's leading insurance groups. Insurance, too, runs on calculation.", "He patented his calculator, the Arithmometer, in 1820. It used Leibniz's stepped drum and was built to be sturdy and reliable rather than delicate.", "Then he kept improving it for three decades, filing further patents between 1849 and 1851. Real industrial production began in 1851, the year it was shown at the Great Exhibition in London.", "Insurers, banks, engineers and government offices bought it. Each machine had a serial number and a printed manual. From 1851 to 1890 it was the only kind of mechanical calculator in commercial production, and it was made until 1915.", "Thomas died in 1870. His achievement was not a brand-new idea but a dependable product: he turned the calculator from a curiosity into office equipment and started an industry that lasted until electronic calculators took over in the 1970s."], "facts": ["Patented the Arithmometer in 1820", "Industrial production from 1851; shown at the Great Exhibition", "The only calculator in commercial production, 1851–1890", "Founded the Le Soleil insurance company in 1829"], "sources": [{"title": "Thomas de Colmar", "url": "https://en.wikipedia.org/wiki/Charles_Xavier_Thomas"}, {"title": "Arithmometer", "url": "https://en.wikipedia.org/wiki/Arithmometer"}], "uncertain": ["Thomas's biography rests on Wikipedia only; no museum or book source was verified."], "src": "early"}, {"id": "hollerith", "section": "engines", "name": "Herman Hollerith", "years": "1860–1929", "role": "Built the punched-card tabulator for the 1890 US census and founded the company that became IBM", "photo": "people/hollerith.jpg", "w": 576, "h": 720, "credit": "Charles Milton Bell, portrait (Library of Congress). Public domain, via Wikimedia Commons", "story": ["Herman Hollerith was born in Buffalo, New York, in 1860 to German immigrant parents. He was bright but struggled with spelling, and according to a biography quoted by MacTutor he would run off rather than face a teacher drilling him on it, until he was taken out of school and taught privately.", "He graduated from Columbia's School of Mines in 1879, aged 19, and followed his former professor to work at the US Census Office.", "The census had a data problem. The 1880 count was tabulated by hand, and final tables were not finished until 1887. With the population booming, the 1890 census threatened to be out of date before it was counted.", "The census official John Shaw Billings suggested there ought to be a mechanical way to do the job. Hollerith ran with it. He studied how the Jacquard loom used punched cards, and got another idea watching a train conductor punch tickets to record details about each passenger.", "His system stored each person's data as holes in a card. The card was pressed under a set of pins; where there was a hole, a pin completed an electrical circuit and advanced a counter dial. He patented it in 1889, and the same year submitted a description to Columbia as his doctoral thesis. It beat rival systems in a test for the census.", "For the 1890 census about 60 million cards were punched and run through his machines. IBM's history says the count finished months ahead of schedule and under budget.", "In 1896 he founded the Tabulating Machine Company. Census bureaus around the world, railways and insurance companies used his machines. In 1911 his firm merged with three others into the Computing-Tabulating-Recording Company, which in 1924, under Thomas J. Watson, renamed itself International Business Machines: IBM.", "Hollerith died in Washington, D.C., in 1929. His punched cards carried the world's data for the next half-century."], "facts": ["Columbia School of Mines graduate at 19 (1879)", "Inspired by Billings, the Jacquard loom and railway ticket punches", "About 60 million cards punched for the 1890 census", "His company became part of IBM (named 1924)"], "sources": [{"title": "MacTutor: Herman Hollerith", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Hollerith/"}, {"title": "US Census Bureau: Tabulation and processing history", "url": "https://www.census.gov/about/history/bureau-history/census-innovations/technology/tabulation-and-processing.html"}, {"title": "Computer History Museum: Hollerith's punched card solution", "url": "https://www.computerhistory.org/revolution/punched-cards/2/2"}, {"title": "IBM History: The punched card", "url": "https://www.ibm.com/history/punched-card"}], "uncertain": ["How much faster the 1890 count was varies by source: IBM says months ahead of schedule; Wikipedia says the whole process went from eight years to six."], "src": "early"}, {"id": "ludgate", "section": "engines", "name": "Percy Ludgate", "years": "1883–1922", "role": "Dublin clerk who designed an analytical engine in his spare time", "photo": "people/ludgate.jpg", "w": 280, "h": 277, "credit": "Photograph, unknown author. Public domain (per Wikimedia Commons, File:Percy_Ludgate.jpg); small image, 280 px", "story": ["Percy Ludgate was born in 1883 in Skibbereen, County Cork, Ireland. Census records show him as a teenage copyist in Dublin's civil service in 1901, and as a clerk for a corn merchant in 1911.", "He had no university post, no lab and no team. He studied accountancy in the evenings at Rathmines College of Commerce, winning a gold medal.", "Working alone in his spare time, from about 1903 to 1909, he designed a general-purpose calculating machine. According to Trinity College Dublin's records, he did not know about Babbage's Analytical Engine until later in the process.", "His design was very different from Babbage's. It stored numbers as the positions of rods held in shuttles, and it multiplied using a clever system of index numbers now called Irish logarithms. It was to be controlled by a perforated paper tape.", "He published the design in 1909 in the Scientific Proceedings of the Royal Dublin Society, becoming the second person, after Babbage, to publish a design for an analytical engine. It was never built.", "Almost nothing is known of his personal life; his scientific papers are nearly the only record. He died of pneumonia in October 1922, aged 39, and is buried in Mount Jerome Cemetery, Dublin.", "He was nearly forgotten until the computer scientist Brian Randell brought his work back to light. Trinity College Dublin now awards a Ludgate Prize for the best final-year computer science project."], "facts": ["Designed his engine alone, about 1903–1909", "Published in 1909: the second analytical engine design after Babbage's", "Invented 'Irish logarithms' for multiplication", "Commemorated by Trinity College Dublin's Ludgate Prize"], "sources": [{"title": "Trinity College Dublin, School of Computer Science treasures catalogue: Percy E. Ludgate Prize (with biography)", "url": "https://www.scss.tcd.ie/SCSSTreasuresCatalog/miscellany/TCD-SCSS-X.20121208.002/TCD-SCSS-X.20121208.002.pdf"}, {"title": "Percy Ludgate", "url": "https://en.wikipedia.org/wiki/Percy_Ludgate"}], "uncertain": ["Wikipedia gives his death date as both 16 and 19 October 1922.", "Wikipedia says his 1909 paper helped defeat a Zuse patent claim in 1960; not verified, so left out.", "Exact date of Randell's rediscovery not checked."], "src": "early"}, {"id": "hilbert", "section": "theory", "name": "David Hilbert", "years": "1862–1943", "role": "Asked the question that gave birth to the theory of computation", "photo": "people/hilbert.jpg", "w": 446, "h": 720, "credit": "Postcard photograph (1912), unknown author. Public domain, via Wikimedia Commons (File:David_Hilbert_postcard.png)", "story": ["Hilbert was born in 1862 in Königsberg, Prussia. He studied and taught there before moving in 1895 to Göttingen, which he helped turn into the world's leading centre of mathematics.", "He was surrounded by a circle of brilliant colleagues and students, including Emmy Noether, and loved working through problems in conversation.", "At the International Congress of Mathematicians in Paris in 1900 he presented a list of open problems; the published version had 23. They shaped much of 20th-century mathematics.", "In the 1920s he launched a bold program to put mathematics on unshakeable foundations: axioms that never contradict each other and are strong enough to settle every statement. Part of it was the Entscheidungsproblem, the 'decision problem': is there a mechanical procedure that can decide whether any mathematical statement is provable?", "He was an optimist. In a 1930 address he declared: 'Wir müssen wissen. Wir werden wissen.' (We must know. We will know.) The words are on his gravestone.", "Within a few years the answers came back, and they were no. Gödel showed in 1931 that no such system can be complete and prove its own consistency, and in 1936 Church and Turing showed that no mechanical decision procedure can exist.", "His last years were bleak. The Nazi purges of 1933 drove out colleagues such as Hermann Weyl, Emmy Noether and Edmund Landau. At a banquet, the education minister Bernhard Rust asked whether mathematics in Göttingen had really suffered from the departure of the Jews. Hilbert replied: 'Suffered? It doesn't exist any longer, does it?'", "He died in 1943, in the middle of the war. Fewer than a dozen people attended his funeral. Yet by asking exactly the right question, he set the stage for computer science."], "facts": ["Presented his famous problems in Paris, 1900 (23 in the published list)", "Championed the Entscheidungsproblem", "'We must know. We will know.' (1930), on his gravestone", "Answered negatively by Gödel (1931), Church and Turing (1936)"], "sources": [{"title": "MacTutor: David Hilbert", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Hilbert/"}, {"title": "Stanford Encyclopedia of Philosophy: Hilbert's Program", "url": "https://plato.stanford.edu/entries/hilbert-program/"}, {"title": "Hilbert's 1900 address 'Mathematical Problems', Bulletin of the AMS (1902 translation)", "url": "https://www.ams.org/journals/bull/1902-08-10/S0002-9904-1902-00923-3/"}, {"title": "Stanford Encyclopedia of Philosophy: The Church–Turing Thesis", "url": "https://plato.stanford.edu/entries/church-turing/"}], "uncertain": ["The Rust exchange is a widely reported anecdote, not a recorded transcript.", "The term Entscheidungsproblem was probably coined by Heinrich Behmann (per the Stanford Encyclopedia); Hilbert made it famous."], "src": "early"}, {"id": "godel", "section": "theory", "name": "Kurt Gödel", "years": "1906–1978", "role": "Proved that every consistent system of mathematics leaves some truths unprovable", "photo": "people/godel.jpg", "w": 543, "h": 720, "credit": "Photograph as a student, 1925, unknown author. Public domain, via Wikimedia Commons", "story": ["Gödel was born in 1906 in Brünn (now Brno), in Austria-Hungary. He asked so many questions as a child that his family nicknamed him 'Herr Warum': Mr. Why.", "He studied in Vienna, where a seminar run by the philosopher Moritz Schlick drew him toward logic.", "In 1931, at 25, he published his incompleteness theorems. The key trick was to turn statements about mathematics into numbers, so mathematics could talk about itself. He then built a statement that says, in effect, 'This statement cannot be proved.' If the system is consistent, that statement is true but unprovable.", "It was a direct blow to Hilbert's dream. And his idea of encoding statements as numbers foreshadowed how computers store programs as data.", "Life in Vienna turned dangerous. In 1936 Schlick was murdered by a former student, and Gödel suffered a severe breakdown. In 1940 he and his wife Adele left for America, avoiding the wartime Atlantic by taking the Trans-Siberian Railway, then a ship from Japan to San Francisco, then on to Princeton.", "At the Institute for Advanced Study he became one of Albert Einstein's closest friends. Late in life Einstein said he went to the Institute largely 'to have the privilege of walking home with Gödel'.", "Before his US citizenship exam, Gödel told Einstein and the economist Oskar Morgenstern, his witnesses, that he had found a logical flaw in the Constitution that could allow a dictatorship. They tried to keep him off the subject at the hearing.", "In later life he became convinced he was being poisoned, and ate only food Adele prepared. When she was hospitalised, he stopped eating. He died in Princeton on 14 January 1978, having essentially starved himself."], "facts": ["Incompleteness theorems published 1931, aged 25", "Invented Gödel numbering: statements encoded as numbers", "Reached the US in 1940 via the Trans-Siberian Railway", "Close friend of Einstein at Princeton"], "sources": [{"title": "MacTutor: Kurt Gödel", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Godel/"}, {"title": "Stanford Encyclopedia of Philosophy: Kurt Gödel", "url": "https://plato.stanford.edu/entries/goedel/"}, {"title": "Stanford Encyclopedia of Philosophy: Gödel's Incompleteness Theorems", "url": "https://plato.stanford.edu/entries/goedel-incompleteness/"}], "uncertain": ["What exactly the Constitution flaw was is unknown; the story comes from Morgenstern's recollections."], "src": "early"}, {"id": "church", "section": "theory", "name": "Alonzo Church", "years": "1903–1995", "role": "Invented lambda calculus, proved the decision problem unsolvable, and taught a generation of founders", "photo": null, "w": null, "h": null, "credit": null, "story": ["Alonzo Church was born in Washington, D.C., in 1903. As a boy he was partially blinded in an air gun accident.", "He studied at Princeton and taught there for nearly four decades, from 1929 to 1967. Then he moved to UCLA, where he taught until 1990.", "In the early 1930s he created the lambda calculus: a tiny language built entirely from making functions and applying them. Despite its simplicity, it can express any computation.", "In 1936, using it, he showed that Hilbert's decision problem has no solution, publishing just before Turing reached the same answer another way. His proposal that 'effectively calculable' means exactly what lambda calculus can compute became, together with Turing's version, the Church–Turing thesis.", "When Turing's paper came out, Church reviewed it in 1937 and called Turing's invention a 'Turing machine', the name that stuck. Turing came to Princeton and finished his PhD under Church in 1938.", "Church was an extraordinary teacher. His 31 doctoral students included Alan Turing, Stephen Kleene, J. Barkley Rosser, Michael Rabin, Dana Scott, John Kemeny (co-creator of BASIC) and Raymond Smullyan.", "He was a founding editor of the Journal of Symbolic Logic and edited its reviews section for 43 years, from 1936 to 1979. He died in 1995, aged 92. His lambda calculus lives on in functional languages like Lisp and Haskell, and in the 'lambda' functions of Python and JavaScript."], "facts": ["Created the lambda calculus in the early 1930s", "Proved the Entscheidungsproblem unsolvable in 1936", "Named the 'Turing machine' in his 1937 review; supervised Turing's PhD", "31 doctoral students, including Turing, Kleene, Rabin, Scott and Kemeny"], "sources": [{"title": "MacTutor: Alonzo Church", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Church/"}, {"title": "Stanford Encyclopedia of Philosophy: The Lambda Calculus", "url": "https://plato.stanford.edu/entries/lambda-calculus/"}, {"title": "Stanford Encyclopedia of Philosophy: The Church–Turing Thesis", "url": "https://plato.stanford.edu/entries/church-turing/"}, {"title": "Alonzo Church", "url": "https://en.wikipedia.org/wiki/Alonzo_Church"}], "uncertain": ["The air gun accident is from Wikipedia; details are sparse."], "src": "early"}, {"id": "post", "section": "theory", "name": "Emil Post", "years": "1897–1954", "role": "Logician who independently reached many of Gödel's and Turing's ideas", "photo": "people/post.jpg", "w": 239, "h": 326, "credit": "Photograph, unknown author. Public domain (per Wikimedia Commons, File:Emil_Leon_Post.jpg); small image", "story": ["Emil Post was born in 1897 in Augustów, then in the Russian Empire (now Poland), and moved with his family to New York as a child.", "He dreamed of becoming an astronomer. But at twelve he lost his left arm in an accident, and he turned to mathematics instead.", "He went to a free high school for gifted students on the City College campus, then to City College and Columbia. His doctoral thesis, published in 1921, proved that the basic logic of Russell and Whitehead's Principia Mathematica was complete.", "During a postdoctoral year at Princeton in 1920–21 he came close to discovering incompleteness, a decade before Gödel. He didn't publish, believing he needed a fuller analysis first. Years later he wrote on a postcard to Gödel: 'I would have discovered Gödel's theorem in 1921, if I had been Gödel.'", "His life was shadowed by severe manic-depressive illness, at a time when no drug treatment existed. He worked as a high school teacher, and on his doctor's advice limited research to about three hours a day.", "In 1936, the same year as Turing, he published a model of computation, a 'worker' moving between boxes and marking them, strikingly similar to a Turing machine. He also invented the Post correspondence problem, still a standard example of an unsolvable puzzle in computer science courses.", "He taught at the City College of New York from 1936, carrying a heavy teaching load. In April 1954 he died of a heart attack shortly after electroshock treatment for depression. His ideas underpin much of computability theory and formal languages."], "facts": ["Lost his left arm at twelve and gave up astronomy", "Came close to Gödel's incompleteness result in 1921", "Published a Turing-machine-like model in 1936", "Created the Post correspondence problem"], "sources": [{"title": "MacTutor: Emil Post", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Post/"}, {"title": "Emil Leon Post", "url": "https://en.wikipedia.org/wiki/Emil_Leon_Post"}, {"title": "Stanford Encyclopedia of Philosophy: The Church–Turing Thesis", "url": "https://plato.stanford.edu/entries/church-turing/"}], "uncertain": ["Wikipedia says 'car accident'; MacTutor just says 'accident', so the text says accident.", "The Post correspondence problem is from Wikipedia; its date (1946) is not given in the text."], "src": "early"}, {"id": "bush", "section": "theory", "name": "Vannevar Bush", "years": "1890–1974", "role": "Built the differential analyzer, hired the young Shannon, and imagined the memex", "photo": "people/bush.jpg", "w": 514, "h": 720, "credit": "Harris & Ewing, portrait 1938 (Library of Congress). Public domain, via Wikimedia Commons", "story": ["Vannevar Bush was born in 1890 in Everett, Massachusetts, the son of a Universalist minister. He studied at Tufts College, where students could earn a master's degree alongside their bachelor's.", "He became a professor of electrical engineering at MIT and, in 1922, co-founded the company that became Raytheon.", "From 1928 to 1931 he and his colleague Harold Hazen built the differential analyzer: a room-sized analog computer of shafts, gears and mechanical integrators that solved differential equations. Copies were soon built in Britain and elsewhere.", "In 1936 a 20-year-old graduate student named Claude Shannon was hired as a research assistant to run it. Working on its relay control circuits led Shannon to his famous master's thesis on switching and Boolean logic.", "During the Second World War Bush led the US Office of Scientific Research and Development, coordinating thousands of scientists on radar and other projects, and starting the early administration of the Manhattan Project. He was, in effect, the first presidential science adviser.", "In 1945 his essay 'As We May Think' imagined the memex: a desk that stored a person's books and notes on microfilm and linked them by 'trails'. It inspired later pioneers of hypertext and the web.", "On 5 July 1945 he gave President Truman 'Science, The Endless Frontier', a report arguing for government support of basic research. It led to the creation of the National Science Foundation. He died in 1974."], "facts": ["Built the differential analyzer with Harold Hazen (1928–1931)", "Shannon was hired to run it in 1936", "Led the US wartime Office of Scientific Research and Development", "'As We May Think' (1945) imagined the memex"], "sources": [{"title": "National Science Foundation: Vannevar Bush and 'Science, The Endless Frontier'", "url": "https://www.nsf.gov/about/history/vbush1945.htm"}, {"title": "Vannevar Bush", "url": "https://en.wikipedia.org/wiki/Vannevar_Bush"}, {"title": "Differential analyser", "url": "https://en.wikipedia.org/wiki/Differential_analyser"}], "uncertain": ["How directly Bush supervised Shannon's thesis was not verified, so the text doesn't claim it."], "src": "early"}, {"id": "shannon", "section": "theory", "name": "Claude Shannon", "years": "1916–2001", "role": "Showed logic can be built from switches and founded information theory", "photo": "people/shannon.jpg", "w": 576, "h": 720, "credit": "Photograph, Tekniska museet (Stockholm), unknown author. CC BY 2.0, via Wikimedia Commons (File:C.E._Shannon._Tekniska_museet_43069.jpg)", "story": ["Claude Shannon grew up in the small town of Gaylord, Michigan. As a boy he built model planes, a radio-controlled boat, and a telegraph line to a friend's house half a mile away using barbed-wire fencing. His hero was Thomas Edison, who, he later learned, was a distant cousin.", "He graduated from the University of Michigan in 1936 with two bachelor's degrees, in electrical engineering and mathematics. There he first met the work of George Boole.", "That year he went to MIT to run Vannevar Bush's differential analyzer. Its control circuits were full of relay switches, and Shannon realised Boole's algebra described them perfectly: switches in series act like AND, switches in parallel act like OR. His 1937 master's thesis showed that any logical expression could be built as a circuit and simplified with algebra. It has been called one of the most important master's theses ever written.", "At Bell Labs during the war he worked on cryptography. For about two months in early 1943 Alan Turing was visiting, and the two met at teatime in the cafeteria. Turing showed Shannon his 1936 paper, and Shannon found it fitted closely with his own ideas.", "In 1948 he published 'A Mathematical Theory of Communication'. It treated information as something you can measure, in bits, a word he credited in the paper to his colleague John Tukey. It also proved that every noisy channel has a maximum rate, and that clever coding can get close to it with almost no errors. Every phone, Wi-Fi link and zip file depends on these results.", "He was playful in a way that was also serious. He became known for riding a unicycle through the corridors at Bell Labs and later MIT, sometimes juggling. In 1950 he built, with his wife Betty, Theseus, a mechanical mouse that learned its way through a maze, and he published one of the first papers on programming a computer to play chess.", "He returned to MIT as a professor in the late 1950s, and in 1973 he was the first recipient of the Shannon Award, named in his honour. In his last years he had Alzheimer's disease, and he died in 2001."], "facts": ["1937 master's thesis linked Boolean algebra to switching circuits", "Met Alan Turing at Bell Labs in early 1943", "1948 paper founded information theory; credited Tukey for 'bit'", "Built Theseus, a maze-learning mechanical mouse, in 1950"], "sources": [{"title": "Shannon, 'A Mathematical Theory of Communication' (1948), original paper PDF", "url": "https://people.math.harvard.edu/~ctm/home/text/others/shannon/entropy/entropy.pdf"}, {"title": "MacTutor: Claude Shannon", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Shannon/"}, {"title": "IEEE History Center (ETHW): Oral history of Claude E. Shannon", "url": "https://ethw.org/Oral-History:Claude_E._Shannon"}, {"title": "Quanta Magazine: How Claude Shannon's information theory invented the future", "url": "https://www.quantamagazine.org/how-claude-shannons-information-theory-invented-the-future-20201222/"}, {"title": "Claude Shannon", "url": "https://en.wikipedia.org/wiki/Claude_Shannon"}], "uncertain": ["The Edison family connection (a common ancestor, John Ogden) comes from Wikipedia."], "src": "early"}, {"id": "zuse", "section": "theory", "name": "Konrad Zuse", "years": "1910–1995", "role": "Built the first working programmable computer, the Z3, in Berlin", "photo": "people/zuse.jpg", "w": 354, "h": 472, "credit": "Wolfgang Hunscher, Dortmund, photo 1992. CC BY-SA 3.0, via Wikimedia Commons (File:Konrad_Zuse_(1992).jpg)", "story": ["Konrad Zuse was born in Berlin in 1910. He studied civil engineering and found the endless structural calculations mind-numbing.", "After graduating he worked for the Henschel aircraft company, analysing stresses in aircraft parts: more mountains of calculation. He decided to build a machine to do them.", "He worked independently, without knowing about Babbage or other computing projects. In his parents' Berlin apartment, with help from friends, he built the Z1: a mechanical, binary, floating-point calculator that read instructions from punched film. Its mechanical parts were never quite precise enough to work reliably.", "He moved to telephone relays, and in May 1941 the Z3 was working: the world's first working programmable, fully automatic digital computer. It read programs from punched film and used binary floating-point numbers. Much later it was shown to be capable, in principle, of any computation.", "The German authorities saw little value in it. His workshop, with the Z3, was destroyed in an Allied air raid in late 1943, and the Z1 and his blueprints were lost when his parents' flat was bombed in January 1944.", "Near the end of the war he moved his nearly finished Z4 out of Berlin, first to Göttingen and then to the Bavarian village of Hinterstein. Between 1943 and 1945 he also designed Plankalkül, the first high-level programming language, and used it to sketch a chess program.", "After the war he founded one of the first computer companies. The Z4 went to ETH Zurich, where it ran from 1950 as one of the first commercially available computers. Siemens later took over his company.", "A reconstruction of the Z3 was built in the 1960s and is on display at the Deutsches Museum in Munich. He died in 1995."], "facts": ["Built the Z1 in his parents' apartment in the late 1930s", "Z3 working in May 1941: first working programmable computer", "Designed Plankalkül, the first high-level programming language (1943–45)", "Z4 installed at ETH Zurich in 1950"], "sources": [{"title": "MacTutor: Konrad Zuse", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Zuse/"}, {"title": "Konrad Zuse", "url": "https://en.wikipedia.org/wiki/Konrad_Zuse"}], "uncertain": ["Start date of the Z1 differs: MacTutor quotes Zuse saying he started in 1934; Wikipedia says 1936.", "Removed from earlier draft: his painting and 'computing universe' idea (not cross-checked)."], "src": "early"}, {"id": "rejewski", "section": "codebreakers", "name": "Marian Rejewski", "years": "1905–1980", "role": "Polish mathematician who first broke Enigma", "photo": "people/rejewski.jpg", "w": 482, "h": 608, "credit": "No photographer mentioned in either source, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Marian_Rejewski.jpg", "story": ["In the late 1920s, a young mathematics student in Poznań got an unusual invitation. The Polish Cipher Bureau was quietly running a secret cryptology course for students who spoke German. Marian Rejewski was one of them.", "Poland had a very good reason to care. Its big neighbour, Germany, had started sending military messages on a new machine called Enigma. Every keypress lit up a different letter, and the wiring shifted with every letter typed. To anyone listening on the radio, the messages looked like pure noise.", "On 1 September 1932, Rejewski started full-time work at the Cipher Bureau in Warsaw. Most codebreakers of the day were linguists who looked for patterns in words. Rejewski did something new. He treated the machine as a maths problem, using the algebra of permutations, which is the study of how things get shuffled.", "The Germans had one habit that gave him a way in. Each message began with a short key typed twice. Rejewski realised that those repeats left fingerprints. He wrote them down as equations and, with the help of some German manuals passed on by French intelligence, worked out how the machine's rotors were wired. By the end of 1932 he had rebuilt Enigma on paper without ever seeing one.", "With his colleagues Henryk Zygalski and Jerzy Różycki, he then built tools to find the daily settings. These included a catalogue made with a device called the cyclometer, and later the 'bomba', a machine that tested settings automatically.", "On 24–25 July 1939, five weeks before Germany invaded Poland, the Poles invited British and French codebreakers to a forest near Warsaw and handed over everything: their methods and copies of the machine. That gift gave Bletchley Park a running start.", "When war came, Rejewski escaped through Romania to France, where he kept breaking codes, and later made it to Britain. After the war he went home to Poland and worked quietly as an office clerk. For decades almost nobody knew what he had done. Only in the 1970s did his role become widely known. MacTutor calls his work the application of 'the theory of substitutions' that enabled Enigma to be broken."], "facts": ["Began full-time at the Polish Cipher Bureau on 1 September 1932", "Reconstructed Enigma's rotor wiring mathematically in late 1932", "Shared everything with Britain and France in July 1939", "Spent the post-war years in an ordinary office job in Poland"], "sources": [{"title": "MacTutor: Marian Rejewski", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Rejewski/"}, {"title": "IEEE Milestone: Code-breaking at Bletchley Park, 1939-1945", "url": "https://ethw.org/Milestones:Code-breaking_at_Bletchley_Park_during_World_War_II,_1939-1945"}, {"title": "Wikipedia: Henryk Zygalski (context on the trio)", "url": "https://en.wikipedia.org/wiki/Henryk_Zygalski"}], "uncertain": ["How much the French-supplied German documents mattered versus pure maths is debated by historians", "The Pyry meeting is dated 24–25 July 1939 by MacTutor; some accounts say 25–26 July"], "src": "war-and-machines"}, {"id": "zygalski", "section": "codebreakers", "name": "Henryk Zygalski", "years": "1908–1978", "role": "Polish codebreaker, inventor of the perforated sheets", "photo": "people/zygalski.jpg", "w": 451, "h": 570, "credit": "No photographer mentioned in the source, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Henryk_Zygalski.jpg", "story": ["Henryk Zygalski was born in 1908 in Posen, which was then part of the German Empire and is now Poznań in Poland. Growing up there meant he learned German, and that turned out to matter a great deal.", "As a maths student in Poznań he was invited onto the secret cryptology course that the Polish Cipher Bureau ran for students who spoke German. His classmates included Marian Rejewski and Jerzy Różycki.", "In 1932 the three of them joined the Cipher Bureau in Warsaw. Rejewski worked out the machine's wiring, and then the job became finding each day's settings fast enough for the messages to still be useful.", "Zygalski's big idea came in late 1938, when the Germans changed their procedures and the old Polish shortcuts stopped working. He came up with sheets of card punched with holes, one sheet for each possible starting position of one rotor.", "Here is the trick in plain words. Certain repeated letter patterns, nicknamed 'females', only show up at certain machine settings. Each hole marked a setting where a female could happen. Stack the right sheets on a light table, slide them around, and wherever light shone through every layer, you had a candidate setting.", "It was slow, careful handwork. The number of sheet sets needed grows quickly with the number of rotors to choose from. When the Germans added two extra rotors in December 1938, the Poles did not have the staff to cut them all. Bletchley Park later made full sets, and the British called them Zygalski sheets.", "Like Rejewski, Zygalski escaped when Poland fell in 1939 and kept breaking codes in France, and later in Britain.", "Unlike Rejewski, he stayed in Britain after the war. He taught mathematics at the Polish University College in London and then at Battersea Polytechnic, which later became the University of Surrey. He died in Liss, Hampshire, in 1978."], "facts": ["Invented perforated 'Zygalski sheets' in late 1938", "Bletchley Park manufactured full sets in 1939–40", "Stayed in Britain after the war and taught maths"], "sources": [{"title": "MacTutor: Henryk Zygalski", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Zygalski/"}, {"title": "Wikipedia: Henryk Zygalski", "url": "https://en.wikipedia.org/wiki/Henryk_Zygalski"}, {"title": "IEEE Milestone: Code-breaking at Bletchley Park, 1939-1945", "url": "https://ethw.org/Milestones:Code-breaking_at_Bletchley_Park_during_World_War_II,_1939-1945"}], "uncertain": ["Accounts differ on exactly when the full British-made sets were first used successfully"], "src": "war-and-machines"}, {"id": "rozycki", "section": "codebreakers", "name": "Jerzy Różycki", "years": "1909–1942", "role": "Polish codebreaker, inventor of the 'clock' method", "photo": "people/rozycki.jpg", "w": 538, "h": 720, "credit": "No photographer mentioned in either source, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Jerzy_Rozycki.jpg", "story": ["Jerzy Różycki was born in 1909 in Olszana, then in the Russian Empire and today Vilshana in Ukraine. He spent his early years there before his family moved to Poland.", "He loved both mathematics and modern languages and wanted to study both. At Poznań University he was picked for the Cipher Bureau's secret course for German-speaking maths students.", "He was the youngest of the three who joined the Cipher Bureau in 1932, alongside Rejewski and Zygalski.", "His best-known invention was the 'clock' method. It rested on a sharp observation about letter statistics in German text, and it let the team guess which rotor sat in the first position of the machine. That cut the amount of work needed to find each day's settings.", "When Poland fell in 1939, he escaped with his colleagues to France. In 1940, as France collapsed, the team was moved to Algeria, first to Oran and then to Algiers.", "After a few months he went back to work at a secret codebreaking centre code-named 'Cadix', in a château near Uzès in the south of France. It ran from October 1940 to November 1942, hidden from the Vichy authorities.", "In January 1942 he boarded the passenger ship SS Lamoricière in Algiers, heading for Marseille. A violent storm struck near the Balearic Islands. The ship ran out of coal, took on water and sank. Różycki was among those lost. He was 32.", "He left a wife and a young son. Today a commemorative plaque in Warsaw honours him, and the Polish trio are celebrated together at the Enigma Cipher Centre in Poznań."], "facts": ["Invented the 'clock' method for finding the fast rotor", "Died when SS Lamoricière sank in January 1942"], "sources": [{"title": "MacTutor: Jerzy Różycki", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Rozycki/"}, {"title": "Wikipedia: Jerzy Różycki", "url": "https://en.wikipedia.org/wiki/Jerzy_R%C3%B3%C5%BCycki"}], "uncertain": ["Whether the Lamoricière sinking was pure accident is occasionally questioned, but no evidence of sabotage is accepted"], "src": "war-and-machines"}, {"id": "welchman", "section": "codebreakers", "name": "Gordon Welchman", "years": "1906–1985", "role": "Head of Hut 6; improved the Bombe; built Bletchley's production line", "photo": "people/welchman.jpg", "w": 720, "h": 540, "credit": "William Warby from London, England, CC BY 2.0, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Gordon_Welchman%27s_Desk_(21589984765).jpg", "story": ["Gordon Welchman was born in 1906 near Bristol, the youngest child of a vicar who later became Archdeacon of Bristol. He won scholarships to Marlborough College and then to Trinity College, Cambridge, where he took first-class honours in mathematics.", "By the late 1930s he was a fellow and dean of Sidney Sussex College and an algebraic geometer, writing a textbook on the subject. War interrupted it. The book finally came out in 1950, more than ten years late.", "Alastair Denniston, head of Britain's Government Code and Cypher School, realised the next war would need mathematicians, not just linguists. He wrote to lecturers at Oxford and Cambridge, and Welchman was one of the first to say yes.", "At Bletchley, Dilly Knox gave him what looked like a dull job: studying call signs and the outsides of messages. Welchman realised he was looking at an entire German communication network. Working out who talked to whom, when and how, even without reading the words, became known as traffic analysis. MacTutor calls it his greatest contribution.", "He proposed organising Bletchley into specialised huts and was put in charge of Hut 6, which broke German Army and Air Force Enigma. He treated it as a production line: intercept, sort, decode, then hand the results on for translation and intelligence. He also recruited many fellow mathematicians, including his former student Joan Clarke.", "His most famous technical idea was the 'diagonal board'. Enigma's plugboard swapped letters in pairs, so if A became B, then B became A. Welchman added wiring to Turing's Bombe design that used this symmetry to rule out far more wrong settings at once. Bombes became much faster and could work from shorter cribs.", "In October 1941 he was one of the four, with Turing, Hugh Alexander and Stuart Milner-Barry, who wrote directly to Churchill asking for more staff. Churchill answered: 'Action this day.' Welchman was made an OBE in 1946.", "After the war he became director of research for the John Lewis Partnership. In 1948 he moved to the United States, where he taught an early computing course at MIT, worked for Remington Rand and Ferranti, and later spent years at the MITRE Corporation designing battlefield communication systems. He became a US citizen in 1962.", "In 1982 he published 'The Hut Six Story', the first book to explain in detail how Bletchley actually broke Enigma. The security services were furious, and his security clearance was withdrawn. He died in Massachusetts in 1985."], "facts": ["Proposed Bletchley's hut structure and ran Hut 6", "Pioneered traffic analysis", "Invented the Bombe's diagonal board", "Co-signed the October 1941 letter to Churchill; OBE 1946", "Published 'The Hut Six Story' (1982)"], "sources": [{"title": "MacTutor: Gordon Welchman", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Welchman/"}, {"title": "Wikipedia: Gordon Welchman", "url": "https://en.wikipedia.org/wiki/Gordon_Welchman"}, {"title": "The National Museum of Computing: The Turing-Welchman Bombe", "url": "https://www.tnmoc.org/bombe"}], "uncertain": ["Photo shows Welchman's desk at Bletchley Park (CC BY 2.0), not Welchman himself", "The withdrawal of his clearance is widely reported, but I didn't check it against an official document"], "src": "war-and-machines"}, {"id": "clarke", "section": "codebreakers", "name": "Joan Clarke", "years": "1917–1996", "role": "Cryptanalyst in Hut 8, later deputy head", "photo": "people/clarke.jpg", "w": 540, "h": 720, "credit": "Spudgun67, CC BY-SA 4.0, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:JOAN_CLARKE_1917%E2%80%931996_Code-breaker_lived_here.jpg", "story": ["Joan Clarke was born in London in 1917. She won a scholarship to Newnham College, Cambridge, and achieved a double first in mathematics. Cambridge did not give women full degrees at the time, so she was awarded only the title of one.", "In 1940 Gordon Welchman, who had supervised her in geometry, recruited her to Bletchley Park. She was first placed with the women doing routine clerical work, often called 'the girls'. Her talent was soon spotted, and she was moved into Hut 8 with Alan Turing to work on German naval Enigma.", "Hut 8 used a statistical method Turing had invented called Banburismus. The name came from the long printed sheets made in the town of Banbury. Codebreakers compared messages on these sheets to work out which rotors were in the machine, saving huge amounts of Bombe time.", "Clarke became one of its best practitioners. Her colleague Jack Good later recalled that there were eight male Banburists and she was the only woman.", "She was promoted, but the civil service had no grade for a woman doing her job. She was listed as a 'linguist' and enjoyed filling in forms with 'Grade: Linguist. Languages: none.' She believed her sex held back further promotion.", "She and Turing grew close and were briefly engaged in 1941. Turing told her he was gay. She was not put off and the engagement continued, but he later ended it. They stayed friends.", "Later in the war, many Hut 8 staff moved to other work, but Clarke stayed and became deputy head of Hut 8. She was appointed MBE for her wartime service.", "After the war she continued in codebreaking at GCHQ. She married Jock Murray in 1952 and, through him, became fascinated by Scottish coins. As a numismatist she worked out the sequence of gold unicorns and heavy groats struck under James III and James IV.", "She died in Oxfordshire in 1996. The 2014 film 'The Imitation Game' made her name famous, and a blue plaque now marks her former home in Dulwich."], "facts": ["Double first in maths at Cambridge", "Expert in Banburismus in Hut 8", "Briefly engaged to Alan Turing in 1941", "Later an authority on Scottish coinage"], "sources": [{"title": "MacTutor: Joan Clarke", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Clarke_Joan/"}, {"title": "Wikipedia: Joan Clarke", "url": "https://en.wikipedia.org/wiki/Joan_Clarke"}, {"title": "Bletchley Park Roll of Honour", "url": "https://bletchleypark.org.uk/roll-of-honour/"}], "uncertain": ["MBE year given as 1946 in some sources and 1947 in others", "Photo is her blue plaque in Dulwich (CC BY-SA 4.0), not a portrait"], "src": "war-and-machines"}, {"id": "flowers", "section": "codebreakers", "name": "Tommy Flowers", "years": "1905–1998", "role": "Post Office engineer who built Colossus", "photo": "people/flowers.jpg", "w": 300, "h": 407, "credit": "Unknown, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Tommy_Flowers.jpg", "story": ["Tommy Flowers was born in 1905 in Poplar, in London's East End. His father was a bricklayer. Flowers took an engineering apprenticeship, studied at evening classes for a degree, and joined the Post Office, which ran Britain's telephone network.", "At the Post Office research station at Dollis Hill he became an expert in using vacuum tubes, called 'valves' in Britain, as fast electronic switches in telephone exchanges. Most engineers thought valves were too unreliable for big systems. Flowers knew they lasted well if you never switched them off.", "In 1943 he was asked to help with the Lorenz cipher used by Hitler's high command. Bletchley's existing machine for it, the 'Heath Robinson', had to keep two paper tapes running in step, and they kept stretching and snapping.", "Flowers proposed a bolder design that generated one of the tapes electronically inside the machine. That meant well over a thousand valves. Bletchley's managers doubted it would work, so Flowers pressed on at Dollis Hill with his own team.", "The first Colossus, with about 1,500 valves, ran at Dollis Hill in November 1943 and was delivered to Bletchley Park in January 1944. The staff named it Colossus because of its size. It was about five times faster than Heath Robinson.", "An improved Mark 2, with about 2,400 valves, went into service on 1 June 1944, days before D-Day. It helped confirm that the Germans had fallen for the Allied deceptions about where the landings would come.", "By the end of the war there were ten Colossi. According to The National Museum of Computing, 63 million characters of top-level German messages were decrypted with their help. Afterwards most of the machines were destroyed on orders, and the work was locked under the Official Secrets Act.", "Flowers had put his own money into the project. The government's £1,000 award did not cover it, and he shared much of it with his team. When he later asked the Bank of England for a loan to build a similar machine, he was turned down, and he could not explain why he knew it would work.", "Only from the mid-1970s did the secret start to come out. In 1983 he received the first Martlesham Medal. A working rebuild of Colossus now runs at The National Museum of Computing at Bletchley. He died in 1998."], "facts": ["Colossus Mark 1: about 1,500 valves, working November 1943, at Bletchley January 1944", "Mark 2: about 2,400 valves, in service 1 June 1944", "Ten Colossi by 1945", "Refused a Bank of England loan after the war"], "sources": [{"title": "The National Museum of Computing: Colossus", "url": "https://www.tnmoc.org/colossus"}, {"title": "Wikipedia: Tommy Flowers", "url": "https://en.wikipedia.org/wiki/Tommy_Flowers"}, {"title": "IEEE Milestone: Code-breaking at Bletchley Park, 1939-1945", "url": "https://ethw.org/Milestones:Code-breaking_at_Bletchley_Park_during_World_War_II,_1939-1945"}], "uncertain": ["Valve counts differ: about 1,500 or 1,600 (Mark 1) and about 2,400 (Mark 2); TNMOC's page gives a rounded 2,500", "How much of his own money he spent is not documented", "Photo is a 300 px public-domain image (low resolution)"], "src": "war-and-machines"}, {"id": "tutte", "section": "codebreakers", "name": "Bill Tutte", "years": "1917–2002", "role": "Mathematician who worked out the Lorenz machine without seeing it", "photo": "people/tutte.jpg", "w": 720, "h": 540, "credit": "Matt Brown, CC BY 2.0, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Bill_Tutte_memorial,_Newmarket.jpg", "story": ["Bill Tutte was born in 1917 in Newmarket, Suffolk, the home of English horse racing. His father was an estate gardener and his mother a cook and housekeeper.", "He won a scholarship to Trinity College, Cambridge, where he studied chemistry. He was drawn into a group of young mathematicians puzzling over recreational problems, and he published maths research while still training as a chemist.", "In 1941 he was recruited to Bletchley Park. He was put to work on teleprinter traffic that Bletchley nicknamed 'Fish', especially a link called 'Tunny'. It was enciphered on a Lorenz machine that nobody in Britain had ever seen.", "There was one clue. In August 1941 a German operator sent a long message twice with small changes, a serious mistake. From those two near-copies, the veteran codebreaker John Tiltman worked out a long stretch of the secret key.", "Tutte was given that key. He wrote it out in rows of different lengths, looking for repeats. From the patterns, step by step, he worked out how many wheels the machine had, how big each was, and how they moved.", "By early 1942 the whole logic of the Lorenz machine had been reconstructed on paper. Many historians call it one of the great intellectual feats of the war.", "Tutte then devised a statistical method for finding the wheel settings of each message. Doing it by hand was far too slow, and that is why Max Newman's section built machines to do the counting, first Heath Robinson and then Tommy Flowers's Colossus.", "After the war he finished a PhD at Cambridge and in 1948 accepted an invitation to the University of Toronto. He later moved to the University of Waterloo, where he became one of the founders of modern graph theory, the mathematics of networks.", "For decades his war work stayed secret. He died in Waterloo in 2002. A memorial in his hometown of Newmarket now tells his story."], "facts": ["Deduced the Lorenz cipher's structure from key alone in 1942", "His statistical method was the task Colossus was built for", "Later a leading graph theorist at Waterloo"], "sources": [{"title": "MacTutor: William Tutte", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Tutte/"}, {"title": "Wikipedia: W. T. Tutte", "url": "https://en.wikipedia.org/wiki/W._T._Tutte"}, {"title": "The National Museum of Computing: Colossus", "url": "https://www.tnmoc.org/colossus"}], "uncertain": ["Photo is the Bill Tutte memorial in Newmarket (CC BY 2.0), not a portrait"], "src": "war-and-machines"}, {"id": "newman", "section": "codebreakers", "name": "Max Newman", "years": "1897–1984", "role": "Mathematician who led the Newmanry, home of Colossus", "photo": null, "w": null, "h": null, "credit": null, "story": ["Max Newman was born in London in 1897 as Max Neumann. His father was German. During the First World War, in 1916, he changed his name to Newman.", "He studied at St John's College, Cambridge, and became an expert in topology, the mathematics of shapes that can be stretched but not torn. A series of his papers between 1926 and 1932 reshaped the subject.", "At Cambridge he taught a course on the foundations of mathematics. One student was Alan Turing. MacTutor says these lectures introduced Turing to the idea of 'decidability', which inspired his 1936 paper 'On Computable Numbers', and that Newman helped get it published.", "In 1942 Newman joined Bletchley Park. Building on the work of John Tiltman and Bill Tutte, he saw that breaking the Lorenz cipher needed machines, and he was put in charge of a section to build and run them. It was called the 'Newmanry'.", "The Newmanry first used the Heath Robinson and then Tommy Flowers's Colossus machines. MacTutor says the work convinced him that general-purpose electronic computers could and should be built.", "After the war he became Fielden Professor of Mathematics at Manchester and set up the Royal Society Computing Machine Laboratory there. In 1948 Manchester produced the 'Baby', the world's first working stored-program electronic computer. Newman brought Turing to Manchester the same year.", "He received the Royal Society's Sylvester Medal in 1958 and the London Mathematical Society's De Morgan Medal in 1962. He died near Cambridge in 1984."], "facts": ["Taught the course that inspired Turing's 1936 paper", "Ran the Newmanry, home of Colossus", "Founded the Manchester computing lab"], "sources": [{"title": "MacTutor: Max Newman", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Newman/"}, {"title": "Wikipedia: Max Newman", "url": "https://en.wikipedia.org/wiki/Max_Newman"}, {"title": "The National Museum of Computing: Colossus", "url": "https://www.tnmoc.org/colossus"}], "uncertain": ["The only photo found on Commons is under the Open Government Licence, so I left it out", "The Baby was built by F. C. Williams and Tom Kilburn; how much credit Newman's lab should get is debated"], "src": "war-and-machines"}, {"id": "bletchley-women", "section": "codebreakers", "name": "The women of Bletchley Park (overview)", "years": "1939–1945", "role": "Thousands of women who ran the codebreaking machine", "photo": null, "w": null, "h": null, "credit": null, "story": ["By 1945, according to Bletchley Park itself, three in every four people working there were women. About six in ten of them were in uniform.", "Many came from the women's services: the WRNS (the 'Wrens'), the ATS and the WAAF. Others were civilians, recruited for languages, maths, or just because they were good at crosswords and puzzles.", "Wrens ran the Bombes, hundreds of noisy machines in outstations around Bletchley. They worked in shifts around the clock, setting up drums and wiring from the menus the codebreakers drew up.", "Wrens also ran Colossus. They changed plugs and switches, loaded paper tape that raced through at 5,000 characters a second, and read off results.", "Others did the less glamorous but vital jobs: indexing every name and unit mentioned in decrypts, translating, and typing up intelligence for the front line. That index was how scraps of messages became useful knowledge.", "Almost all of them signed the Official Secrets Act and kept quiet for 30 years or more. Some never told their own husbands. Today Bletchley Park's Roll of Honour lists them by name.", "The cards that follow tell a few of their stories: Mavis Batey and Margaret Rock in Dilly Knox's team, and Jane Fawcett in Hut 6. Joan Clarke has her own card above."], "facts": ["By 1945, about 75% of Bletchley staff were women", "Wrens operated the Bombes and Colossus", "Most kept their work secret until the 1970s or later"], "sources": [{"title": "Bletchley Park: Who were the Codebreakers?", "url": "https://bletchleypark.org.uk/our-story/who-were-the-codebreakers/"}, {"title": "Bletchley Park Roll of Honour", "url": "https://bletchleypark.org.uk/roll-of-honour/"}, {"title": "Wikipedia: Women in Bletchley Park", "url": "https://en.wikipedia.org/wiki/Women_in_Bletchley_Park"}, {"title": "The National Museum of Computing: Colossus", "url": "https://www.tnmoc.org/colossus"}, {"title": "IEEE Milestone: Code-breaking at Bletchley Park, 1939-1945", "url": "https://ethw.org/Milestones:Code-breaking_at_Bletchley_Park_during_World_War_II,_1939-1945"}], "uncertain": ["Total staff: IEEE's Bletchley milestone plaque says 12,000 men and women worked there during the war; other figures vary", "Ruth Briggs not added: the only source I could reach is about a different Ruth Briggs (a US Women's Army Corps officer)"], "src": "war-and-machines"}, {"id": "batey", "section": "codebreakers", "name": "Mavis Batey (née Lever)", "years": "1921–2013", "role": "Codebreaker in Dilly Knox's section; broke Italian and Abwehr Enigma", "photo": null, "w": null, "h": null, "credit": null, "story": ["Mavis Lever was born in Dulwich, London, in 1921. Her mother was a seamstress and her father a postal worker. When war broke out she was studying German at University College London, reading the German Romantic poets.", "She later joked that she realised the German Romantics would soon be flying overhead, so she ought to do something more useful. She first applied to be a nurse, but her German was in demand. Her first wartime job was checking the personal ads in The Times for coded spy messages.", "In 1940, aged 19, she was sent to Bletchley Park to work for Dilly Knox, a brilliant and eccentric classical scholar whose research section was known for hiring young women. His opening words to her were: 'Hello, we're breaking machines. Have you got a pencil?'", "Knox's team attacked the Italian Navy's Enigma, a version with no plugboard, using a hand method called 'rodding'. One day she noticed a message that contained every letter except L. Enigma never turns a letter into itself, so she guessed a lazy operator had just tapped L over and over to send a dummy message. That guess helped crack a newly introduced rotor.", "In March 1941 she and her colleagues, including Margaret Rock, worked for three days and nights on messages that revealed an Italian plan to attack a British supply convoy. Admiral Andrew Cunningham used the warning to surprise the Italian fleet at the Battle of Cape Matapan, sinking three cruisers and two destroyers. He later visited to thank the team. Knox wrote a poem: 'When Cunningham won at Matapan / By the grace of God and Mavis'.", "Next she worked on the Enigma of the Abwehr, German military intelligence. In December 1941 she broke a message between Belgrade and Berlin that let the team work out that machine's wiring. Reading Abwehr traffic let Britain check that the Germans believed the false information fed to them by double agents, a vital part of the D-Day deception.", "In 1942 she married Keith Batey, a Hut 6 mathematician she had gone to for help. After the war she brought up three children and became a leading garden historian. She campaigned to save historic parks and was made MBE in 1987 for that work, not for codebreaking.", "She also wrote a biography of her old boss, 'Dilly: The Man Who Broke Enigmas'. The Guardian's obituary called her one of the leading codebreakers 'of either sex'. She died in 2013, aged 92."], "facts": ["Broke into Italian naval Enigma before Matapan (March 1941)", "Broke an Abwehr Enigma message in December 1941", "Later a garden historian; MBE 1987 for conservation"], "sources": [{"title": "Wikipedia: Mavis Batey", "url": "https://en.wikipedia.org/wiki/Mavis_Batey"}, {"title": "The Guardian: Mavis Batey obituary (Michael Smith, 2013)", "url": "https://www.theguardian.com/world/2013/nov/20/mavis-batey"}, {"title": "Bletchley Park Roll of Honour", "url": "https://bletchleypark.org.uk/roll-of-honour/"}], "uncertain": ["No PD/CC-licensed photo found", "The Guardian says three heavy cruisers and two destroyers and about 3,000 Italian sailors lost; figures vary"], "src": "war-and-machines"}, {"id": "rock", "section": "codebreakers", "name": "Margaret Rock", "years": "1903–1983", "role": "Mathematician and senior Enigma cryptanalyst in Knox's section", "photo": null, "w": null, "h": null, "credit": null, "story": ["Margaret Rock was born in 1903 in Hammersmith, London. Her father served as a naval surgeon and died when the armed merchant cruiser HMS Laurentic struck German mines off Ireland during the First World War. Letters he had written urging her to keep up her studies stayed with her.", "She studied at Bedford College, University of London, and then worked as a statistician for the Federation of British Industry, forecasting how businesses would respond to the market.", "She joined Bletchley Park on 15 April 1940, aged 36, and was posted to Dilly Knox's research section alongside the much younger Mavis Lever.", "Knox thought highly of her. In August 1940 he rated her as the fourth or fifth best person on the whole Enigma staff, and she rose to be one of the section's senior cryptographers.", "She worked on the Italian naval messages behind the Battle of Matapan, and then on the Abwehr's Enigma. On 8 December 1941 Knox's team read an Abwehr Enigma message using his rodding method, a breakthrough that later fed into the D-Day deception work.", "She also worked on German and Russian systems. After the war she stayed in government work, including at GCHQ, until she retired in 1963.", "Bound by the Official Secrets Act, she never talked about her work, even when Bletchley stories began to fill the newspapers. She died in Worcester in 1983."], "facts": ["Joined Bletchley Park 15 April 1940", "Rated by Knox among the top five on the Enigma staff", "In government service until 1963"], "sources": [{"title": "Wikipedia: Margaret Rock", "url": "https://en.wikipedia.org/wiki/Margaret_Rock"}, {"title": "Wikipedia: Mavis Batey (Matapan and Abwehr work)", "url": "https://en.wikipedia.org/wiki/Mavis_Batey"}, {"title": "Bletchley Park Roll of Honour", "url": "https://bletchleypark.org.uk/roll-of-honour/"}], "uncertain": ["No PD/CC photo found", "Wikipedia says her father died when HMS Laurentic sank (January 1917) and also says the family moved to Portsmouth in 1917; the details are thinly sourced"], "src": "war-and-machines"}, {"id": "fawcett", "section": "codebreakers", "name": "Jane Fawcett (née Hughes)", "years": "1921–2016", "role": "Hut 6 decoder who helped find the Bismarck", "photo": null, "w": null, "h": null, "credit": null, "story": ["Janet 'Jane' Hughes was born on 4 March 1921. Her father was clerk of the Goldsmiths' Company in London.", "In 1940 she was recruited to Bletchley Park through Stuart Milner-Barry, one of its senior codebreakers. She was one of the young women from well-off families that the writer Michael Smith later called the 'Debs of Bletchley Park'.", "She worked in Hut 6's Decoding Room, a women-only room that was dim, cold and badly ventilated, with long hours under heavy pressure. Once the day's Enigma key was found, women like her set it on British Typex machines, typed in the intercepted messages and checked whether real German came out.", "On 25 May 1941 she and several others were briefed to watch for the German battleship Bismarck, which had slipped away from its British pursuers.", "Soon afterwards she decoded a message giving the Bismarck's position and its destination in France. The Royal Navy closed in, and the Bismarck was sunk on 27 May. It was the codebreakers' first big, visible victory.", "After the war she sang professionally and later became a heritage campaigner, serving as secretary of the Victorian Society from 1963 to 1976 and writing books such as 'The Future of the Past'. She was made MBE.", "She stayed silent for about 50 years. When she finally spoke in the 1990s she said: 'I'd never told a soul, not even my husband. My grandchildren were very surprised.' She died in Oxford in 2016."], "facts": ["Decoded a key Bismarck message in May 1941", "Secretary of the Victorian Society 1963–76"], "sources": [{"title": "Wikipedia: Jane Fawcett", "url": "https://en.wikipedia.org/wiki/Jane_Fawcett"}, {"title": "Bletchley Park: Who were the Codebreakers?", "url": "https://bletchleypark.org.uk/our-story/who-were-the-codebreakers/"}], "uncertain": ["No PD/CC photo found", "Exact wording of the Bismarck message varies in retellings"], "src": "war-and-machines"}, {"id": "mauchly", "section": "electronic", "name": "John Mauchly", "years": "1907–1980", "role": "Physicist who co-designed ENIAC and UNIVAC", "photo": "people/mauchly.jpg", "w": 355, "h": 473, "credit": "Unknown author, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:John_Mauchly.jpg", "story": ["John Mauchly was born in 1907 in Cincinnati, Ohio. He studied physics at Johns Hopkins University and earned a PhD there.", "By 1940 he was teaching physics at Ursinus College near Philadelphia. He was fascinated by weather and wanted to find patterns in huge piles of weather data. Desk calculators were far too slow, so he began looking for machine help.", "In December 1940 he met John Atanasoff at a science meeting in Philadelphia. In June 1941 he visited Atanasoff in Iowa and studied his electronic computing machine. That visit later became the centre of a famous court fight.", "In 1941 he took a wartime electronics course at the University of Pennsylvania's Moore School and then stayed on to teach. There he met a brilliant young engineer, J. Presper Eckert.", "In 1942 Mauchly wrote a short memo proposing an electronic calculator built from vacuum tubes. Herman Goldstine, the Army's liaison at the Moore School, saw what it could do. In April 1943 the Army approved funding for the project that became ENIAC.", "Mauchly was the big-picture thinker and Eckert the engineering genius. ENIAC was unveiled in February 1946.", "In 1946 Mauchly and Eckert left Penn and founded one of the first computer companies. They built BINAC and then UNIVAC, the first commercial computer produced in the United States.", "In 1948 he married Kathleen McNulty, one of ENIAC's first programmers. He was a widower with two children.", "In 1973 a US judge ruled the ENIAC patent invalid, finding that its subject matter was 'derived' from Atanasoff's machine. Mauchly insisted his ideas came from earlier work with electronic counters. Historians still debate the question. He died in 1980."], "facts": ["1942 memo proposed an electronic computer", "Co-founded the Eckert–Mauchly Computer Corporation", "ENIAC patent invalidated in 1973 (Honeywell v. Sperry Rand)"], "sources": [{"title": "MacTutor: John Mauchly", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Mauchly/"}, {"title": "Wikipedia: John Mauchly", "url": "https://en.wikipedia.org/wiki/John_Mauchly"}, {"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}, {"title": "IEEE Milestone: ENIAC, 1946", "url": "https://ethw.org/Milestones:Electronic_Numerical_Integrator_and_Computer,_1946"}, {"title": "Wikipedia: Atanasoff–Berry computer", "url": "https://en.wikipedia.org/wiki/Atanasoff%E2%80%93Berry_computer"}, {"title": "MacTutor: Herman Goldstine", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Goldstine/"}, {"title": "MacTutor: Kathleen McNulty Antonelli", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Antonelli/"}], "uncertain": ["Degree of influence from the 1941 Atanasoff visit is disputed"], "src": "war-and-machines"}, {"id": "eckert", "section": "electronic", "name": "J. Presper Eckert", "years": "1919–1995", "role": "Chief engineer of ENIAC, co-founder of UNIVAC", "photo": "people/eckert.jpg", "w": 506, "h": 720, "credit": "Unknown, dedicated to Bettmann Archive, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Computer_Engineer_J._Presper_Eckert.png", "story": ["J. Presper Eckert was born in Philadelphia in 1919 into a wealthy family. His father was a property developer. As a boy he was a gifted tinkerer.", "He studied electrical engineering at Penn's Moore School and stayed on as a graduate student and researcher. There, in 1941, he met John Mauchly.", "When the Army funded ENIAC in 1943, Eckert, at 24, became its chief engineer.", "His great achievement was making 17,468 vacuum tubes work together. Critics said a machine with so many tubes would never run long enough to finish a problem. Eckert ran them well below their rated power and tested parts carefully.", "Kay McNulty later remembered that at first some tubes failed and bad solder joints had to be fixed, but once those were ironed out, 'the machine was really quite reliable and it operated very well'.", "ENIAC was unveiled on 15 February 1946. It filled a large room, weighed about 30 tons and could do 5,000 additions a second.", "Eckert also invented the mercury delay-line memory, in which data travels as pulses of sound through a tube of mercury. It made storing programs in memory practical, and it went into UNIVAC.", "With Mauchly he founded the company that built BINAC and UNIVAC. When Remington Rand bought it in 1950, Eckert stayed on as an executive for the rest of his career. He died in 1995."], "facts": ["ENIAC chief engineer at 24", "Pioneered mercury delay-line memory", "UNIVAC: first commercial US computer, 1951"], "sources": [{"title": "MacTutor: J Presper Eckert", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Eckert_John/"}, {"title": "ETHW: J. Presper Eckert", "url": "https://ethw.org/J._Presper_Eckert"}, {"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}, {"title": "IEEE Milestone: ENIAC, 1946", "url": "https://ethw.org/Milestones:Electronic_Numerical_Integrator_and_Computer,_1946"}, {"title": "Wikipedia: J. Presper Eckert", "url": "https://en.wikipedia.org/wiki/J._Presper_Eckert"}, {"title": "MacTutor: Kathleen McNulty Antonelli (reliability quote)", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Antonelli/"}, {"title": "Wikipedia: Marlyn Meltzer (ENIAC specifications)", "url": "https://en.wikipedia.org/wiki/Marlyn_Meltzer"}], "uncertain": ["Who first proposed the stored-program idea (Eckert, Mauchly or von Neumann) is still disputed"], "src": "war-and-machines"}, {"id": "goldstine", "section": "electronic", "name": "Herman Goldstine", "years": "1913–2004", "role": "Army mathematician who championed ENIAC", "photo": "people/goldstine.jpg", "w": 345, "h": 439, "credit": "U.S. Army photo, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Capt._Herman_H._Goldstine_(cropped).jpg", "story": ["Herman Goldstine grew up in Chicago, where his father was a lawyer. He studied mathematics at the University of Chicago and earned a doctorate there in 1936 on the calculus of variations.", "In 1939 he moved to the University of Michigan as an instructor. In 1941 he married Adele Katz.", "In July 1942 he joined the Army. He received two sets of orders at once, one for the Far East and one for the Ballistic Research Laboratory in Aberdeen, Maryland. His commanding officer asked which he preferred and told him to drive to Aberdeen as fast as he could.", "His job was liaising with the Moore School in Philadelphia, where the Army's firing tables were calculated. When Mauchly wrote his 1942 report on a better computer, Goldstine saw its potential at once.", "In April 1943 he persuaded Oswald Veblen, the laboratory's chief scientist, to approve the idea. The Army allocated about $500,000, and Goldstine became the project's Army liaison and manager.", "In 1946 he and Adele published one of the first technical descriptions of ENIAC. A reviewer said that, 'almost overnight as it were', it had sped up some calculations by a factor of more than 1,000.", "His chance meeting with John von Neumann on a railway platform in 1944 brought von Neumann into the project. After the war Goldstine followed him to Princeton's Institute for Advanced Study, and they wrote the influential reports 'Planning and Coding of Problems for an Electronic Computing Instrument', which used flow diagrams to plan programs.", "He later spent many years at IBM as an IBM Fellow and wrote 'The Computer from Pascal to von Neumann' (1972), one of the first histories of computing by someone who was there. He died in 2004."], "facts": ["Persuaded the Army to fund ENIAC in April 1943", "Introduced von Neumann to ENIAC", "Co-wrote 'Planning and Coding of Problems'"], "sources": [{"title": "MacTutor: Herman Goldstine", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Goldstine/"}, {"title": "Wikipedia: Herman Goldstine", "url": "https://en.wikipedia.org/wiki/Herman_Goldstine"}, {"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}], "uncertain": ["The railway-platform meeting is from Goldstine's own memoir", "Photo is a small (345 px) public-domain Army image"], "src": "war-and-machines"}, {"id": "adele-goldstine", "section": "electronic", "name": "Adele Goldstine", "years": "1920–1964", "role": "Wrote the ENIAC manual and helped convert it to stored instructions", "photo": null, "w": null, "h": null, "credit": null, "story": ["Adele Katz was born in New York City in 1920 to Yiddish-speaking Jewish parents. Her father had emigrated from Lithuania. She went to Hunter College High School and then Hunter College.", "She earned a master's degree in mathematics at the University of Michigan at 22. There she met Herman Goldstine, and they married in 1941.", "When Herman began working with the Moore School, Adele went there too. She taught mathematics to the women 'computers' calculating ballistic trajectories and trained some of the women who became ENIAC's first programmers.", "Once the programmers had worked out how ENIAC really ran, she wrote its operators' manual, the first manual for an electronic digital computer.", "In 1946 she worked with Jean Bartik and Dick Clippinger on running stored programs on ENIAC. Bartik named her among her three favourite programming partners.", "She helped turn ENIAC into a machine that ran from a fixed set of about fifty stored instructions, so a new problem no longer meant replugging cables. She also set up problems for ENIAC for von Neumann's work at Los Alamos.", "She later worked with von Neumann and Herman at Princeton. She had two children, was diagnosed with cancer in 1962, and died in 1964, aged 43."], "facts": ["Wrote the first ENIAC operators' manual", "Helped convert ENIAC to stored instructions"], "sources": [{"title": "Wikipedia: Adele Goldstine", "url": "https://en.wikipedia.org/wiki/Adele_Goldstine"}, {"title": "MacTutor: Herman Goldstine (joint 1946 ENIAC paper)", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Goldstine/"}, {"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}], "uncertain": ["Her children's birth years differ within the same Wikipedia article (1952/1959 vs 1953/1960)", "No PD/CC photo found"], "src": "war-and-machines"}, {"id": "wilkes", "section": "electronic", "name": "Maurice Wilkes", "years": "1913–2010", "role": "Built EDSAC, the first practical stored-program computer in regular service", "photo": "people/wilkes.jpg", "w": 720, "h": 497, "credit": "Unknown author, CC BY 2.0 uk, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Maurice_Vincent_Wilkes_1980_(3).jpg", "story": ["Maurice Wilkes was born in England in 1913. He went to Cambridge in 1931 and then researched how radio waves travel through the ionosphere, which led him to tides in the atmosphere and to calculating methods.", "After war service working on radar, he returned to Cambridge in 1945 to run the university's Mathematical Laboratory, later the Computer Laboratory.", "One day the computing expert Leslie Comrie lent him von Neumann's EDVAC report. Wilkes had to read it overnight, because it had to be returned and there were no photocopiers. He decided at once that it described the future of computers.", "In summer 1946 he went to Philadelphia for the famous Moore School Lectures on electronic computers. Back home he began building his own machine, EDSAC, using mercury delay lines for memory.", "On 6 May 1949 EDSAC ran its first program. It soon went into everyday service for Cambridge scientists and ran for almost ten years. A biology problem from Ronald Fisher was among the first research it tackled.", "In 1951 Wilkes, David Wheeler and Stanley Gill published the first book on computer programming. Wilkes also proposed microprogramming, a way to build a processor's instructions out of simpler steps, which became widely used in industry.", "In 1965 he published the first paper on cache memories, the small fast memories every modern chip relies on. He received the Turing Award in 1967 and was knighted.", "He later worked for DEC and Olivetti, returned to Cambridge in 2002, and died in 2010. A working replica of EDSAC is being rebuilt at The National Museum of Computing."], "facts": ["EDSAC first ran on 6 May 1949", "Co-wrote the first programming textbook (1951)", "Proposed microprogramming; first paper on caches (1965)", "Turing Award 1967"], "sources": [{"title": "IEEE Computer Society: Maurice V. Wilkes profile", "url": "https://www.computer.org/profiles/maurice-wilkes"}, {"title": "TNMOC: EDSAC replica project", "url": "https://www.tnmoc.org/edsac"}, {"title": "Wikipedia: Maurice Wilkes", "url": "https://en.wikipedia.org/wiki/Maurice_Wilkes"}], "uncertain": ["Photo author not named on Commons (CC BY 2.0 UK)"], "src": "war-and-machines"}, {"id": "booth", "section": "electronic", "name": "Kathleen Booth", "years": "1922–2022", "role": "Co-wrote the first assembly language", "photo": null, "w": null, "h": null, "credit": null, "story": ["Kathleen Britten was born in Stourbridge, Worcestershire, in 1922. Her father was a tax clerk. She went to King Edward VI Grammar School for Girls in Birmingham.", "She took a maths degree at Royal Holloway, University of London, in 1944 and worked as a junior scientific officer at the Royal Aircraft Establishment in Farnborough.", "In 1946 she joined Andrew Booth's small computing group at Birkbeck College, London. In 1947 she travelled with him to Princeton and met John von Neumann.", "There she co-wrote a report on designing a general-purpose electronic computer, which redesigned their relay machine, ARC, along von Neumann's lines. Part of her contribution was the ARC assembly language.", "Assembly language is the step between raw machine numbers and modern languages: short words like ADD or JUMP that are translated into machine code. Every processor still has one.", "From 1947 to 1953 the Birkbeck team, one of the smallest early British groups, built three machines: ARC, the all-electronic SEC, and APE(X)C, which led to the commercial HEC series. She married Andrew Booth in 1950 and earned her PhD the same year.", "She wrote one of the first books on programming APE(X)C, co-founded Birkbeck's Department of Numerical Automation in 1957, and researched early neural networks for recognising patterns. In 1955 her group publicly demonstrated a machine-translation prototype.", "In 1962 the Booths left Birkbeck and later moved to Canada. She died in British Columbia in 2022, aged 100."], "facts": ["Co-wrote ARC's assembly language (1947)", "Helped build ARC, SEC and APE(X)C", "Lived to 100"], "sources": [{"title": "Wikipedia: Kathleen Booth", "url": "https://en.wikipedia.org/wiki/Kathleen_Booth"}], "uncertain": ["Single source (Wikipedia). MacTutor has no biography of her, and the Guardian obituary URL I tried returned 404", "How much of the assembly language she designed, compared with Andrew Booth, is unclear", "No PD/CC photo found"], "src": "war-and-machines"}, {"id": "vonneumann", "section": "electronic", "name": "John von Neumann", "years": "1903–1957", "role": "Mathematician who wrote down the stored-program design", "photo": "people/vonneumann.jpg", "w": 543, "h": 720, "credit": "Los Alamos Laboratory, Attribution, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:John_von_Neumann_Los_Alamos_identity_badge_photo.jpg", "story": ["John von Neumann was born in Budapest in 1903, the son of a top banker. As a child, nicknamed Jancsi, he was famous for his memory and his speed at mental arithmetic.", "By his twenties he was one of Europe's leading mathematicians, working on logic, set theory and the maths of quantum mechanics. In 1933 he joined the new Institute for Advanced Study in Princeton.", "He had a gift for jumping into other fields. With the economist Oskar Morgenstern he founded game theory, the maths of strategy.", "During the war he consulted on the atomic bomb at Los Alamos, which needed enormous calculations. That made him hungry for faster computing.", "In 1944, as Herman Goldstine told it, the two met on a railway platform at Aberdeen, Maryland, and Goldstine mentioned ENIAC. Von Neumann was soon visiting the Moore School and joining discussions about ENIAC's successor, EDVAC.", "In June 1945 he wrote the 'First Draft of a Report on the EDVAC'. It described a computer that keeps both its instructions and its data in one memory. That is the 'von Neumann architecture' that almost every computer still uses.", "The draft circulated with only his name on it. Eckert and Mauchly were angry, because they felt many of its ideas came from the whole team. Because it was so widely shared, the design counted as published, so no one could patent it.", "He then built his own computer at Princeton, the IAS machine, and its design was copied around the world. His wife Klára was one of the first people to program such machines.", "He died of cancer in 1957, aged 53. His unfinished lectures were published as 'The Computer and the Brain', with a preface by Klára."], "facts": ["June 1945: First Draft of a Report on the EDVAC", "Stored instructions and data in one memory", "Led the IAS computer project in Princeton"], "sources": [{"title": "MacTutor: John von Neumann", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Von_Neumann/"}, {"title": "von Neumann, First Draft of a Report on the EDVAC (Internet Archive)", "url": "https://archive.org/details/firstdraftofrepo00vonn"}, {"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}, {"title": "MacTutor: Herman Goldstine", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Goldstine/"}, {"title": "Wikipedia: Klára Dán von Neumann", "url": "https://en.wikipedia.org/wiki/Klara_Dan_von_Neumann"}], "uncertain": ["The railway-platform meeting is Goldstine's own account", "Credit for the stored-program concept is contested", "Photo license on Commons is 'Attribution' (Los Alamos National Laboratory); credit LANL"], "src": "war-and-machines"}, {"id": "atanasoff", "section": "electronic", "name": "John Vincent Atanasoff", "years": "1903–1995", "role": "Physicist who built the first automatic electronic digital computing machine", "photo": "people/atanasoff.jpg", "w": 720, "h": 589, "credit": "Eye Steel Film from Canada, CC BY 2.0, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:ATANASOFF_Pic%5E10_-_Flickr_-_Eye_Steel_Film.jpg", "story": ["John Vincent Atanasoff was born in Hamilton, New York, in 1903. His father, an electrical engineer, had emigrated from Bulgaria. His mother was a maths teacher. At nine he learned to use a slide rule and then studied logarithms.", "He studied electrical engineering at the University of Florida, earned a master's in maths at Iowa State College, and completed a PhD in theoretical physics at Wisconsin in 1930. His thesis needed endless calculations on a mechanical Monroe calculator, and the drudgery stuck with him.", "Back at Iowa State as a professor, he tried hooking calculators to IBM tabulators and built an analogue calculating device. Gears could only be made so precise, which pushed him toward digital methods.", "By his own account, the key ideas came to him in the winter of 1937–38, after a long night drive that ended in Rock Island, Illinois. They were to use electronics, use binary numbers, and store numbers in capacitors that are regularly refreshed so they don't fade.", "In September 1939 he received a $650 grant and took on a gifted graduate student, Clifford Berry. Their prototype was working by November 1939.", "The full Atanasoff–Berry Computer (ABC) had more than 300 vacuum tubes and a rotating drum of capacitors as memory, a forerunner of today's DRAM. It weighed about 700 pounds and was built to solve systems of up to 29 linear equations. It was tested in 1942, but its card system for storing intermediate results was never perfected.", "In June 1941 John Mauchly visited and studied the machine. Then the war called Atanasoff away to Navy work, and the ABC project stopped.", "In 1973, ruling in Honeywell v. Sperry Rand, a federal judge found that ENIAC's subject matter had been 'derived' from Atanasoff's work and voided the ENIAC patent. The ABC was neither programmable nor general purpose, so historians still argue about which 'first' it deserves.", "Bulgaria awarded him its Order of Saints Cyril and Methodius, First Class. He died in Maryland in 1995."], "facts": ["ABC prototype working November 1939", "Binary, electronic, with refreshed capacitor memory", "1973 court ruling found ENIAC derived from his work"], "sources": [{"title": "Wikipedia: John Vincent Atanasoff", "url": "https://en.wikipedia.org/wiki/John_Vincent_Atanasoff"}, {"title": "Wikipedia: Atanasoff–Berry computer", "url": "https://en.wikipedia.org/wiki/Atanasoff%E2%80%93Berry_computer"}, {"title": "Iowa State: John Vincent Atanasoff and the Birth of Electronic Digital Computing", "url": "https://jva.cs.iastate.edu/"}], "uncertain": ["The night-drive story is Atanasoff's own recollection", "Photo license is CC BY 2.0 via Flickr (EyeSteelFilm); the original photographer isn't named"], "src": "war-and-machines"}, {"id": "berry", "section": "electronic", "name": "Clifford Berry", "years": "1918–1963", "role": "Graduate student who co-built the Atanasoff–Berry Computer", "photo": null, "w": null, "h": null, "credit": null, "story": ["Clifford Berry was born in Gladbrook, Iowa, in 1918. His father owned an appliance repair shop, where young Clifford learned about radios.", "He graduated from Marengo High School in 1934 as class valedictorian, aged 16, and went on to Iowa State College to study electrical engineering.", "In 1939, as he finished his degree, he began working with John Atanasoff to turn Atanasoff's ideas into hardware.", "Berry did much of the hands-on design and construction of the Atanasoff–Berry Computer between 1939 and 1942.", "He earned a master's degree in physics in 1941. In 1942 he married Martha Jean Reed, an Iowa State classmate who was also Atanasoff's secretary. He completed a PhD in physics in 1948.", "After the war he worked in industry on scientific instruments and computing, including a 1949 electrical computer for spectrometer calculations.", "He died in New York in 1963, aged 45, in circumstances recorded as 'possible suicide'. He never saw the 1973 ruling that gave his and Atanasoff's machine its place in history."], "facts": ["Co-builder of the ABC (1939–42)", "PhD in physics, Iowa State, 1948"], "sources": [{"title": "Wikipedia: Clifford Berry", "url": "https://en.wikipedia.org/wiki/Clifford_Berry"}, {"title": "Wikipedia: Atanasoff–Berry computer", "url": "https://en.wikipedia.org/wiki/Atanasoff%E2%80%93Berry_computer"}], "uncertain": ["Wikipedia's article on him is short and partly sourced to dead links; his exact share of the design is hard to separate from Atanasoff's", "No PD/CC photo found"], "src": "war-and-machines"}, {"id": "mcnulty", "section": "electronic", "name": "Kathleen 'Kay' McNulty", "years": "1921–2006", "role": "ENIAC programmer", "photo": "people/mcnulty.jpg", "w": 518, "h": 720, "credit": "Zebbie, CC BY 4.0, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Kay_McNulty_enhanced_portrait.jpg", "story": ["Kathleen McNulty was born on 12 February 1921 in Creeslough, County Donegal, Ireland, during the Irish War of Independence. The night she was born, her father, an Irish Republican Army commander, was arrested and taken to Derry Jail.", "Her father was released in 1922 and went ahead to America. In 1924 the rest of the family followed, and they settled in the Chestnut Hill area of Philadelphia, where her father had trained as a stonemason.", "She went to Catholic schools and won a scholarship to Chestnut Hill College. She chose maths, she said, because it was the surest way to keep her marks up, and found she loved it: 'I didn't want to teach. I just wanted to do the maths puzzles.' She graduated in 1942.", "She answered a Moore School advert for 'math majors' and became a human 'computer', working out shell paths for the Army's firing tables. One trajectory, she explained, took 30 or 40 hours with a desk calculator, and each gun's table needed about 1,800 of them.", "In 1945 she was chosen as one of the women who would program ENIAC. With no manuals, they learned from wiring diagrams.", "She described what made ENIAC fast: breaking equations into the smallest steps and routing each one to the right unit, many at once, with every number arriving on time to within 1/5000th of a second.", "When ENIAC was shown to the world on 15 February 1946, the women were treated as hostesses and left out of official reports. Some observers even assumed they were models posing beside the machine.", "In 1948 she married John Mauchly, a widower 14 years older. Her parents disapproved and did not attend the wedding. On the honeymoon he gave her a cookbook and said, 'You are our new cook.'", "While raising seven children, five of her own and two stepchildren, she kept working, uncredited, on programs for BINAC and UNIVAC. After John's death in 1980 she married the photographer Severo Antonelli. She died in 2006."], "facts": ["Born in Creeslough, County Donegal, 1921", "Chestnut Hill College maths graduate, 1942", "One of the first ENIAC programmers", "Married John Mauchly in 1948"], "sources": [{"title": "MacTutor: Kathleen McNulty Antonelli", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Antonelli/"}, {"title": "Wikipedia: Kathleen Antonelli", "url": "https://en.wikipedia.org/wiki/Kathleen_Antonelli"}, {"title": "ENIAC Programmers Project (Kathy Kleiman) and the book Proving Ground", "url": "https://eniacprogrammers.org/"}, {"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}], "uncertain": ["Photo license CC BY 4.0, an enhanced portrait by Commons user Zebbie"], "src": "war-and-machines"}, {"id": "bartik", "section": "electronic", "name": "Jean Jennings Bartik", "years": "1924–2011", "role": "ENIAC programmer", "photo": "people/bartik.jpg", "w": 415, "h": 720, "credit": "Unidentified U.S. Army photographer, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Betty_Jennings_(Mrs._Bartik).jpg", "story": ["Betty Jean Jennings was born in 1924 near Alanthus Grove, Missouri, the sixth of seven children in a farming family full of teachers. The family was too poor to buy a newspaper, so her grandmother passed hers on every day.", "She was a local softball star, drove a car at 14 to reach the school bus, and graduated from high school at 16 with the highest maths mark the school had ever seen.", "At Northwest Missouri State Teachers College most male students left for the war, and she ended up as the only maths major. The college brought two retired teachers back to teach courses just for her. She graduated in January 1945.", "She did not want to teach. IBM turned her down, but in March 1945 a telegram asked her to come to Philadelphia as a 'computer'. She joined about 80 women calculating trajectories.", "In June 1945 a call went out for operators for ENIAC, and she was chosen. At Aberdeen Proving Ground she learned to wire the punched-card machines that fed ENIAC its data and printed its results.", "The plan was for the women to run the machine while others programmed it. ENIAC was so complicated that the women ended up doing the programming. Along the way they worked out techniques like subroutines and nested subroutines.", "With Betty Snyder she programmed the trajectory demonstration for the February 1946 press launch. It ran perfectly. In her later oral histories she recalled that the women were not invited to the celebration dinner.", "She then led a group, working with von Neumann's team, that converted ENIAC to run stored programs. She married engineer William Bartik in December 1946, and John Mauchly walked her down the aisle. She went on to work on BINAC and UNIVAC.", "After years raising three children, she earned a master's degree at Penn in 1967 and returned to computing, in technical publishing and minicomputers.", "Recognition came late. She became a Computer History Museum Fellow in 2008. Her memoir 'Pioneer Programmer' was published in 2013, two years after her death in 2011."], "facts": ["Programmed the February 1946 public demonstration", "Later worked on BINAC and UNIVAC", "CHM Fellow 2008"], "sources": [{"title": "CHM Fellow: Jean Jennings Bartik", "url": "https://www.computerhistory.org/fellowawards/hall/jean-bartik/"}, {"title": "MacTutor: Jean Bartik", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Bartik/"}, {"title": "IEEE History Center oral history: Jean Bartik", "url": "https://ethw.org/Oral-History:Jean_Bartik"}, {"title": "Wikipedia: Jean Bartik", "url": "https://en.wikipedia.org/wiki/Jean_Bartik"}, {"title": "CHM: Jean Bartik oral history (catalog 102658322)", "url": "https://www.computerhistory.org/collections/catalog/102658322"}, {"title": "ENIAC Programmers Project (Kathy Kleiman) and the book Proving Ground", "url": "https://eniacprogrammers.org/"}], "uncertain": ["MacTutor describes the first group as five women; most accounts, including the ENIAC Programmers Project, say six", "The 'not invited to dinner' story comes from Bartik's own oral histories"], "src": "war-and-machines"}, {"id": "holberton", "section": "electronic", "name": "Frances 'Betty' Snyder Holberton", "years": "1917–2001", "role": "ENIAC programmer", "photo": "people/holberton.jpg", "w": 558, "h": 720, "credit": "Unknown photographer, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Betty-Holbeton-circa-1950s-600dpi.jpg", "story": ["Frances Elizabeth Snyder was born in Philadelphia in 1917, the third of eight children.", "On her first day at the University of Pennsylvania, she later recalled, a maths professor asked whether she wouldn't be better off at home raising children. She studied journalism instead, partly because it promised travel.", "During the war the Moore School hired at least 200 women as human 'computers' for the Army's ballistics work. Betty Snyder was one of them, and in 1945 she was chosen as one of ENIAC's six programmers.", "The women were classed as 'subprofessionals', even though men with the same degrees were 'professionals'. At first ENIAC was classified, so they had to learn to program it from blueprints and wiring diagrams alone.", "Colleagues joked that she 'solved more problems in her sleep than other people did awake'. She is credited with inventing breakpoints, which pause a program at a chosen step so you can look inside.", "With Jean Jennings she programmed the trajectory demonstration for ENIAC's public unveiling on 15 February 1946.", "Afterwards she worked with Mauchly on the C-10 instruction set for BINAC, and then on UNIVAC. She put the numeric keypad next to the keyboard and persuaded engineers to swap UNIVAC's black casing for a grey-beige, which became the classic colour of computers.", "Her sort-merge generator took a description of your data and produced a custom sorting program. Grace Hopper said: 'Everybody's forgotten that she wrote the first program that wrote a program.' She worked out its sorting logic with a deck of playing cards.", "She wrote a statistical analysis package used for the 1950 US Census. Later she led programming research for the Navy and worked at the National Bureau of Standards, helping set the standards for COBOL and FORTRAN.", "She won the IEEE Computer Pioneer Award and the Ada Lovelace Award in 1997, and died in 2001."], "facts": ["One of the six ENIAC programmers", "Wrote the SORT/MERGE generator for UNIVAC", "Worked on COBOL and FORTRAN standards"], "sources": [{"title": "Wikipedia: Betty Holberton", "url": "https://en.wikipedia.org/wiki/Betty_Holberton"}, {"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}, {"title": "ENIAC Programmers Project (Kathy Kleiman) and the book Proving Ground", "url": "https://eniacprogrammers.org/"}, {"title": "Wikipedia: ENIAC (programmers section)", "url": "https://en.wikipedia.org/wiki/ENIAC"}], "uncertain": ["The beige-console and playing-card stories come from interviews, not records"], "src": "war-and-machines"}, {"id": "wescoff", "section": "electronic", "name": "Marlyn Wescoff Meltzer", "years": "1922–2008", "role": "ENIAC programmer", "photo": "people/wescoff.jpg", "w": 251, "h": 720, "credit": "U.S. Government, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Marlyn_Meltzer.png", "story": ["Marlyn Wescoff was born in Philadelphia in 1922 and graduated from Temple University in 1942.", "The Moore School first hired her to do weather calculations, largely because she already knew how to run an adding machine.", "In 1943 she moved to the ballistics work, calculating shell trajectories on mechanical desk calculators as one of the Army's women 'computers'.", "In 1945 she was chosen as one of ENIAC's six original programmers. The machine had 17,468 vacuum tubes and about 5 million hand-soldered joints, weighed more than 30 tons, and was programmed by plugging cables and setting switches.", "She worked closely with Ruth Lichterman. The two taught themselves how parts of ENIAC worked and helped prepare the trajectory programs.", "When ENIAC was unveiled in February 1946, the headlines went to the male engineers. The women who had made it calculate were barely mentioned.", "In 1947 she left the team to get married, before ENIAC moved to Maryland.", "In 1997 she and the other ENIAC programmers were inducted into the Women in Technology International Hall of Fame.", "She spent decades volunteering. She delivered Meals on Wheels for more than ten years and, in her last four years, knitted more than 500 hats for people going through chemotherapy. She died in 2008."], "facts": ["Temple University graduate, 1942", "Left the ENIAC team in 1947", "WITI Hall of Fame 1997"], "sources": [{"title": "Wikipedia: Marlyn Meltzer", "url": "https://en.wikipedia.org/wiki/Marlyn_Meltzer"}, {"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}, {"title": "ENIAC Programmers Project (Kathy Kleiman) and the book Proving Ground", "url": "https://eniacprogrammers.org/"}, {"title": "Wikipedia: Ruth Teitelbaum", "url": "https://en.wikipedia.org/wiki/Ruth_Teitelbaum"}], "uncertain": ["Detailed information about her career is thin, and most accounts trace back to a few interviews"], "src": "war-and-machines"}, {"id": "bilas", "section": "electronic", "name": "Frances Bilas Spence", "years": "1922–2012", "role": "ENIAC programmer", "photo": "people/bilas.jpg", "w": 720, "h": 494, "credit": "Unidentified U.S. Army photographer, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Two_women_operating_ENIAC_(full_resolution).jpg", "story": ["Frances Bilas was born in Philadelphia in 1922, the second of five sisters. Her father was an engineer for the city's public school system and her mother was a teacher.", "She graduated from the South Philadelphia High School for Girls in 1938. She started at Temple University, then moved to Chestnut Hill College on a scholarship and studied maths with a minor in physics.", "At Chestnut Hill she met Kathleen McNulty. After graduating in 1942, the two joined the Moore School's computing team.", "She was part of a team of about 80 women computing ballistic trajectories. She and McNulty also worked on the differential analyser, a giant mechanical machine of shafts and gears.", "In 1945 she was chosen as one of ENIAC's six programmers. One of the best-known Army photos shows her with Jean Jennings at ENIAC's main control panel.", "At the February 1946 unveiling the Army did not name the women, and newspaper photos of them often ran without credit.", "She kept working on ENIAC after the war. In 1947 she married Homer Spence, an Army electrical engineer assigned to ENIAC who later headed the Army's Computer Research Branch.", "Soon after the wedding she left to raise their three sons. She was inducted into the Women in Technology International Hall of Fame in 1997 and died in 2012."], "facts": ["Studied maths at Chestnut Hill College", "Married Army engineer Homer Spence in 1947"], "sources": [{"title": "Wikipedia: Frances Spence", "url": "https://en.wikipedia.org/wiki/Frances_Spence"}, {"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}, {"title": "ENIAC Programmers Project (Kathy Kleiman) and the book Proving Ground", "url": "https://eniacprogrammers.org/"}], "uncertain": ["Photo is the PD Army photo 'Two women operating ENIAC'. Identification of Bilas in it follows Commons and the US Army caption", "Parts of Wikipedia's career section on her are marked as needing citations"], "src": "war-and-machines"}, {"id": "lichterman", "section": "electronic", "name": "Ruth Lichterman Teitelbaum", "years": "1924–1986", "role": "ENIAC programmer", "photo": "people/lichterman.jpg", "w": 453, "h": 720, "credit": "U.S. Government, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Ruth_Teitelbaum.png", "story": ["Ruth Lichterman was born in the Bronx, New York, on 1 February 1924, the elder of two children of Jewish immigrants from Russia. Her father was a teacher.", "She earned a degree in mathematics from Hunter College in New York.", "The Moore School hired her to compute ballistic trajectories, as part of a group of about 80 women doing the Army's calculations by hand.", "In 1945 she was chosen as one of ENIAC's six programmers. ENIAC had 40 black panels, each eight feet tall, and a program meant setting around 3,000 switches and routing cables to carry numbers and instructions through the machine.", "She and Marlyn Wescoff formed a pair, teaching themselves how parts of ENIAC worked and preparing the ballistics programs. The programmers earned $1,620 a year.", "When ENIAC moved to the Army's Ballistic Research Laboratory at Aberdeen Proving Ground, Maryland, she went with it. She stayed two more years and trained the next group of ENIAC programmers.", "She married Arnold Teitelbaum and later moved to Dallas. She died in 1986, years before the ENIAC women became famous.", "Her story was told later in documentaries, including 'Top Secret Rosies' (2010) and 'The Computers' (2013), made by Kathy Kleiman and the ENIAC Programmers Project."], "facts": ["Hunter College maths graduate", "Trained the next ENIAC programmers at Aberdeen"], "sources": [{"title": "Wikipedia: Ruth Teitelbaum", "url": "https://en.wikipedia.org/wiki/Ruth_Teitelbaum"}, {"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}, {"title": "ENIAC Programmers Project (Kathy Kleiman) and the book Proving Ground", "url": "https://eniacprogrammers.org/"}], "uncertain": ["Few primary sources about her life survive", "Wikipedia's career section on her is flagged as needing citations"], "src": "war-and-machines"}, {"id": "klara", "section": "electronic", "name": "Klára Dán von Neumann", "years": "1911–1963", "role": "Early ENIAC and MANIAC programmer", "photo": null, "w": null, "h": null, "credit": null, "story": ["Klára Dán was born in Budapest on 18 August 1911 into a wealthy Jewish family. Friends called her Klári. At 14 she became a national figure-skating champion.", "She married young and divorced twice. During her first marriage, at a casino in Monte Carlo, she met the mathematician John von Neumann. He claimed to have a system to win at roulette, promptly lost all his money, and asked her to buy him a drink.", "They married in 1938 and moved to Princeton. On her immigration papers she listed her job as 'housewife'. In 1939 she sailed back to Hungary to persuade her family to leave. Her father, uprooted from his home and factory, took his own life later that year.", "When the US entered the war, jobs opened up for women. At Princeton's Office of Population Research she headed a statistical computing group and shared an office with Adele Goldstine. In 1947 she took a calculus course at Princeton.", "That summer she and Adele Goldstine were contracted to work for Los Alamos. Von Neumann and colleagues wanted to run 'Monte Carlo' simulations on ENIAC, which use random numbers to model things like neutrons moving through a bomb core.", "In 1948 ENIAC was converted to run programs written as a code of instructions instead of a tangle of cables. Klára designed new controls for it and was one of its main programmers. She wrote the code for some of the first Monte Carlo simulations ever run on a computer.", "She trained people from the Manhattan Project to program and helped meteorologists use ENIAC for the first computer weather forecasts. On that project she spent 32 days checking the final code and managing 100,000 punched cards so that no data was lost.", "She also programmed MANIAC I at Los Alamos. After John's death in 1957 she wrote the preface to his lectures 'The Computer and the Brain', married the physicist Carl Eckart, and wrote an unpublished memoir, 'A Grasshopper in Very Tall Grass'.", "She died in San Diego in 1963. For decades she was a footnote in her husband's story. In 2022 the podcast 'Lost Women of Science' gave her a full season of her own."], "facts": ["Wrote code for early Monte Carlo runs on ENIAC (1948)", "Taught meteorologists to program ENIAC"], "sources": [{"title": "Wikipedia: Klára Dán von Neumann", "url": "https://en.wikipedia.org/wiki/Klara_Dan_von_Neumann"}, {"title": "Wikipedia: Adele Goldstine", "url": "https://en.wikipedia.org/wiki/Adele_Goldstine"}], "uncertain": ["No PD/CC photo found on Commons", "Her Wikipedia article is flagged for needing more citations; key claims trace to Haigh, Priestley and Rope's 'ENIAC in Action' (2016), which I didn't check directly", "Usually reported as drowning at La Jolla (San Diego)"], "src": "war-and-machines"}, {"id": "hopper", "section": "software", "name": "Grace Hopper", "years": "1906–1992", "role": "Navy officer, compiler pioneer, driving force behind COBOL", "photo": "people/hopper.jpg", "w": 576, "h": 720, "credit": "Public domain, via Wikimedia Commons (see v8 IMAGE-CREDITS.md)", "story": ["Grace Hopper earned a PhD in mathematics from Yale in 1934 and was teaching at Vassar when the war came. She joined the US Navy Reserve in 1943.", "The Navy sent her to Harvard to work on the Mark I, a 51-foot electromechanical calculator. She became one of its first programmers and wrote much of its manual.", "In 1947 operators of the Mark II found a moth stuck in a relay and taped it into the logbook as the 'first actual case of bug being found'. Hopper loved telling the story, though the word 'bug' was older.", "At the UNIVAC company she had a radical idea: let computers translate something close to English into machine code. In 1952 she wrote the A-0 system, an early compiler. Many people told her computers could only do arithmetic.", "Her FLOW-MATIC language inspired COBOL, designed in 1959 for business. It became one of the most used languages in history.", "She taught by props. She handed out pieces of wire about 30 cm long to show how far light travels in a nanosecond.", "She retired from the Navy in 1986 as a rear admiral, at 79, then the oldest serving officer. She received the Presidential Medal of Freedom after her death, in 2016, and a Yale college was renamed for her in 2017."], "facts": ["1952: A-0 compiler", "FLOW-MATIC fed into COBOL (1959)", "Retired as rear admiral in 1986"], "sources": [{"title": "MacTutor: Grace Hopper", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Hopper/"}, {"title": "CHM Fellow: Grace Murray Hopper", "url": "https://www.computerhistory.org/fellowawards/hall/grace-murray-hopper/"}, {"title": "Yale News: Hopper College", "url": "https://news.yale.edu/2017/02/11/yale-change-calhoun-college-s-name-honor-grace-murray-hopper"}], "uncertain": ["She did not find the moth herself or coin the word 'bug'", "'First compiler' claims depend on definitions"], "src": "war-and-machines"}, {"id": "backus", "section": "software", "name": "John Backus", "years": "1924–2007", "role": "Led the team that created FORTRAN; co-inventor of BNF", "photo": "people/backus.jpg", "w": 238, "h": 356, "credit": "PIerre.Lescanne, CC BY-SA 4.0, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:John_Backus_2.jpg", "story": ["John Backus was born in Philadelphia in 1924. His father, a chemist who became a banker, worked in Wilmington, Delaware. Backus admitted he was a poor student.", "He went to the University of Virginia to study chemistry, at his father's request. He liked the theory but disliked the lab work intensely, went to every party he could find, and his studies were soon ended.", "In 1943 he joined the Army and was made a corporal in charge of an anti-aircraft crew in Georgia. Army tests sent him toward engineering and medicine, but neither stuck.", "Back in New York he took a maths course, found he liked how maths could be applied, and enrolled at Columbia. He earned a master's in mathematics in 1950.", "Just before graduating he wandered into IBM's Computer Center on Madison Avenue, said he was looking for a job, and was sent to talk to a director. He was hired as a programmer.", "Programming then meant writing machine code by hand, slow and full of mistakes. In 1953 Backus proposed a language that would let scientists write formulas almost as in maths. 'We did not know what we wanted and how to do it,' he later said. The goal was code nearly as fast as hand-written code, or nobody would trust it.", "FORTRAN, short for 'Formula Translation', became commercially available for the IBM 704 in 1957. It was fast and it spread everywhere. It is still used for weather, climate and physics today.", "In 1959 he invented a notation for describing a language's grammar, which Peter Naur refined for ALGOL. It is now called Backus–Naur Form and is still used to define programming languages.", "He won the Turing Award in 1977. In his lecture he surprised people by criticising languages like FORTRAN and arguing for 'functional' programming. He died in Oregon in 2007."], "facts": ["FORTRAN released 1957 for the IBM 704", "Backus–Naur Form for ALGOL", "Turing Award 1977"], "sources": [{"title": "MacTutor: John Backus", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Backus/"}, {"title": "CHM Fellow: John Backus", "url": "https://www.computerhistory.org/fellowawards/hall/john-backus/"}, {"title": "IBM: Fortran", "url": "https://www.ibm.com/history/fortran"}], "uncertain": ["Photo is small (238 px), CC BY-SA 4.0"], "src": "war-and-machines"}, {"id": "sammet", "section": "software", "name": "Jean Sammet", "years": "1928–2017", "role": "COBOL designer, creator of FORMAC, historian of languages", "photo": "people/sammet.jpg", "w": 720, "h": 493, "credit": "Ben Shneiderman, CC BY-SA 4.0, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Jean_Sammet_UMD_1979.jpg", "story": ["Jean Sammet was born in New York City in 1928. She loved maths but could not attend the Bronx High School of Science, which did not accept girls then, so she went to Julia Richman High School.", "She took a maths degree at Mount Holyoke College and a master's at the University of Illinois in 1949.", "From 1955 to 1958 she worked at Sperry Gyroscope, where she supervised early scientific programming and worked on the SPEEDAC computer. After Sperry merged with Remington Rand, she also worked alongside Grace Hopper's group.", "At Sylvania Electric she worked on software for MOBIDIC, a mobile military computer. In 1959 she joined the short-range committee that designed COBOL, the business language, which built on Hopper's FLOW-MATIC.", "In 1961 she moved to IBM, where she led the creation of FORMAC. It was the first widely used language for working with algebra symbols rather than just numbers, an ancestor of today's maths software.", "In 1969 she published 'Programming Languages: History and Fundamentals', a huge survey of about 120 languages that became a standard reference.", "She was the first woman president of the ACM, the main computing society, from 1974 to 1976.", "She spent her later years making sure the history of programming languages was recorded, and gave long oral histories herself. She died in 2017."], "facts": ["Member of the original COBOL committee", "FORMAC (1962)", "First female ACM president, 1974–76"], "sources": [{"title": "ETHW: Jean Sammet", "url": "https://ethw.org/Jean_Sammet"}, {"title": "IEEE oral history: Jean Sammet", "url": "https://ethw.org/Oral-History:Jean_Sammet"}, {"title": "Wikipedia: Jean E. Sammet", "url": "https://en.wikipedia.org/wiki/Jean_E._Sammet"}], "uncertain": [], "src": "war-and-machines"}, {"id": "thompson", "section": "software", "name": "Ken Thompson", "years": "born 1943", "role": "Co-creator of Unix, B, UTF-8 and Go", "photo": "people/thompson.jpg", "w": 310, "h": 201, "credit": "Unknown author, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Ken_Thompson_and_Dennis_Ritchie--1973.jpg", "story": ["Ken Thompson was born in New Orleans in 1943. He studied electrical engineering at the University of California, Berkeley, and joined Bell Labs in 1966.", "Bell Labs was then part of Multics, a big joint project to build a time-sharing operating system. In 1969 Bell Labs pulled out. Thompson missed the shared, interactive computing Multics offered.", "That year he found a little-used PDP-7 minicomputer. With Dennis Ritchie and others he wrote a small operating system for it. By his own account, he wrote the core pieces in about a month while his wife and baby were away.", "That system became Unix. Its ideas, such as small tools that each do one job well and can be chained together, a simple file system, and a shell for typing commands, still shape Linux, macOS and Android.", "He wrote the B language, which Ritchie grew into C. He also wrote early tools that are still in daily use, such as the text-search program grep.", "With Joe Condon he built Belle, a dedicated chess machine that became a champion of computer chess.", "With Rob Pike he designed UTF-8, the text encoding that now carries almost every web page in every language. He also worked on the Plan 9 operating system.", "Thompson and Ritchie shared the 1983 Turing Award. Later, at Google, he co-designed the Go programming language."], "facts": ["Unix began on a PDP-7 in 1969", "Created the B language", "Co-designed UTF-8 and Go", "Turing Award 1983"], "sources": [{"title": "Dennis Ritchie, 'The Evolution of the Unix Time-sharing System' (Bell Labs)", "url": "https://www.nokia.com/bell-labs/about/dennis-m-ritchie/hist.html"}, {"title": "CHM Fellow: Ken Thompson", "url": "https://www.computerhistory.org/fellowawards/hall/ken-thompson/"}, {"title": "Wikipedia: Ken Thompson", "url": "https://en.wikipedia.org/wiki/Ken_Thompson"}], "uncertain": ["'About a month' is Thompson's own recollection", "Photo is a small PD photo showing both Thompson and Ritchie"], "src": "war-and-machines"}, {"id": "ritchie", "section": "software", "name": "Dennis Ritchie", "years": "1941–2011", "role": "Creator of C and co-creator of Unix", "photo": "people/ritchie.jpg", "w": 310, "h": 201, "credit": "Unknown author, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Ken_Thompson_and_Dennis_Ritchie--1973.jpg", "story": ["Dennis Ritchie was born in 1941 near New York City.", "He studied physics and applied mathematics at Harvard, then joined Bell Labs in 1967.", "He worked side by side with Ken Thompson on Unix from the start, beginning on a PDP-7 in 1969.", "Thompson's B language was too limited for the newer PDP-11 computer. Between 1969 and 1973 Ritchie grew it into C, with the most creative period in 1972. C stayed close to the hardware but was much easier to read and write than assembly.", "In the summer of 1973, C was strong enough that they rewrote the Unix kernel for the PDP-11 in it. An operating system written in a high-level language could be moved to new computers far more easily.", "In 1978 he and Brian Kernighan published 'The C Programming Language', the book that starts by printing 'hello, world'.", "Unix and C spread through universities and then industry. Their descendants run phones, servers, cars and spacecraft.", "Ritchie was modest and wrote careful histories of his own work, which are still online. He shared the 1983 Turing Award with Thompson. He died in October 2011, a week after Steve Jobs, with far less fanfare."], "facts": ["Created C around 1972", "Unix rewritten in C in 1973", "K&R book 1978"], "sources": [{"title": "Dennis Ritchie, 'The Development of the C Language' (Bell Labs)", "url": "https://www.nokia.com/bell-labs/about/dennis-m-ritchie/chist.html"}, {"title": "Dennis Ritchie, 'The Evolution of the Unix Time-sharing System' (Bell Labs)", "url": "https://www.nokia.com/bell-labs/about/dennis-m-ritchie/hist.html"}, {"title": "CHM Fellow: Dennis Ritchie", "url": "https://www.computerhistory.org/fellowawards/hall/dennis-ritchie/"}, {"title": "Dennis Ritchie home page (Bell Labs)", "url": "https://www.bell-labs.com/usr/dmr/www/"}], "uncertain": [], "src": "war-and-machines"}, {"id": "torvalds", "section": "software", "name": "Linus Torvalds", "years": "born 1969", "role": "Creator of Linux and Git", "photo": "people/torvalds.jpg", "w": 517, "h": 720, "credit": "Krd (photo)Von Sprat (crop/extraction), CC BY-SA 4.0, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:LinuxCon_Europe_Linus_Torvalds_03_(cropped).jpg", "story": ["Linus Torvalds was born in Helsinki in 1969. He started programming on his grandfather's Commodore VIC-20.", "He studied computer science at the University of Helsinki. In 1991 he bought a PC with an Intel 386 chip and was using Minix, a small teaching version of Unix.", "He wanted something better, so he started writing his own kernel, the core of an operating system that manages memory, files and programs.", "On 25 August 1991 he posted to the comp.os.minix newsgroup: 'I'm doing a (free) operating system (just a hobby, won't be big and professional like gnu) for 386(486) AT clones.'", "He shared the code online, and volunteers around the world sent fixes and features. From 1992 it used the GNU General Public License, so anyone could use and change it as long as they shared their changes.", "Combined with GNU's tools, Linux became a complete free operating system. Today it runs most web servers, the world's top supercomputers and every Android phone.", "In 2005 he wrote Git to manage Linux's code. It became the standard tool for tracking code changes almost everywhere.", "He still coordinates kernel development. His motto, quoted by the Computer History Museum, is 'Talk is cheap. Show me the code.' He became a CHM Fellow in 2008."], "facts": ["Announced Linux on 25 August 1991", "Linux under GPL since 1992", "Created Git in 2005"], "sources": [{"title": "Linus Torvalds, LINUX's History (archived posts)", "url": "https://www.cs.cmu.edu/~awb/linux.history.html"}, {"title": "CHM Fellow: Linus Torvalds", "url": "https://www.computerhistory.org/fellowawards/hall/linus-torvalds/"}], "uncertain": ["Photo CC BY-SA 4.0"], "src": "war-and-machines"}, {"id": "stallman", "section": "software", "name": "Richard Stallman", "years": "born 1953", "role": "Founder of the GNU Project and the free software movement", "photo": "people/stallman.jpg", "w": 556, "h": 720, "credit": "Ruben Rodriguez, CC BY 4.0, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Richard_Stallman_at_LibrePlanet_2019.jpg", "story": ["Richard Stallman worked at MIT's AI Lab in the 1970s, where programmers freely shared and improved each other's code.", "Around 1980 the lab got a new Xerox laser printer that kept jamming. Stallman had fixed the old printer's software to warn people. This time the source code was secret. That stuck with him.", "On 27 September 1983 he announced GNU ('GNU's Not Unix'), a plan to write a complete free Unix-like system.", "By 'free' he meant freedom, not price: freedom to run, study, change and share software.", "In 1985 he founded the Free Software Foundation, and in 1989 he released the GNU General Public License.", "GNU's tools, such as the GCC compiler and Emacs editor, joined the Linux kernel to make a complete system.", "He remains a divisive figure. He resigned from MIT and the FSF in 2019 after controversial comments, and returned to the FSF board in 2021."], "facts": ["GNU announced 27 September 1983", "FSF founded 1985", "GPL 1989"], "sources": [{"title": "GNU Project: Initial Announcement", "url": "https://web.archive.org/web/2015/http://www.gnu.org/gnu/initial-announcement.html"}, {"title": "Free Software Foundation: About", "url": "https://www.fsf.org/about/"}, {"title": "Wikipedia: Richard Stallman", "url": "https://en.wikipedia.org/wiki/Richard_Stallman"}], "uncertain": ["Printer story details come from Stallman's own accounts"], "src": "war-and-machines"}, {"id": "hamilton", "section": "software", "name": "Margaret Hamilton", "years": "born 1936", "role": "Led Apollo flight software at MIT", "photo": "people/hamilton.jpg", "w": 579, "h": 720, "credit": "Adam Cuerden, Public domain, via Wikimedia Commons: https://commons.wikimedia.org/wiki/File:Margaret_Hamilton_-_restoration.jpg", "story": ["Margaret Hamilton studied maths at Earlham College. She took a job at MIT in 1959, planning to support her husband through law school and then study maths herself.", "She worked on weather software and then on SAGE, an air-defence system.", "In the 1960s she joined MIT's Instrumentation Laboratory, which was writing the software for Apollo's onboard computers. She became leader of the team.", "She often brought her young daughter Lauren to the lab. Lauren once crashed a simulator by starting a programme mid-flight. Hamilton wanted to add protection. She was told astronauts would never make that mistake, until one did on Apollo 8.", "During the Apollo 11 landing in July 1969, alarms '1201' and '1202' flashed. The computer was overloaded, but the software was designed to drop low-priority jobs and keep the landing tasks running. The landing went on.", "She pushed the term 'software engineering' so that writing code would be taken as seriously as building hardware.", "She received NASA's Exceptional Space Act Award in 2003 and the Presidential Medal of Freedom in 2016. A famous photo shows her next to a stack of Apollo code listings as tall as she is."], "facts": ["Led Apollo onboard flight software", "Apollo 11 software handled 1201/1202 overloads", "Presidential Medal of Freedom 2016"], "sources": [{"title": "CHM Fellow: Margaret Hamilton", "url": "https://www.computerhistory.org/fellowawards/hall/margaret-hamilton/"}, {"title": "MIT News: Margaret Hamilton's Apollo code", "url": "https://news.mit.edu/2016/scene-at-mit-margaret-hamilton-apollo-code-0817"}, {"title": "WIRED: Her Code Got Humans on the Moon", "url": "https://www.wired.com/2015/10/margaret-hamilton-nasa-apollo/"}], "uncertain": ["Whether she personally coined 'software engineering' is debated", "The stack of listings in the photo includes code for more than one mission"], "src": "war-and-machines"}];
window.EXTRA_ACC=[{"section": "ai1", "title": "The summer of 1956: what actually happened at Dartmouth", "paras": ["The 1955 proposal by McCarthy, Minsky, Nathaniel Rochester and Claude Shannon guessed that 'every aspect of learning or any other feature of intelligence can in principle be so precisely described that a machine can be made to simulate it.'", "The workshop ran for roughly eight weeks in summer 1956. People came and went; it was more a long brainstorm than a conference.", "Allen Newell and Herbert Simon brought a working program, the Logic Theorist, which proved theorems from Principia Mathematica. The workshop solved nothing outright, but it gave the field a name and a community."], "sources": [{"title": "Dartmouth workshop — Wikipedia", "url": "https://en.wikipedia.org/wiki/Dartmouth_workshop"}, {"title": "Logic Theorist — Wikipedia", "url": "https://en.wikipedia.org/wiki/Logic_Theorist"}, {"title": "Dartmouth proposal, AI Magazine reprint", "url": "https://ojs.aaai.org/aimagazine/index.php/aimagazine/article/view/1904"}]}, {"section": "ai1", "title": "The AI winters: why the money froze, twice", "paras": ["The first winter came in the mid-1970s. In Britain, the 1973 Lighthill report judged that AI had not delivered on its promises, and support was cut. In the U.S., DARPA shifted toward mission-focused funding.", "The second winter hit in the late 1980s, when the market for specialized Lisp machines collapsed and expert systems proved brittle and costly to maintain.", "The pattern — big promises, narrow progress, disappointment — is often cited as a caution for today's boom."], "sources": [{"title": "AI winter — Wikipedia", "url": "https://en.wikipedia.org/wiki/AI_winter"}, {"title": "Lighthill report — Wikipedia", "url": "https://en.wikipedia.org/wiki/Lighthill_report"}]}, {"section": "ai1", "title": "Backpropagation: the key that unlocked hidden layers", "paras": ["In 1986 Rumelhart, Hinton and Williams showed in Nature that networks with hidden layers could learn useful internal features by passing errors backward through the network.", "Others, including Paul Werbos, had worked along similar lines earlier with little impact. Hinton credits the 1986 work's influence to its clear demonstrations and its publication in Nature."], "sources": [{"title": "Rumelhart, Hinton & Williams 1986 — Nature", "url": "https://www.nature.com/articles/323533a0"}, {"title": "ACM laureate profile — Hinton (by Thomas Haigh)", "url": "https://amturing.acm.org/award_winners/hinton_4791679.cfm"}, {"title": "Backpropagation — Wikipedia", "url": "https://en.wikipedia.org/wiki/Backpropagation"}]}, {"section": "ai1", "title": "Two roads: symbols vs. neurons", "paras": ["From the start AI split into two camps. The symbolic camp (McCarthy, Minsky, Newell, Simon) tried to program logic and rules. The connectionist camp (Rosenblatt, later Hinton) tried to grow intelligence from networks that learn.", "Pearl's probability work offered a path both camps borrowed from. Today's systems are mostly connectionist, but debates about adding reasoning and symbols continue."], "sources": [{"title": "ACM laureate profile — Pearl", "url": "https://amturing.acm.org/award_winners/pearl_2658896.cfm"}, {"title": "Perceptrons (book) — Wikipedia", "url": "https://en.wikipedia.org/wiki/Perceptrons_(book)"}]}, {"section": "ai2", "title": "Why GPUs changed everything", "paras": ["Neural networks mostly multiply big grids of numbers, over and over. Graphics cards were designed to do exactly that for video-game pixels.", "AlexNet's 60 million parameters were trained on two GPUs. Within a few years nearly all deep learning ran on GPUs, and NVIDIA reshaped itself around AI."], "sources": [{"title": "ACM laureate profile — Hinton", "url": "https://amturing.acm.org/award_winners/hinton_4791679.cfm"}, {"title": "AlexNet — Wikipedia", "url": "https://en.wikipedia.org/wiki/AlexNet"}]}, {"section": "ai2", "title": "The data behind the magic", "paras": ["ImageNet was labeled by large numbers of crowd workers. Later studies found errors and offensive labels in its 'person' categories, and many were removed in 2019 — a reminder that AI learns whatever is in its data."], "sources": [{"title": "ImageNet — Wikipedia", "url": "https://en.wikipedia.org/wiki/ImageNet"}]}, {"section": "ai2", "title": "Move 37 and Move 78", "paras": ["In game two AlphaGo played a fifth-line stone that commentators took for a slip; AlphaGo estimated a human would play it about 1 in 10,000 times. It helped win the game.", "In game four Lee Sedol answered with his own surprising move 78, giving humanity its only win of the match."], "sources": [{"title": "AlphaGo versus Lee Sedol — Wikipedia", "url": "https://en.wikipedia.org/wiki/AlphaGo_versus_Lee_Sedol"}, {"title": "Silver et al. 2016 — Nature", "url": "https://www.nature.com/articles/nature16961"}]}, {"section": "ai2", "title": "The Canadian bet", "paras": ["From 2004 to 2013 Hinton directed a CIFAR program on 'Neural Computation and Adaptive Perception' that included LeCun and Bengio. This small Canadian program kept the deep-learning trio meeting and sharing ideas while the field was out of fashion."], "sources": [{"title": "ACM laureate profile — Hinton", "url": "https://amturing.acm.org/award_winners/hinton_4791679.cfm"}]}, {"section": "ai3", "title": "How attention works, in one breath", "paras": ["For each word, the model forms a question ('what am I looking for?'), every word offers a label ('what I contain'), and the best matches share information. Many such 'heads' run side by side, each noticing different patterns.", "Because all words are processed at once rather than one after another, Transformers train fast on GPUs."], "sources": [{"title": "Vaswani et al., 'Attention Is All You Need' (2017), arXiv", "url": "https://arxiv.org/abs/1706.03762"}]}, {"section": "ai3", "title": "Why Google didn't ship ChatGPT first", "paras": ["Google filed defensive patents and put Transformers into Translate and, via BERT, search in 2018–19. Uszkoreit told Wired the team could probably have had GPT-3-class systems by 2019 or 2020; the hard question was why Google didn't act. OpenAI moved faster."], "sources": [{"title": "Steven Levy, '8 Google Employees Invented Modern AI', WIRED, 2024", "url": "https://www.wired.com/story/eight-google-employees-invented-modern-ai-transformers-paper/"}]}, {"section": "ai3", "title": "The scaling era in numbers", "paras": ["GPT-2 (2019) had 1.5 billion parameters; GPT-3 (2020) had 175 billion and could do new tasks from a few examples in the prompt.", "ChatGPT launched in November 2022 and was widely reported to reach about 100 million users within two months."], "sources": [{"title": "Brown et al. 2020 — arXiv", "url": "https://arxiv.org/abs/2005.14165"}, {"title": "Large language model — Wikipedia", "url": "https://en.wikipedia.org/wiki/Large_language_model"}]}, {"section": "ai3", "title": "Does scaling go on forever?", "paras": ["Sutton's 'Bitter Lesson' argues general methods that use more compute keep winning. LeCun argues new ideas are needed. Limits under discussion include running short of high-quality text and the power needed for data centers."], "sources": [{"title": "Sutton, The Bitter Lesson", "url": "http://www.incompleteideas.net/IncIdeas/BitterLesson.html"}, {"title": "Neural scaling law — Wikipedia", "url": "https://en.wikipedia.org/wiki/Neural_scaling_law"}]}, {"section": "quantum", "title": "IBM opens the cloud, Google pushes the edge", "paras": ["In May 2016 IBM put a 5-qubit processor online free for anyone; students worldwide ran their first quantum programs from a browser.", "Google's Willow (December 2024) has 105 superconducting transmon qubits and showed errors shrinking as a logical qubit grows — 'below threshold'. Critics note its logical error rate (~0.14% per cycle) is still far above what large algorithms need."], "sources": [{"title": "IBM Quantum Experience — Wikipedia", "url": "https://en.wikipedia.org/wiki/IBM_Quantum_Experience"}, {"title": "Willow processor — Wikipedia", "url": "https://en.wikipedia.org/wiki/Willow_processor"}, {"title": "Acharya et al., Nature 2024", "url": "https://doi.org/10.1038/s41586-024-08449-y"}]}, {"section": "quantum", "title": "The supremacy argument", "paras": ["'Quantum supremacy' (or 'advantage') means a quantum computer doing a task no classical computer can do in reasonable time — even a useless one. Each claim so far has been challenged by cleverer classical algorithms."], "sources": [{"title": "Quantum supremacy — Wikipedia", "url": "https://en.wikipedia.org/wiki/Quantum_supremacy"}, {"title": "Arute et al. 2019 — Nature", "url": "https://www.nature.com/articles/s41586-019-1666-5"}]}, {"section": "quantum", "title": "Physical vs. logical qubits", "paras": ["A physical qubit is one noisy device. A logical qubit is many physical qubits working together with error correction to act like one reliable qubit. Estimates for breaking RSA-2048 keep falling — a 2025 study put it under a million noisy qubits — still far beyond today's machines."], "sources": [{"title": "Physical and logical qubits — Wikipedia", "url": "https://en.wikipedia.org/wiki/Physical_and_logical_qubits"}, {"title": "Gidney, 'How to factor 2048 bit RSA integers with less than a million noisy qubits' (2025) — arXiv", "url": "https://arxiv.org/abs/2505.15917"}]}, {"section": "quantum", "title": "Encryption gets ready", "paras": ["Because of Shor's algorithm, NIST published its first post-quantum encryption standards in August 2024, based on math problems believed hard even for quantum computers. Organizations are migrating now, partly because data stolen today could be decrypted later."], "sources": [{"title": "NIST Post-Quantum Cryptography", "url": "https://csrc.nist.gov/projects/post-quantum-cryptography"}]}, {"section": "trail-hardware", "title": "From sand to silicon", "paras": ["Chips start as quartz sand, refined into extremely pure silicon. It is melted, and a single crystal is slowly pulled out as an ingot (the Czochralski method), then sliced into thin wafers and polished mirror-smooth."], "sources": [{"title": "Semiconductor device fabrication — Wikipedia", "url": "https://en.wikipedia.org/wiki/Semiconductor_device_fabrication"}, {"title": "Czochralski method — Wikipedia", "url": "https://en.wikipedia.org/wiki/Czochralski_method"}]}, {"section": "trail-hardware", "title": "Printing with light", "paras": ["Patterns are printed by photolithography: light shines through a mask onto a light-sensitive coating. The most advanced chips use extreme ultraviolet light of 13.5 nanometers, made by hitting tiny droplets of molten tin with a laser. ASML in the Netherlands is the only maker of these machines."], "sources": [{"title": "Extreme ultraviolet lithography — Wikipedia", "url": "https://en.wikipedia.org/wiki/Extreme_ultraviolet_lithography"}]}, {"section": "trail-hardware", "title": "Hundreds of steps", "paras": ["A modern chip goes through hundreds of steps of depositing, patterning, etching and doping, layer after layer, typically over weeks to months, inside clean rooms."], "sources": [{"title": "Semiconductor device fabrication — Wikipedia", "url": "https://en.wikipedia.org/wiki/Semiconductor_device_fabrication"}]}, {"section": "trail-hardware", "title": "Why '3 nanometer' isn't a size", "paras": ["Names like '3 nm' are now labels for a technology generation, not the size of any actual feature on the chip."], "sources": [{"title": "3 nm process — Wikipedia", "url": "https://en.wikipedia.org/wiki/3_nm_process"}]}, {"section": "trail-ai", "title": "Step 1: read a library the size of the internet", "paras": ["Pretraining: the model reads trillions of words and practices predicting the next small chunk of text (a 'token'). Each wrong guess nudges billions of internal numbers slightly, using backpropagation."], "sources": [{"title": "Large language model — Wikipedia", "url": "https://en.wikipedia.org/wiki/Large_language_model"}]}, {"section": "trail-ai", "title": "Step 2: learning to be helpful", "paras": ["A raw model just continues text. It becomes an assistant through fine-tuning on example conversations and then reinforcement learning from human feedback (RLHF) — which, as the ACM notes, is reinforcement learning, the field Sutton and Barto founded."], "sources": [{"title": "RLHF — Wikipedia", "url": "https://en.wikipedia.org/wiki/Reinforcement_learning_from_human_feedback"}, {"title": "ACM 2024 Turing Award", "url": "https://awards.acm.org/about/2024-turing"}]}, {"section": "trail-ai", "title": "Step 3: testing and red-teaming", "paras": ["Before release, labs test models for dangerous abilities and bad behavior and try to break them on purpose. Policies such as Anthropic's Responsible Scaling Policy set which checks are required."], "sources": [{"title": "Jared Kaplan — Wikipedia", "url": "https://en.wikipedia.org/wiki/Jared_Kaplan"}]}, {"section": "trail-ai", "title": "The cost", "paras": ["Frontier models train on many thousands of GPUs for weeks or months; reported costs run from tens to hundreds of millions of dollars."], "sources": [{"title": "Large language model — Wikipedia", "url": "https://en.wikipedia.org/wiki/Large_language_model"}]}, {"section": "trail-quantum", "title": "Superconducting circuits", "paras": ["Google and IBM use transmons — superconducting circuits with Josephson junctions, descendants of the 1985 Clarke–Devoret–Martinis experiment — cooled to about a hundredth of a degree above absolute zero."], "sources": [{"title": "Transmon — Wikipedia", "url": "https://en.wikipedia.org/wiki/Transmon"}, {"title": "Nobel Prize in Physics 2025 — NobelPrize.org", "url": "https://www.nobelprize.org/prizes/physics/2025/summary/"}]}, {"section": "trail-quantum", "title": "Single atoms", "paras": ["Trapped-ion machines (the Cirac–Zoller idea) hold charged atoms in electric fields and steer them with lasers. Neutral-atom machines hold uncharged atoms in focused laser 'tweezers'."], "sources": [{"title": "Trapped-ion quantum computer — Wikipedia", "url": "https://en.wikipedia.org/wiki/Trapped-ion_quantum_computer"}]}, {"section": "trail-quantum", "title": "Light, spins and exotic states", "paras": ["Other teams use photons, electron spins in silicon, or proposed 'topological' qubits. No one yet knows which approach will scale best."], "sources": [{"title": "Physical and logical qubits — Wikipedia", "url": "https://en.wikipedia.org/wiki/Physical_and_logical_qubits"}]}, {"section": "finale", "title": "AGI vs. ASI", "paras": ["AGI usually means AI that matches people at most thinking tasks; ASI means AI that far exceeds the best humans at nearly everything. There is no agreed test for either, and experts disagree widely on timelines."], "sources": [{"title": "Technological singularity — Wikipedia", "url": "https://en.wikipedia.org/wiki/Technological_singularity"}]}, {"section": "finale", "title": "The great debate", "paras": ["In May 2023 hundreds of researchers, including Hinton and Bengio, signed a one-sentence statement that reducing extinction risk from AI should be a global priority. Others, including LeCun and Sutton, call such fears overblown. Both sides include respected pioneers."], "sources": [{"title": "CAIS Statement on AI Risk", "url": "https://www.safe.ai/work/statement-on-ai-risk"}, {"title": "Existential risk from AI — Wikipedia", "url": "https://en.wikipedia.org/wiki/Existential_risk_from_artificial_intelligence"}]}, {"section": "finale", "title": "Weizenbaum's warning", "paras": ["Long before today's risk debate, Weizenbaum argued the real question isn't what computers can do but what we should let them decide. His worry was human judgment, not killer robots — a view many current critics echo."], "sources": [{"title": "Computer Power and Human Reason — Wikipedia", "url": "https://en.wikipedia.org/wiki/Computer_Power_and_Human_Reason"}]}, {"section": "finale", "title": "Full circle", "paras": ["Turing asked whether machines can think; Good asked what happens if they think better than us; Bostrom asked how we stay in control. The site ends on the question all three left open."], "sources": [{"title": "Computing Machinery and Intelligence — Wikipedia", "url": "https://en.wikipedia.org/wiki/Computing_Machinery_and_Intelligence"}]}, {"section": "transistor", "title": "The traitorous eight", "paras": ["In 1957 eight young scientists quit Shockley Semiconductor together: Julius Blank, Victor Grinich, Jean Hoerni, Eugene Kleiner, Jay Last, Gordon Moore, Robert Noyce and Sheldon Roberts.", "With funding from Fairchild Camera and Instrument they started Fairchild Semiconductor.", "People who left Fairchild went on to found dozens of companies, nicknamed 'Fairchildren'. Intel and AMD are the best known. Kleiner co-founded the venture firm Kleiner Perkins.", "This chain of spin-offs is a big reason Silicon Valley grew where it did."], "sources": [{"title": "Wikipedia: Traitorous eight", "url": "https://en.wikipedia.org/wiki/Traitorous_eight"}, {"title": "Wikipedia: Fairchild Semiconductor", "url": "https://en.wikipedia.org/wiki/Fairchild_Semiconductor"}, {"title": "Computer History Museum: Gordon Moore, CHM Fellow", "url": "https://computerhistory.org/profile/gordon-moore/"}]}, {"section": "transistor", "title": "Two inventors, one chip", "paras": ["Kilby at Texas Instruments (1958) and Noyce at Fairchild (1959) invented the integrated circuit independently.", "Kilby proved the idea: all parts made from one piece of semiconductor. Noyce made it practical: flat, sealed in oxide, and wired with metal on top.", "The CHM puts it plainly: Noyce's structure, by eliminating Kilby's 'flying-wire' connections, gave a practical way to manufacture Kilby's solid circuits.", "Their companies fought over patents for years, then cross-licensed. Today both men are credited."], "sources": [{"title": "Computer History Museum, The Silicon Engine: 1959 Practical Monolithic IC Concept Patented", "url": "https://www.computerhistory.org/siliconengine/practical-monolithic-integrated-circuit-concept-patented/"}, {"title": "NobelPrize.org: Jack S. Kilby, Biographical (his own account)", "url": "https://www.nobelprize.org/prizes/physics/2000/kilby/biographical/"}, {"title": "Wikipedia: Invention of the integrated circuit", "url": "https://en.wikipedia.org/wiki/Invention_of_the_integrated_circuit"}]}, {"section": "transistor", "title": "Busicom, a calculator, and the first microprocessor", "paras": ["Intel's first microprocessor started as a calculator job for Busicom of Japan.", "Intel built a four-chip family, the MCS-4: the 4001 (ROM), 4002 (RAM), 4003 (shift register) and the 4004 processor.", "In mid-1971 Busicom asked for lower prices. Intel agreed, and in return Busicom gave up its exclusive rights. Intel could now sell the 4004 to anyone.", "Intel announced it in November 1971 with ads promising 'a new era of integrated electronics'. It cost $60."], "sources": [{"title": "Computer History Museum, The Silicon Engine: 1971 Microprocessor Integrates CPU Function onto a Single Chip", "url": "https://www.computerhistory.org/siliconengine/microprocessor-integrates-cpu-function-onto-a-single-chip/"}, {"title": "Wikipedia: Intel 4004", "url": "https://en.wikipedia.org/wiki/Intel_4004"}, {"title": "Wikipedia: Busicom", "url": "https://en.wikipedia.org/wiki/Busicom"}]}, {"section": "transistor", "title": "Point-contact vs junction: why the first transistor didn't last", "paras": ["The first transistor used two gold points pressed onto germanium. It worked, but it was delicate and hard to make consistently.", "Shockley's junction transistor (conceived January 1948) used layers of semiconductor instead, building on the p-n junction Russell Ohl discovered in 1940.", "Junction transistors were sturdier and easier to mass-produce, so they took over the 1950s."], "sources": [{"title": "Computer History Museum, The Silicon Engine: 1947 Invention of the Point-Contact Transistor", "url": "https://www.computerhistory.org/siliconengine/invention-of-the-point-contact-transistor/"}, {"title": "Computer History Museum, The Silicon Engine: 1948 Conception of the Junction Transistor", "url": "https://www.computerhistory.org/siliconengine/conception-of-the-junction-transistor/"}]}, {"section": "switches", "title": "What Moore actually said", "paras": ["In 1965 Gordon Moore, then Fairchild's head of R&D, drew a line through five data points from 1959 to 1964. The number of components on the most cost-effective chip had been doubling about every year.", "He extrapolated ten years ahead: about 65,000 components per chip by 1975. That was a wild guess at the time, and it came true.", "In 1975 he revised the pace to a doubling about every two years. The '18 months' you often hear came from others, who mixed in speed gains, not Moore himself.", "Caltech's Carver Mead named it 'Moore's law'. It is an observation about engineering and economics, not a law of physics."], "sources": [{"title": "Computer History Museum, The Silicon Engine: 1965 Moore's Law Predicts the Future of ICs", "url": "https://www.computerhistory.org/siliconengine/moores-law-predicts-the-future-of-integrated-circuits/"}, {"title": "Computer History Museum catalog: Moore, 'Cramming more components onto integrated circuits' (1965)", "url": "https://www.computerhistory.org/collections/catalog/102770822"}, {"title": "Computer History Museum: Gordon Moore, CHM Fellow", "url": "https://computerhistory.org/profile/gordon-moore/"}, {"title": "Wikipedia: Moore's law", "url": "https://en.wikipedia.org/wiki/Moore%27s_law"}]}, {"section": "switches", "title": "Dennard scaling and the end of 'free' speed", "paras": ["In 1974 Robert Dennard and colleagues at IBM showed that when you shrink a transistor, you can shrink its voltage and current too, so the power used per area stays about the same.", "For thirty years that meant each new generation was smaller, faster and no hotter. Speed came almost for free.", "Around the mid-2000s this broke down: tiny transistors leak current even when 'off', and voltage could not keep dropping.", "Clock speeds stalled at a few gigahertz. Chipmakers switched to putting many cores side by side, which is why your phone has several processors in one chip."], "sources": [{"title": "Wikipedia: Dennard scaling", "url": "https://en.wikipedia.org/wiki/Dennard_scaling"}, {"title": "Wikipedia: Multi-core processor", "url": "https://en.wikipedia.org/wiki/Multi-core_processor"}]}, {"section": "switches", "title": "Why '3 nanometers' isn't 3 nanometers", "paras": ["Chip generations have names like '5 nm' or '3 nm'. Decades ago these matched a real physical size. Today they are mostly generation labels.", "The smallest features on a '3 nm' chip are bigger than 3 nanometers. The name tells you roughly where a process sits in the lineup, not what a ruler would measure."], "sources": [{"title": "Wikipedia: 3 nm process", "url": "https://en.wikipedia.org/wiki/3_nm_process"}, {"title": "Wikipedia: Semiconductor device fabrication", "url": "https://en.wikipedia.org/wiki/Semiconductor_device_fabrication"}]}, {"section": "switches", "title": "From 2,300 to billions: the scale in human terms", "paras": ["The 4004 of 1971 had about 2,300 transistors. Modern high-end chips have tens or hundreds of billions.", "That is roughly the jump from the population of a small village to many times the population of Earth, squeezed onto a chip about the size of a postage stamp.", "The trend held for so long because each step made chips cheaper per transistor, which paid for the next step."], "sources": [{"title": "Computer History Museum, The Silicon Engine: 1971 Microprocessor Integrates CPU Function onto a Single Chip", "url": "https://www.computerhistory.org/siliconengine/microprocessor-integrates-cpu-function-onto-a-single-chip/"}, {"title": "Wikipedia: Transistor count", "url": "https://en.wikipedia.org/wiki/Transistor_count"}]}, {"section": "dive", "title": "Photolithography: printing with light", "paras": ["Chips are made a bit like old-fashioned photographs. A silicon wafer is coated with a light-sensitive chemical called photoresist.", "Light shines through a mask, a stencil of one layer of the circuit, and lenses shrink the image onto the wafer.", "Where light lands, the resist changes and can be washed away. The bare areas are then etched, filled with metal, or treated with other atoms.", "Repeat this dozens of times, layer upon layer, and billions of transistors appear."], "sources": [{"title": "Wikipedia: Photolithography", "url": "https://en.wikipedia.org/wiki/Photolithography"}, {"title": "Wikipedia: Semiconductor device fabrication", "url": "https://en.wikipedia.org/wiki/Semiconductor_device_fabrication"}, {"title": "ASML: Light & lasers (lithography principles)", "url": "https://www.asml.com/en/technology/lithography-principles/light-and-lasers"}]}, {"section": "dive", "title": "Shorter light, smaller chips", "paras": ["The shorter the wavelength of light, the smaller the features you can print. ASML explains it like waves in the sea: the distance between peaks is the wavelength.", "Early machines used blue light at 436 nm from a mercury lamp. Later came deep-ultraviolet lasers; argon-fluoride lasers at 193 nm can print features of about 38 nm.", "The next jump was a leap: extreme ultraviolet light at just 13.5 nm."], "sources": [{"title": "ASML: Light & lasers (lithography principles)", "url": "https://www.asml.com/en/technology/lithography-principles/light-and-lasers"}]}, {"section": "dive", "title": "EUV: light from exploding tin", "paras": ["EUV light is so hard to make that it needed a radically new light source.", "Tiny droplets of molten tin, about 25 micrometers across, fly through a vacuum chamber at about 70 meters per second. A laser pulse flattens each droplet, then a second, stronger pulse blasts it into a glowing plasma that gives off EUV light.", "EUV is absorbed by air and by glass, so everything runs in vacuum and the light is steered by special multilayer mirrors made by Zeiss instead of lenses.", "A typical EUV machine weighs nearly 200 tons and costs on the order of US$180 million."], "sources": [{"title": "Wikipedia: Extreme ultraviolet lithography", "url": "https://en.wikipedia.org/wiki/Extreme_ultraviolet_lithography"}, {"title": "ASML: Light & lasers (lithography principles)", "url": "https://www.asml.com/en/technology/lithography-principles/light-and-lasers"}]}, {"section": "dive", "title": "ASML: one company, one bottleneck", "paras": ["ASML began in 1984 as a joint venture of Philips and ASM International, starting out in a shed near Philips buildings in Eindhoven, the Netherlands.", "In 2010 it shipped its first prototype EUV tool to a chipmaker's research site. In 2013 it bought Cymer, a San Diego maker of light sources, to speed up EUV.", "Today ASML is the only company that makes and sells EUV machines for chip production, which makes it one of the most important companies most people have never heard of."], "sources": [{"title": "ASML: Our history", "url": "https://www.asml.com/en/company/about-asml/history"}, {"title": "Wikipedia: ASML Holding", "url": "https://en.wikipedia.org/wiki/ASML_Holding"}]}, {"section": "personal", "title": "Xerox PARC: invented here, sold elsewhere", "paras": ["Xerox opened its Palo Alto Research Center in 1970. Bob Taylor built its Computer Science Laboratory.", "In just a few years PARC researchers built the Alto (1973), Ethernet, laser printing, WYSIWYG editing, Smalltalk and the overlapping-window GUI.", "Xerox sold a version, the Star, in 1981, but it was very expensive. Apple, after Jobs's 1979 visit, and later Microsoft brought the ideas to the mass market."], "sources": [{"title": "Internet Hall of Fame: Robert Taylor", "url": "https://www.internethalloffame.org/inductee/robert-taylor/"}, {"title": "Computer History Museum: Charles Thacker, CHM Fellow", "url": "https://computerhistory.org/profile/charles-thacker/"}, {"title": "Wikipedia: PARC", "url": "https://en.wikipedia.org/wiki/PARC_(company)"}, {"title": "Wikipedia: Xerox Alto", "url": "https://en.wikipedia.org/wiki/Xerox_Alto"}]}, {"section": "personal", "title": "The Homebrew Computer Club", "paras": ["A group of hobbyists began meeting in Menlo Park, California, in March 1975, soon after the Altair 8800 kit appeared.", "They swapped parts, ideas and circuit diagrams. Steve Wozniak showed his Apple I there.", "The club is a reminder that much of the personal computer came from hobbyists, not big companies."], "sources": [{"title": "Computer History Museum: Steve Wozniak, CHM Fellow", "url": "https://computerhistory.org/profile/steve-wozniak/"}, {"title": "Wikipedia: Homebrew Computer Club", "url": "https://en.wikipedia.org/wiki/Homebrew_Computer_Club"}]}, {"section": "personal", "title": "The IBM PC and the clone wars", "paras": ["IBM released its Personal Computer in August 1981, built mostly from off-the-shelf parts around an Intel 8088 chip.", "Because its parts were open, companies like Compaq built compatible 'clones'.", "Microsoft could license MS-DOS to all of them. That is how 'PC' became a standard rather than one company's product."], "sources": [{"title": "Wikipedia: IBM Personal Computer", "url": "https://en.wikipedia.org/wiki/IBM_Personal_Computer"}, {"title": "Wikipedia: IBM PC compatible", "url": "https://en.wikipedia.org/wiki/IBM_PC_compatible"}]}, {"section": "personal", "title": "The Mead–Conway revolution", "paras": ["Before about 1980, designing a chip required deep knowledge of the factory process. Mead and Conway's method separated design from manufacturing with simple, scalable rules.", "Students could now design chips, send them off, and get real silicon back. MOSIS (1981) made this a service.", "This 'fabless' idea — design here, build in someone else's factory — is how companies like Nvidia and Apple make chips today."], "sources": [{"title": "Computer History Museum: Lynn Conway, CHM Fellow", "url": "https://computerhistory.org/profile/lynn-conway/"}, {"title": "Wikipedia: Lynn Conway", "url": "https://en.wikipedia.org/wiki/Lynn_Conway"}]}, {"section": "network", "title": "ARPANET's first four nodes", "paras": ["By the end of 1969 ARPANET linked four sites: UCLA, the Stanford Research Institute, UC Santa Barbara and the University of Utah.", "Each site had an IMP, a small computer built by BBN, that handled the routing. This let very different host computers join without each needing to understand all the others."], "sources": [{"title": "Computer History Museum: Robert Kahn, CHM Fellow", "url": "https://computerhistory.org/profile/robert-kahn/"}, {"title": "Wikipedia: ARPANET", "url": "https://en.wikipedia.org/wiki/ARPANET"}]}, {"section": "network", "title": "Two inventors, one idea: packets", "paras": ["Paul Baran in the US (early 1960s) and Donald Davies in the UK (1965) independently came up with packet switching.", "Baran wanted survival under nuclear attack. Davies wanted efficient sharing for time-sharing computers. Different reasons, same answer.", "Davies's word, 'packet', won. Both are recognized by the National Inventors Hall of Fame."], "sources": [{"title": "Internet Hall of Fame: Paul Baran", "url": "https://www.internethalloffame.org/inductee/paul-baran/"}, {"title": "Internet Hall of Fame: Donald Davies", "url": "https://www.internethalloffame.org/inductee/donald-davies/"}, {"title": "National Inventors Hall of Fame: Donald Davies", "url": "https://www.invent.org/inductees/donald-watts-davies"}]}, {"section": "network", "title": "From ARPANET to the internet", "paras": ["ARPANET switched to TCP/IP on January 1, 1983. That date is often called the internet's birthday.", "NSFNET then connected universities across the US. ARPANET was retired in 1990, and commercial traffic opened up in the early 1990s."], "sources": [{"title": "Wikipedia: Internet protocol suite", "url": "https://en.wikipedia.org/wiki/Internet_protocol_suite"}, {"title": "Wikipedia: National Science Foundation Network", "url": "https://en.wikipedia.org/wiki/National_Science_Foundation_Network"}, {"title": "Internet Hall of Fame: J.C.R. Licklider", "url": "https://www.internethalloffame.org/inductee/jcr-licklider/"}]}, {"section": "network", "title": "The web is not the internet", "paras": ["The internet is the network of networks — the roads. The web is one thing that travels on it: pages joined by links.", "Email, video calls and online games also use the internet, without being the web."], "sources": [{"title": "Wikipedia: World Wide Web", "url": "https://en.wikipedia.org/wiki/World_Wide_Web"}, {"title": "W3C: Tim Berners-Lee biography", "url": "https://www.w3.org/People/Berners-Lee/"}]}, {"section": "origins", "title": "Before beads: counting boards and pebbles", "paras": ["The oldest counting tools were marks: notches on bones and sticks, and later clay tokens in Mesopotamia.", "The Salamis Tablet, a marble counting board found on the Greek island of Salamis in 1846, is the oldest counting board known to survive. Pebbles were moved between its lines; the Latin word for pebble, calculus, is where 'calculate' comes from.", "Bead abacuses came later and spread across the world, from the Chinese suanpan to the Japanese soroban, and are still used today."], "sources": [{"title": "Salamis Tablet", "url": "https://en.wikipedia.org/wiki/Salamis_Tablet"}, {"title": "Abacus", "url": "https://en.wikipedia.org/wiki/Abacus"}]}, {"section": "origins", "title": "Inside the Antikythera mechanism", "paras": ["The fragments contain around 30 surviving bronze gears, cut by hand.", "Turning a crank moved the date. Dials then showed the Sun and Moon, the Moon's phase, and on the back, an eclipse-prediction cycle and a calendar tracking the four-year cycle of the Greek athletic games.", "A clever pin-and-slot pair of gears made the Moon pointer speed up and slow down, copying the Moon's real uneven motion.", "The 2021 model from University College London proposes a full display of the known planets on the front, rebuilt from inscriptions and gear evidence."], "sources": [{"title": "Freeth et al. 2006, Nature", "url": "https://www.nature.com/articles/nature05357"}, {"title": "Freeth et al. 2021, Scientific Reports", "url": "https://www.nature.com/articles/s41598-021-84310-w"}, {"title": "Antikythera mechanism", "url": "https://en.wikipedia.org/wiki/Antikythera_mechanism"}]}, {"section": "origins", "title": "Why carrying was the hard problem", "paras": ["Adding one column is easy for gears. The trouble is the carry: 999,999 + 1 has to ripple through every wheel.", "Pascal's sautoir handled carries one by one with gravity. Leibniz's carry never worked properly. Babbage later spent years designing a mechanism to do all the carries at once.", "Modern chips face the same issue and use 'carry-lookahead' adders so they don't wait for carries to ripple, a distant echo of Pascal's problem."], "sources": [{"title": "Pascal's calculator", "url": "https://en.wikipedia.org/wiki/Pascal%27s_calculator"}, {"title": "Computer History Museum: The Babbage Engine", "url": "https://www.computerhistory.org/babbage/"}]}, {"section": "origins", "title": "From workshop to industry: the Arithmometer", "paras": ["For about 150 years, calculators stayed handmade curiosities. That changed with Thomas de Colmar's Arithmometer, patented in 1820 and manufactured from 1851.", "From 1851 to 1890 it was the only kind of mechanical calculator in commercial production. Insurers, banks and engineers bought it, and it launched an industry that built calculators into the 1970s."], "sources": [{"title": "Arithmometer", "url": "https://en.wikipedia.org/wiki/Arithmometer"}]}, {"section": "engines", "title": "How the method of differences works", "paras": ["Take the squares: 1, 4, 9, 16, 25. The gaps between them are 3, 5, 7, 9. The gaps between those gaps are always 2.", "So to get the next square, just add: 9 + 2 gives 11, and 25 + 11 gives 36. No multiplication needed.", "Any polynomial works the same way with enough levels of differences. Babbage's Difference Engine No. 2 holds eight numbers of 31 digits each, enough to tabulate seventh-degree polynomials."], "sources": [{"title": "Computer History Museum: The Engines", "url": "https://www.computerhistory.org/babbage/engines/"}, {"title": "Difference engine", "url": "https://en.wikipedia.org/wiki/Difference_engine"}]}, {"section": "engines", "title": "The Analytical Engine, part by part", "paras": ["Store: memory, built from columns of geared counters.", "Mill: the arithmetic unit, which could add, subtract, multiply and divide.", "Cards: operation cards said what to do and variable cards said which numbers to use, an early version of instructions and addresses.", "Branching: the engine could choose different cards depending on a result, the conditional jump every program uses."], "sources": [{"title": "Computer History Museum: The Babbage Engine", "url": "https://www.computerhistory.org/babbage/"}, {"title": "Menabrea's 'Sketch of the Analytical Engine' with Ada Lovelace's Notes (full text, 1843)", "url": "https://www.fourmilab.ch/babbage/sketch.html"}]}, {"section": "engines", "title": "The weavers of Lyon", "paras": ["Lyon's silk workers, the canuts, mostly worked in small family workshops, many on the slopes of La Croix-Rousse, weaving to order for merchants.", "When silk prices collapsed in 1831 and pay kept falling, they rose up. They rose again in 1834, and a third time in 1848. These are among the first clearly defined workers' uprisings of the industrial age.", "The Jacquard loom was part of their world. It made complex patterns faster and changed who did the work and what it was worth. Arguments over who benefits when machines take over skilled work have followed every wave of automation since, including AI today."], "sources": [{"title": "Canut revolts", "url": "https://en.wikipedia.org/wiki/Canut_revolts"}, {"title": "Science History Institute, 'The French Connection' (Jacquard's woven portrait)", "url": "https://www.sciencehistory.org/stories/magazine/the-french-connection/"}]}, {"section": "engines", "title": "The card that ran a century", "paras": ["Jacquard's cards controlled a loom. Babbage planned cards to control a calculating engine. Hollerith used cards to hold data: one card per person in the census.", "Hollerith's 1890 tabulator was wired specifically for census cards. A plugboard in his 1906 Type I Tabulator let operators rewire it for different jobs, a step toward programmability.", "IBM's punched cards went on to store payrolls, inventories and programs into the 1970s."], "sources": [{"title": "Computer History Museum: Hollerith's punched card solution", "url": "https://www.computerhistory.org/revolution/punched-cards/2/2"}, {"title": "IBM History: The punched card", "url": "https://www.ibm.com/history/punched-card"}, {"title": "Herman Hollerith", "url": "https://en.wikipedia.org/wiki/Herman_Hollerith"}]}, {"section": "theory", "title": "The halting problem, as a story", "paras": ["Imagine a perfect inspector program that reads any program and says 'this will finish' or 'this runs forever'.", "Now build a troublemaker: it asks the inspector about itself, and does the opposite. If told 'you'll finish', it loops forever; if told 'you'll loop', it stops.", "Either answer is wrong, so the perfect inspector cannot exist. That is Turing's 1936 result in plain words, and it is why no tool can catch every bug."], "sources": [{"title": "Turing, 'On Computable Numbers' (1936), original paper PDF", "url": "https://www.cs.virginia.edu/~robins/Turing_Paper_1936.pdf"}, {"title": "Stanford Encyclopedia of Philosophy: Turing Machines", "url": "https://plato.stanford.edu/entries/turing-machine/"}]}, {"section": "theory", "title": "Four answers to one question", "paras": ["In the mid-1930s several people independently pinned down what 'computable' means: Church with lambda calculus, Turing with machines, Gödel and Herbrand with recursive functions, and Post with his worker marking boxes.", "They turned out to be exactly equivalent: anything one can compute, the others can too.", "That agreement is why most researchers accept the Church–Turing thesis. It can't be proved like a theorem, because 'effectively calculable' is an informal idea. Post argued it should be treated as a working hypothesis that needs continual checking."], "sources": [{"title": "Stanford Encyclopedia of Philosophy: The Church–Turing Thesis", "url": "https://plato.stanford.edu/entries/church-turing/"}]}, {"section": "theory", "title": "What a 'bit' really measures", "paras": ["Shannon defined information as surprise. A fair coin flip carries exactly one bit. A coin that always lands heads carries none, because you already knew the answer.", "Ordinary text carries far less than eight bits per letter because letters are predictable. That gap is what compression exploits.", "His channel capacity theorem says every channel has a maximum reliable rate, and good enough codes can come close to it."], "sources": [{"title": "Shannon, 'A Mathematical Theory of Communication' (1948), original paper PDF", "url": "https://people.math.harvard.edu/~ctm/home/text/others/shannon/entropy/entropy.pdf"}, {"title": "Quanta Magazine on Shannon", "url": "https://www.quantamagazine.org/how-claude-shannons-information-theory-invented-the-future-20201222/"}]}, {"section": "theory", "title": "Analog vs. digital: Bush's machine and Shannon's switches", "paras": ["Bush's differential analyzer was analog: quantities were represented by how far shafts turned, so precision depended on how well the parts were made.", "Shannon's insight, gained while running that machine, was digital: a switch is simply on or off, so small imperfections don't pile up the same way.", "Within about a decade the digital approach won out."], "sources": [{"title": "Differential analyser", "url": "https://en.wikipedia.org/wiki/Differential_analyser"}, {"title": "MacTutor: Claude Shannon", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Shannon/"}]}, {"section": "theory", "title": "Lady Lovelace's objection, answered", "paras": ["In his 1950 paper Turing quoted Lovelace's claim that the Analytical Engine cannot originate anything, and called it 'Lady Lovelace's Objection'.", "His reply: machines often surprise him, and a learning machine, taught like a child, might come to do things its programmers never planned. The debate he started is the one we still have about AI today."], "sources": [{"title": "Stanford Encyclopedia of Philosophy: Alan Turing", "url": "https://plato.stanford.edu/entries/turing/"}, {"title": "Menabrea's 'Sketch of the Analytical Engine' with Ada Lovelace's Notes (full text, 1843)", "url": "https://www.fourmilab.ch/babbage/sketch.html"}]}, {"section": "codebreakers", "title": "How a crib-hunting Bombe actually thinks", "paras": ["A Bombe does not read messages. It proves settings wrong. Codebreakers guessed that a stretch of ciphertext hid a known phrase, such as 'WETTERVORHERSAGE' (weather forecast).", "Because Enigma never turned a letter into itself, they could slide the guess along the message and drop any position where a letter would land on itself.", "The guessed letter pairs were drawn as a 'menu', a loop diagram. The Bombe spun drums that copied Enigma rotors and stopped only when a setting fit every link. Welchman's diagonal board added more links for free.", "Each stop was then tested by hand on a replica Enigma. A good stop meant the day's traffic could be read."], "sources": [{"title": "The National Museum of Computing: The Turing-Welchman Bombe", "url": "https://www.tnmoc.org/bombe"}, {"title": "MacTutor: Gordon Welchman", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Welchman/"}]}, {"section": "codebreakers", "title": "Enigma versus Lorenz: two very different problems", "paras": ["Enigma was a portable rotor machine used by the army, navy and air force. Thousands of operators, many mistakes, and many cribs.", "Lorenz (codename Tunny) sent teleprinter traffic between Hitler's high command and generals. It added a stream of pseudo-random 'key' to each 5-bit character using 12 wheels.", "Breaking Lorenz needed statistics over huge amounts of text. That is why it needed Colossus, the first large electronic machine at Bletchley."], "sources": [{"title": "The National Museum of Computing: Colossus", "url": "https://www.tnmoc.org/colossus"}, {"title": "MacTutor: William Tutte", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Tutte/"}]}, {"section": "codebreakers", "title": "The Polish gift, July 1939", "paras": ["On 24–25 July 1939, weeks before the invasion, Polish codebreakers met British and French officers at Pyry near Warsaw.", "They handed over replica Enigmas and explained the bomba and perforated sheets. Bletchley's Dilly Knox, who had been stuck for years, was reportedly stunned.", "Without this head start, Bletchley would have begun the war years behind."], "sources": [{"title": "MacTutor: Marian Rejewski", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Rejewski/"}, {"title": "IEEE Milestone: Code-breaking at Bletchley Park, 1939-1945", "url": "https://ethw.org/Milestones:Code-breaking_at_Bletchley_Park_during_World_War_II,_1939-1945"}]}, {"section": "codebreakers", "title": "Traffic analysis: reading without reading", "paras": ["Even when a message couldn't be decrypted, its outside could be studied: who sent it, to whom, when, on what frequency and with what call sign.", "Gordon Welchman realised these patterns mapped the German command network. Changes in traffic could hint at an attack before a single word was read.", "Traffic analysis became a pillar of signals intelligence."], "sources": [{"title": "MacTutor: Gordon Welchman", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Welchman/"}]}, {"section": "electronic", "title": "Programming ENIAC with cables and switches", "paras": ["ENIAC had no keyboard and no stored program. A 'program' was a physical setup: patch cables linking units, and thousands of switches set by hand.", "Changing to a new problem could take days of rewiring. The six programmers worked from block diagrams and wrote out every step on paper first.", "They also found faults by tracing pulses through the machine, so they knew the hardware better than many engineers."], "sources": [{"title": "Penn Engineering: ENIAC", "url": "https://www.seas.upenn.edu/about/history-heritage/eniac/"}, {"title": "IEEE History Center oral history: Jean Bartik", "url": "https://ethw.org/Oral-History:Jean_Bartik"}]}, {"section": "electronic", "title": "From ENIAC to the stored program", "paras": ["ENIAC's limits led its team to plan EDVAC, which would store instructions in memory like data.", "Von Neumann's 1945 'First Draft' set out this plan. In 1948 ENIAC itself was rewired to run a simple stored-program instruction set, with help from Klára von Neumann and others.", "Britain's Manchester 'Baby' ran the first stored program on an electronic machine in June 1948."], "sources": [{"title": "von Neumann, First Draft of a Report on the EDVAC (Internet Archive)", "url": "https://archive.org/details/firstdraftofrepo00vonn"}, {"title": "MacTutor: John von Neumann", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Von_Neumann/"}]}, {"section": "electronic", "title": "The 1973 patent ruling", "paras": ["Eckert and Mauchly's ENIAC patent was struck down in Honeywell v. Sperry Rand (1973).", "The judge found that Mauchly had taken ideas from John Atanasoff's work at Iowa State, and that the patent had been filed too late after public use.", "The ruling put the basic idea of the electronic digital computer in the public domain."], "sources": [{"title": "MacTutor: John Mauchly", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Mauchly/"}]}, {"section": "electronic", "title": "The 'first computer' argument", "paras": ["The ABC (1939–42) was electronic and binary, but it solved only one kind of problem and could not be programmed.", "Colossus (1943–44) was electronic and could be configured with switches and plugs, but it was built for one job and stayed secret until the 1970s.", "ENIAC (1945–46) was electronic and general purpose, but it was programmed by rewiring. The Manchester Baby (June 1948) and EDSAC (May 1949) were among the first to run programs stored in memory.", "So 'first' depends on the definition. Each machine was first at something."], "sources": [{"title": "Wikipedia: Atanasoff–Berry computer", "url": "https://en.wikipedia.org/wiki/Atanasoff%E2%80%93Berry_computer"}, {"title": "The National Museum of Computing: Colossus", "url": "https://www.tnmoc.org/colossus"}, {"title": "TNMOC: EDSAC", "url": "https://www.tnmoc.org/edsac"}, {"title": "Wikipedia: Max Newman", "url": "https://en.wikipedia.org/wiki/Max_Newman"}]}, {"section": "electronic", "title": "Human computers before electronic ones", "paras": ["'Computer' was a job title. During the war the Moore School hired at least 200 women to calculate trajectories.", "Kay McNulty said one trajectory took 30 to 40 hours by hand, and each gun's firing table needed about 1,800 of them.", "ENIAC was built to replace that work. The women who did it became its first programmers."], "sources": [{"title": "MacTutor: Kathleen McNulty Antonelli", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Antonelli/"}, {"title": "Wikipedia: ENIAC", "url": "https://en.wikipedia.org/wiki/ENIAC"}]}, {"section": "software", "title": "What a compiler does, in plain words", "paras": ["Computers only understand machine code: long strings of numbers.", "A compiler is a translator program. You write 'X = A + B', and it produces the exact machine steps.", "Hopper's A-0 (1952) and FORTRAN (1957) proved that this translation could be done automatically, and that the result could be fast."], "sources": [{"title": "MacTutor: Grace Hopper", "url": "https://mathshistory.st-andrews.ac.uk/Biographies/Hopper/"}, {"title": "IBM: Fortran", "url": "https://www.ibm.com/history/fortran"}]}, {"section": "software", "title": "Unix philosophy", "paras": ["Unix programs are small and each does one job: list files, search text, count lines.", "The 'pipe' (|) lets you feed one program's output into another, so small tools build big tasks.", "Everything, from files to devices, looks like a stream of bytes. These ideas live on in Linux, macOS and Android."], "sources": [{"title": "Dennis Ritchie, 'The Evolution of the Unix Time-sharing System' (Bell Labs)", "url": "https://www.nokia.com/bell-labs/about/dennis-m-ritchie/hist.html"}]}, {"section": "software", "title": "Free and open source", "paras": ["Free software means freedom: to run, study, change and share code. Stallman wrote this down in the GPL.", "Open source, a term from 1998, focused on practical benefits rather than ethics.", "Today most of the internet runs on code anyone can read."], "sources": [{"title": "Free Software Foundation: About", "url": "https://www.fsf.org/about/"}, {"title": "GNU Project: Initial Announcement", "url": "https://web.archive.org/web/2015/http://www.gnu.org/gnu/initial-announcement.html"}]}];
